write.table(D1,file=paste0(dir,"/",name,".xls"),sep="\t", quote=F,row.names=T,append=T,col.names=NA)

}

else {

e1<-try({
name="25.BivMeans.dependent"
res<-oph.astig.depbivmeans(x)
for(i in 1:length(cmbn1)){
