dimnames(output)<-list(NULL,c('Var','Var','RMSAE 1','RMSAE 2','Dif','p.value','Adj.p.value'))
ic=0
for (j in 1:J){
for (k in 1:J){
if (j < k){
ic=ic+1
a=ydbt(x[,j]^2,x[,k]^2,tr=tr,nboot=nboot)
