# adrun

# ----------------------------------------------------------------------------

#' Additive Model via Running Interval Smoother
#'
#' @description
#' Fits a generalized additive model using running interval smoothers and the
#' backfitting algorithm. Models E(Y|X) as sum of smooth functions: f₁(X₁) + ... + fₚ(Xₚ).
#'
#' @param x Matrix of predictor variables (2 or more columns)
#' @param y Response vector
#' @param est Robust estimator function for smoothing (default: \code{\link{tmean}})
#' @param iter Maximum number of backfitting iterations (default: 10)
#' @param pyhat Logical. If \code{TRUE}, returns fitted values instead of plotting
#'   (default: \code{FALSE})
#' @param plotit Logical. If \code{TRUE} (default) and p=2, creates 3D plot of fitted surface
#' @param fr Span for running interval smoother (default: 1)
#' @param xlab Label for x-axis (default: 'X')
#' @param ylab Label for y-axis (default: 'Y')
#' @param zlab Label for z-axis (default: '')
#' @param theta Azimuthal viewing angle for 3D plot (default: 50)
#' @param phi Colatitude viewing angle for 3D plot (default: 25)
#' @param expand Expansion factor for z-axis (default: 0.5)
#' @param scale Logical. Scale x, y, z to unit box for 3D plot (default: \code{TRUE})
#' @param zscale Logical. Scale z-axis separately (default: \code{TRUE})
#' @param xout Logical. Remove multivariate outliers before fitting (default: \code{FALSE})
#' @param eout Logical. Remove outliers in residuals (default: same as \code{xout})
#' @param outfun Outlier detection function (default: \code{\link{out}})
#' @param ticktype Type of axis tickmarks for 3D plot (default: 'simple')
#' @param ... Additional arguments passed to estimator function
#'
#' @return
#' If \code{pyhat=TRUE}, returns vector of fitted values. Otherwise, creates plot
#' (for 2 predictors only) and returns fitted values invisibly.
#'
#' @details
#' The backfitting algorithm iteratively:
#' \enumerate{
#'   \item Initializes: f_j(X_j) = 0 for all j
#'   \item For each predictor j: computes partial residuals Y - Σ_{k≠j} f_k(X_k)
#'   \item Smooths partial residuals vs X_j using running interval smoother
#'   \item Repeats until convergence or \code{iter} iterations
#' }
#'
#' The running interval smoother uses \code{\link{runhat}} with robust estimator
#' \code{est}. For prediction at x₀, averages Y values where X is within distance
#' \code{fr × range(X)} from x₀.
#'
#' @references
#' Hastie, T. J., & Tibshirani, R. J. (1990). Generalized Additive Models.
#' Chapman and Hall/CRC.
#'
#' @seealso \code{\link{runhat}}, \code{\link{adtest}}, \code{\link{adcom}},
#'   \code{\link{adrunl}}, \code{\link{runm3d}}
#'
#' @keywords models regression smooth
#' @export
adrun<-function(x,y,est=tmean,iter=10,pyhat=FALSE,plotit=TRUE,fr=1,xlab='X',
ylab='Y',zlab='',
theta=50,phi=25,expand=.5,scale=TRUE,zscale=TRUE,xout=FALSE,eout=xout,outfun=out,ticktype='simple',...){
#
# additive model based on running interval smoother
# and backfitting algorithm
#
m<-elimna(cbind(x,y))
if(xout){
flag<-outfun(x,plotit=FALSE)$keep
x=x[flag,]
y=y[flag]
}
x<-as.matrix(x)
p<-ncol(x)
if(p==1)val<-rungen(x[,1],y,est=est,pyhat=TRUE,plotit=plotit,fr=fr,
xlab=xlab,ylab=ylab,...)$output
if(p>1){
np<-p+1
x<-m[,1:p]
y<-m[,np]
fhat<-matrix(NA,ncol=p,nrow=length(y))
fhat.old<-matrix(NA,ncol=p,nrow=length(y))
res<-matrix(NA,ncol=np,nrow=length(y))
dif<-1
for(i in 1:p)
fhat.old[,i]<-rungenv2(x[,i],y,est=est,pyhat=TRUE,plotit=FALSE,fr=fr,...)
eval<-NA
for(it in 1:iter){
for(ip in 1:p){
res[,ip]<-y
for(ip2 in 1:p){
if(ip2 != ip)res[,ip]<-res[,ip]-fhat.old[,ip2]
}
fhat[,ip]<-rungenv2(x[,ip],res[,ip],est=est,pyhat=TRUE,plotit=FALSE,fr=fr,...)
}
eval[it]<-sum(abs(fhat/sqrt(sum(fhat^2))-fhat.old/sqrt(sum(fhat.old^2))))
if(it > 1){
itm<-it-1
dif<-abs(eval[it]-eval[itm])
}
fhat.old<-fhat
if(dif<.01)break
}
val<-apply(fhat,1,sum)
aval<-est(y-val,...)
val<-val+aval
if(plotit && p==2){
fitr<-val
iout<-c(1:length(fitr))
nm1<-length(fitr)-1
for(i in 1:nm1){
ip1<-i+1
for(k in ip1:length(fitr))if(sum(x[i,]==x[k,])==2)iout[k]<-0
}
fitr<-fitr[iout>=1] # Eliminate duplicate points in the x-y plane
#                 This is necessary when doing three dimensional plots
#                 with the R function interp
mkeep<-x[iout>=1,]
fitr<-interp(mkeep[,1],mkeep[,2],fitr)
persp(fitr,theta=theta,phi=phi,xlab=xlab,ylab=ylab,zlab=zlab,expand=expand,
scale=scale,ticktype=ticktype)
}}
if(!pyhat)val<-'Done'
val
}

#' Additive Model Using Loess Smoother and Backfitting
#'
#' @description
#' Fits an additive regression model using loess smoothing and the backfitting
#' algorithm. For models of the form \eqn{Y = f_1(X_1) + ... + f_p(X_p) + e},
#' estimates each function iteratively.
#'
#' @param x Matrix of predictor variables (n by p).
#' @param y Vector of response values.
#' @param est Estimator function for centering (default: \code{\link{tmean}}).
#' @param iter Maximum number of backfitting iterations (default: 10).
#' @param pyhat Logical. If \code{TRUE}, returns predicted values; if \code{FALSE}, returns "Done".
#' @param plotit Logical. If \code{TRUE} and p=2, creates 3D perspective plot of fitted surface.
#' @param fr Span parameter for loess smoother (default: 0.8). Fraction of data used in local smoothing.
#' @param xlab Label for first predictor axis (default: "x1").
#' @param ylab Label for second predictor axis (default: "x2").
#' @param zlab Label for response axis (default: "").
#' @param theta Viewing angle for perspective plot (default: 50).
#' @param phi Viewing angle for perspective plot (default: 25).
#' @param expand Expansion factor for z-axis (default: 0.5).
#' @param scale Logical. If \code{TRUE}, scales z-axis to same range as x-y (default: FALSE).
#' @param zscale Logical (not currently used).
#' @param xout Logical (not currently used).
#' @param outfun Outlier detection function (default: \code{\link{out}}, not currently used).
#' @param ticktype Tick mark style for 3D plot (default: "simple").
#' @param ... Additional arguments passed to \code{est}.
#'
#' @details
#' Uses the backfitting algorithm to fit additive models:
#' \enumerate{
#'   \item Initialize each function \eqn{f_j} using loess smoother
#'   \item Iterate until convergence:
#'     \itemize{
#'       \item For each predictor j, compute residuals from other predictors
#'       \item Update \eqn{f_j} by smoothing residuals against \eqn{X_j}
#'     }
#'   \item Convergence criterion: change in normalized fitted values < 0.01
#' }
#'
#' For bivariate predictors (p=2), optionally creates 3D perspective plot of fitted surface
#' using \code{\link[akima]{interp}}.
#'
#' @return
#' If \code{pyhat=TRUE}, returns vector of predicted values.
#' If \code{pyhat=FALSE}, returns character string "Done".
#'
#' @seealso \code{\link{adrun}}, \code{\link{adtest}}, \code{\link{adtestl}}, \code{\link{lplot}}
#'
#' @references
#' Hastie, T. J., & Tibshirani, R. J. (1990). Generalized Additive Models. Chapman & Hall.
#'
#' @keywords regression robust smooth
#' @export
adrunl<-function(x,y,est=tmean,iter=10,pyhat=FALSE,plotit=TRUE,fr=.8,
xlab="x1",ylab="x2",zlab="",theta=50,phi=25,expand=.5,scale=FALSE,
zscale=TRUE,xout=FALSE,outfun=out,ticktype="simple",...){
#
# additive model based on running interval smoother
# and backfitting algorithm
#
m<-elimna(cbind(x,y))
x<-as.matrix(x)
p<-ncol(x)
if(p==1)val<-lplot(x[,1],y,pyhat=TRUE,plotit=plotit,span=fr,pr=FALSE)$yhat.values
if(p>1){
np<-p+1
x<-m[,1:p]
y<-m[,np]
fhat<-matrix(NA,ncol=p,nrow=length(y))
fhat.old<-matrix(NA,ncol=p,nrow=length(y))
res<-matrix(NA,ncol=np,nrow=length(y))
dif<-1
for(i in 1:p)
fhat.old[,i]<-lplot(x[,i],y,pyhat=TRUE,plotit=FALSE,span=fr,pr=FALSE)$yhat.values
eval<-NA
for(it in 1:iter){
for(ip in 1:p){
res[,ip]<-y
for(ip2 in 1:p){
if(ip2 != ip)res[,ip]<-res[,ip]-fhat.old[,ip2]
}
fhat[,ip]<-lplot(x[,ip],res[,ip],pyhat=TRUE,plotit=FALSE,span=fr,pr=FALSE)$yhat.values
}
eval[it]<-sum(abs(fhat/sqrt(sum(fhat^2))-fhat.old/sqrt(sum(fhat.old^2))))
if(it > 1){
itm<-it-1
dif<-abs(eval[it]-eval[itm])
}
fhat.old<-fhat
if(dif<.01)break
}
val<-apply(fhat,1,sum)
aval<-est(y-val,...)
val<-val+aval
if(plotit && p==2){
fitr<-val
iout<-c(1:length(fitr))
nm1<-length(fitr)-1
for(i in 1:nm1){
ip1<-i+1
for(k in ip1:length(fitr))if(sum(x[i,]==x[k,])==2)iout[k]<-0
}
fitr<-fitr[iout>=1] # Eliminate duplicate points in the x-y plane
#                 This is necessary when doing three dimensional plots
#                 with the R function interp
mkeep<-x[iout>=1,]
fitr<-interp(mkeep[,1],mkeep[,2],fitr)
persp(fitr,theta=theta,phi=phi,xlab=xlab,ylab=ylab,zlab=zlab,expand=expand,
scale=scale,ticktype=ticktype)
}}
if(!pyhat)val<-"Done"
val
}




# ----------------------------------------------------------------------------

# adtest

# ----------------------------------------------------------------------------

#' Test for Additive Model Using Running Interval Smoother
#'
#' @description
#' Tests the hypothesis that a regression model is additive (no interaction terms)
#' using a variation of the Stute et al. (1998) method with running interval
#' smoothing and backfitting algorithm.
#'
#' @param x Matrix of predictor variables (n by p, p >= 2).
#' @param y Vector of response values.
#' @param est Estimator function for smoother (default: \code{\link{tmean}}).
#' @param nboot Number of bootstrap samples (default: 100).
#' @param alpha Significance level (default: 0.05).
#' @param fr Span parameter for running interval smoother. If \code{NA} (default),
#'   automatically selected based on sample size (for p=2 only).
#' @param xout Logical. If \code{TRUE}, removes outliers before testing (default: FALSE).
#' @param outfun Outlier detection function (default: \code{\link{out}}).
#' @param SEED Logical. If \code{TRUE}, sets random seed to 2 for reproducibility.
#' @param ... Additional arguments passed to \code{est} and \code{outfun}.
#'
#' @details
#' Tests \eqn{H_0: Y = f_1(X_1) + ... + f_p(X_p)} versus the alternative that
#' interaction terms are needed. Uses bootstrap to estimate null distribution of
#' test statistics.
#'
#' Two test statistics are computed:
#' \itemize{
#'   \item \strong{D-statistic}: Maximum absolute value of residual process
#'   \item \strong{W-statistic}: Mean squared residual process
#' }
#'
#' Automatic span selection (when \code{fr=NA} and p=2):
#' \itemize{
#'   \item n <= 150: Uses interpolation from empirically determined values
#'   \item n > 150: Uses formula 7.57/n + 0.05
#' }
#'
#' @return
#' List with components:
#' \item{dstat}{Observed D-statistic value}
#' \item{wstat}{Observed W-statistic value}
#' \item{p.value.d}{P-value for D-statistic}
#' \item{p.value.w}{P-value for W-statistic}
#'
#' @seealso \code{\link{adtestl}}, \code{\link{adtestv2}}, \code{\link{adrun}}
#'
#' @references
#' Stute, W., González Manteiga, W., & Presedo Quindimil, M. (1998). Bootstrap
#' approximations in model checks for regression. Journal of the American
#' Statistical Association, 93(441), 141-149.
#'
#' @keywords htest regression robust
#' @export
adtest<-function(x,y,est=tmean,nboot=100,alpha=.05,fr=NA,xout=FALSE,outfun=out,SEED=TRUE,...){
#
# Test the hypothesis that the regression model is additive.
# Use a variation of Stute et al. (1998, JASA, 93, 141-149).
# method, and running interval version of the backfitting
# algorithm
#
x=as.matrix(x)
if(ncol(x)==1)stop("There should be two or more predictors")
temp<-cbind(x,y)
p<-ncol(x)
p1<-p+1
temp<-elimna(temp)
x<-temp[,1:p]
x<-as.matrix(x)
y<-temp[,p1]
if(xout){
keepit<-rep(TRUE,nrow(x))
flag<-outfun(x,plotit=FALSE,...)$out.id
keepit[flag]<-FALSE
x<-x[keepit,]
y<-y[keepit]
}
if(alpha<.05 && nboot<=100)warning("You used alpha<.05 and nboot<=100")
if(is.na(fr)){
fr<-.8
if(ncol(x)==2){
nval<-c(20,30,50,80,150)
fval<-c(0.40,0.36,0.18,0.15,0.09)
if(length(y)<=150)fr<-approx(nval,fval,length(y))$y
if(length(y)>150)fr<-7.57/length(y)+.05
}
}
if(SEED)set.seed(2)
x<-as.matrix(x)
mflag<-matrix(NA,nrow=length(y),ncol=length(y))
for (j in 1:length(y)){
for (k in 1:length(y)){
mflag[j,k]<-(sum(x[j,]<=x[k,])==ncol(x))
}
}
yhat<-adrun(x,y,est=est,plotit=FALSE,fr=fr,pyhat=TRUE)
regres<-y-yhat
print("Taking bootstrap samples, please wait.")
data<-matrix(runif(length(y)*nboot),nrow=nboot)
data<-sqrt(12)*(data-.5) # standardize the random numbers.
rvalb<-apply(data,1,adtests1,yhat,regres,mflag,x,fr)
# An n x nboot matrix of R values
rvalb<-rvalb/sqrt(length(y))
dstatb<-apply(abs(rvalb),2,max)
wstatb<-apply(rvalb^2,2,mean)
v<-c(rep(1,length(y)))
rval<-adtests1(v,yhat,regres,mflag,x,fr)
rval<-rval/sqrt(length(y))
dstat<-max(abs(rval))
wstat<-mean(rval^2)
p.value.d<-1-sum(dstat>=dstatb)/nboot
p.value.w<-1-sum(wstat>=wstatb)/nboot
list(dstat=dstat,wstat=wstat,p.value.d=p.value.d,p.value.w=p.value.w)
}

#' Test for Additive Model Using Loess Smoother
#'
#' @description
#' Tests the hypothesis that a regression model is additive (no interaction terms)
#' using a variation of the Stute et al. (1998) method with loess smoothing and
#' backfitting algorithm.
#'
#' @param x Matrix of predictor variables (n by p, p >= 2).
#' @param y Vector of response values.
#' @param est Estimator function for smoother (default: \code{\link{tmean}}).
#' @param nboot Number of bootstrap samples (default: 100).
#' @param alpha Significance level (default: 0.05).
#' @param fr Span parameter for loess smoother. If \code{NA} (default),
#'   automatically selected based on sample size (for p=2 only).
#' @param SEED Logical. If \code{TRUE}, sets random seed to 2 for reproducibility.
#' @param ... Additional arguments passed to \code{est}.
#'
#' @details
#' Similar to \code{\link{adtest}} but uses loess smoothing instead of running
#' interval smoothing. Tests \eqn{H_0: Y = f_1(X_1) + ... + f_p(X_p)} versus
#' the alternative that interaction terms are needed.
#'
#' Two test statistics are computed:
#' \itemize{
#'   \item \strong{D-statistic}: Maximum absolute value of residual process
#'   \item \strong{W-statistic}: Mean squared residual process
#' }
#'
#' Automatic span selection (when \code{fr=NA} and p=2):
#' \itemize{
#'   \item n <= 400: Uses interpolation from empirically determined values
#'   \item n > 400: Uses constant value of 0.01
#' }
#'
#' @return
#' List with components:
#' \item{dstat}{Observed D-statistic value}
#' \item{wstat}{Observed W-statistic value}
#' \item{p.value.d}{P-value for D-statistic}
#' \item{p.value.w}{P-value for W-statistic}
#'
#' @seealso \code{\link{adtest}}, \code{\link{adtestv2}}, \code{\link{adrunl}}
#'
#' @references
#' Stute, W., González Manteiga, W., & Presedo Quindimil, M. (1998). Bootstrap
#' approximations in model checks for regression. Journal of the American
#' Statistical Association, 93(441), 141-149.
#'
#' @keywords htest regression robust
#' @export
adtestl<-function(x,y,est=tmean,nboot=100,alpha=.05,fr=NA,SEED=TRUE,...){
#
# Test the hypothesis that the regression model is additive.
# Use a variation of Stute et al. (1998, JASA, 93, 141-149).
# method, and running interval version of the backfitting
# algorithm
#
if(!is.matrix(x))stop("X values should be stored in a matrix")
if(ncol(x)==1)stop("There should be two or more predictors")
temp<-cbind(x,y)
p<-ncol(x)
p1<-p+1
temp<-elimna(temp)
x<-temp[,1:p]
x<-as.matrix(x)
y<-temp[,p1]
if(alpha<.05 && nboot<=100)warning("You used alpha<.05 and nboot<=100")
if(is.na(fr)){
fr<-.8
if(ncol(x)==2){
nval<-c(20,30,50,80,150)
fval<-c(0.40,0.36,0.18,0.15,0.09)
if(length(y)<=150)fr<-approx(nval,fval,length(y))$y
if(length(y)>150)fr<-.09
}
}
if(SEED)set.seed(2)
x<-as.matrix(x)
mflag<-matrix(NA,nrow=length(y),ncol=length(y))
for (j in 1:length(y)){
for (k in 1:length(y)){
mflag[j,k]<-(sum(x[j,]<=x[k,])==ncol(x))
}
}
yhat<-adrunl(x,y,plotit=FALSE,fr=fr,pyhat=TRUE)
regres<-y-yhat
print("Taking bootstrap sample, please wait.")
data<-matrix(runif(length(y)*nboot),nrow=nboot)
data<-sqrt(12)*(data-.5) # standardize the random numbers.
rvalb<-apply(data,1,adtestls1,yhat,regres,mflag,x,fr)
# An n x nboot matrix of R values
rvalb<-rvalb/sqrt(length(y))
dstatb<-apply(abs(rvalb),2,max)
wstatb<-apply(rvalb^2,2,mean)
dstatb<-sort(dstatb)
wstatb<-sort(wstatb)
# compute test statistic
v<-c(rep(1,length(y)))
rval<-adtestls1(v,yhat,regres,mflag,x,fr)
rval<-rval/sqrt(length(y))
dstat<-max(abs(rval))
wstat<-mean(rval^2)
ib<-round(nboot*(1-alpha))
critd<-dstatb[ib]
critw<-wstatb[ib]
list(dstat=dstat,wstat=wstat,critd=critd,critw=critw)
}




# ----------------------------------------------------------------------------

# adtestls1

# ----------------------------------------------------------------------------

#' Helper Function for adtestl Bootstrap
#'
#' @description
#' Internal helper function used by \code{\link{adtestl}} to compute bootstrap
#' residual process values using loess smoother.
#'
#' @param vstar Bootstrap multiplier vector.
#' @param yhat Fitted values from additive model.
#' @param res Residuals from additive model.
#' @param mflag Matrix indicating coordinate-wise ordering.
#' @param x Matrix of predictor variables.
#' @param fr Span parameter for loess smoother.
#'
#' @return Vector of residual process values.
#'
#' @keywords internal
adtestls1<-function(vstar,yhat,res,mflag,x,fr){
ystar<-yhat+res*vstar
bres<-adrunl(x,ystar,fr=fr,pyhat=TRUE,plotit=FALSE)
bres<-ystar-bres
rval<-0
for (i in 1:nrow(x)){
rval[i]<-sum(bres[mflag[,i]])
}
rval
}




