#' Coarse Grid Confidence Interval for Trimmed Mean
#'
#' Computes a robust confidence interval using a two-stage trimmed mean (T_S,n)
#' with coarse grid trimming levels. Automatically selects trimming based on outliers.
#'
#' @param x Numeric vector of data values
#' @param alpha Significance level (default: 0.05 for 95% CI)
#' @param ks Number of MADs for outlier detection (default: 3.5)
#'
#' @return List with components:
#'   \item{int}{Confidence interval c(lower, upper)}
#'   \item{tp}{Trimming proportion selected (0, 0.01, 0.1, 0.25, 0.4, or 0.49)}
#'
#' @details
#' First detects outliers using median ± ks×MAD. Based on proportion of outliers,
#' selects trimming level from coarse grid: 0, 1%, 10%, 25%, 40%, or 49%.
#' Computes CI using scaled Winsorized variance.
#'
#' @seealso \code{\link{trimci}} for standard trimmed mean CI
#'
#' @keywords robust univariate
#' @export
cgci<-function(x, alpha = 0.05, ks = 3.5)
{
#gets T_S,n with a coarse grid
# and the corresponding robust  100 (1-alpha)% CI
	n <- length(x)
	up <- 1 - alpha/2
	med <- median(x)
	madd <- mad(x, constant = 1)
	d <- sort(x)	##get robust T_S,n CI
	lo <- sum(x < (med - ks * madd))
	hi <- sum(x > (med + ks * madd))
	tp <- max(hi, lo)/n
	if(tp == 0)
		tp <- 0
	if(tp > 0 && tp <= 0.01)
		tp <- 0.01
	if(tp > 0.01 && tp <= 0.1)
		tp <- 0.1
	if(tp > 0.1 && tp <= 0.25)
		tp <- 0.25
	if(tp > 0.25 && tp <= 0.4)
		tp <- 0.4
	if(tp > 0.4)
		tp <- 0.49
	tstmn <- mean(x, trim = tp)
	#have obtained the two stage trimmed mean
	ln <- floor(n * tp)
	un <- n - ln
	if(ln > 0) {
		d[1:ln] <- d[(ln + 1)]
		d[(un + 1):n] <- d[un]
	}
	den <- ((un - ln)/n)^2
	swv <- var(d)/den
	#got the scaled Winsorized variance
	rdf <- un - ln - 1
	rval <- qt(up, rdf) * sqrt(swv/n)
	tslo <- tstmn - rval
	tshi <- tstmn + rval
	##got low and high endpoints of robust T_S,n CI
	list(int = c(tslo, tshi), tp = tp)
}

#' Asymptotic Variance for LTS and LTA at Cauchy Distribution
#'
#' Computes asymptotic variance for the Least Trimmed Squares (LTS) and
#' Least Trimmed sum of Absolute deviations (LTA) estimators when errors
#' follow a Cauchy(0,1) distribution.
#'
#' @param gam Limiting proportion h/n (default: 0.5 for 50% trimming)
#'
#' @return Returns two values (via \code{return()}):
#'   \item{ltsv}{Asymptotic variance for LTS(h)}
#'   \item{ltav}{Asymptotic variance for LTA(h)}
#'
#' @details
#' Theoretical asymptotic variances for heavy-tailed (Cauchy) errors.
#' Useful for understanding robustness properties of LTS/LTA estimators.
#'
#' @keywords robust regression
#' @export
cltv<-
function(gam = 0.5)
{
# Gets asy var for lts(h) and lta(h)at Cauchy C(0,1)
# where h/n -> gam.
	k <- tan((pi * gam)/2)
	num <- 2 * k - pi * gam
	den <- pi * (gam - (2 * k)/(pi * (1 + k^2)))^2
	ltsv <- num/den
	num <- gam
	den <- 4 * (1/pi - 1/(pi * (1 + k^2)))^2
	ltav <- num/den
	return(ltsv, ltav)
}

#' COVMBA Estimator with Multiple Trimming Levels
#'
#' Computes the COVMBA (COVariance Modified MBA) estimator using concentration
#' algorithm with multiple trimming levels (98%, 95%, 90%, 80%, 70%, 60%, 50%).
#'
#' @param x Numeric data matrix (n × p)
#' @param csteps Number of concentration steps (default: 5)
#' @param ii Starting trimming level index (default: 1 for 98%)
#'
#' @return List with components:
#'   \item{center}{Robust center estimate (p-vector)}
#'   \item{cov}{Robust covariance matrix (p × p)}
#'   \item{mds}{Matrix of Mahalanobis distances for each trimming level}
#'
#' @details
#' Tries multiple trimming levels and selects the one giving smallest determinant.
#' Includes interactive plotting for diagnostics. Scales result for better MVN performance.
#'
#' @seealso \code{\link{covmba}}, \code{\link{covdgk}}
#'
#' @keywords robust multivariate
#' @export
cmba2<-
function(x, csteps = 5, ii = 1)
{
# gets the covmba estimator using 98, 95, 90, 80, 70, 60 and 50% trimming
	n <- dim(x)[1]
	p <- dim(x)[2]
	mds <- matrix(nrow = n, ncol = 8, 0)	##get the DGK estimator
	covs <- var(x)
	mns <- apply(x, 2, mean)
	cmd <- sqrt(mahalanobis(x, mns, covs))	## concentrate
	for(i in 1:csteps) {
		md2 <- mahalanobis(x, mns, covs)
		medd2 <- median(md2)
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])
	}
	mds[, 8] <- sqrt(mahalanobis(x, mns, covs))
	covb <- covs
	mnb <- mns	##get the square root of det(covb)
	critb <- prod(diag(chol(covb)))	##get the resistant estimator
	covv <- diag(p)
	med <- apply(x, 2, median)
	md2 <- mahalanobis(x, center = med, covv)
	smd2 <- sort(md2)
	val <- p + 3
	tem <- 1:7
	tem[1] <- smd2[val + floor(0.02 * n)]
	tem[2] <- smd2[val + floor(0.05 * n)]
	tem[3] <- smd2[val + floor(0.1 * n)]
	tem[4] <- smd2[val + floor(0.2 * n)]
	tem[5] <- smd2[val + floor(0.3 * n)]
	tem[6] <- smd2[val + floor(0.4 * n)]
	tem[7] <- median(md2)
	medd2 <- tem[7]
	for(j in ii:7) {
## get the start
		val2 <- tem[j]
		mns <- apply(x[md2 <= val2,  ], 2, mean)
		covs <- var(x[md2 <= val2,  ])	## concentrate
		for(i in 1:csteps) {
			md2 <- mahalanobis(x, mns, covs)
			medd2 <- median(md2)
			mns <- apply(x[md2 <= medd2,  ], 2, mean)
			covs <- var(x[md2 <= medd2,  ])
		}
		mds[, j] <- sqrt(mahalanobis(x, mns, covs))
		plot(cmd, mds[, j])
		identify(cmd, mds[, j])
		crit <- prod(diag(chol(covs)))
		if(crit < critb) {
			critb <- crit
			covb <- covs
			mnb <- mns
		}
	}
	pairs(mds)	##scale for better performance at MVN
	rd2 <- mahalanobis(x, mnb, covb)
	const <- median(rd2)/(qchisq(0.5, p))
	covb <- const * covb
	list(center = mnb, cov = covb, mds = mds)
}

#' Find LTA Attractor Using Concentration Algorithm
#'
#' Finds the LTA (Least Trimmed sum of Absolute deviations) attractor starting
#' from a given initial coefficient vector using a concentration algorithm.
#'
#' @param x Design matrix (without intercept column)
#' @param y Response vector
#' @param start Starting coefficient vector (default: L1 regression fit)
#'
#' @return List with components:
#'   \item{coef}{Final coefficient vector (intercept and slopes)}
#'   \item{ct}{Number of concentration steps performed}
#'
#' @details
#' Iteratively refits L1 regression to observations with smallest absolute residuals
#' (h = ceiling(n/2) observations) until convergence of the LTA objective function.
#'
#' @seealso \code{\link{l1fit}}, \code{\link{ltareg}}
#'
#' @keywords robust regression
#' @export
conc2<-
function(x, y, start = l1fit(x, y)$coef)
{   #Finds that LTA attractor of the start.
	nc <- dim(x)[2] + 1
	res <- y - (x %*% start[2:nc] + start[1])
	ares <- abs(res)
	cov <- ceiling(length(y)/2)
	m <- sort(ares, partial = cov)[cov]
	old <- sum(ares[ares <= m])
	new <- old - 1
	ct <- 0
	while(new < old) {
		ct <- ct + 1
		start <- l1fit(x[ares <= m,  ], y[ares <=
			m])$coef
		res <- y - (x %*% start[2:nc] + start[1
			])
		ares <- abs(res)
		m <- sort(ares, partial = cov)[cov]
		new <- sum(ares[ares <= m])	#print(old)
		if(new < old) {
			old <- new
			new <- new - 1
		}
	}
	list(coef = start, ct = ct)
}

#' Demonstrate Concentration Algorithm in 2D (Interactive)
#'
#' Interactive demonstration showing how the concentration algorithm works for
#' robust multivariate location/covariance estimation in 2 dimensions.
#'
#' @param n Sample size (default: 100)
#' @param csteps Number of concentration steps (default: 5)
#' @param gam Proportion of outliers if \code{outliers = TRUE} (default: 0.4)
#' @param outliers Logical: include outliers in simulation? (default: TRUE)
#' @param start Starting method: 1 = DGK, 2 = MBA sphere, 3 = MBA MAD (default: 2)
#'
#' @return No return value; creates interactive plots showing concentration steps
#'
#' @details
#' Generates bivariate data (possibly with outliers), then iteratively applies
#' concentration algorithm. At each step, plots data with highlighted "good" points
#' (those within median Mahalanobis distance). Interactive via \code{identify}.
#'
#' @seealso \code{\link{covmba}}, \code{\link{covdgk}}
#'
#' @keywords robust multivariate
#' @export
concmv<-
function(n = 100, csteps = 5, gam = 0.4, outliers = TRUE, start = 2)
{
#Shows how concentration works when p = 2.
# Use start = 1 for DGK, start = 2 for MBA sphere, start = 3 for MBA MAD
	p <- 2	#A <- cbind(c(1, 0.9), c(0.9, 1))
	x <- matrix(rnorm(n * p), ncol = p, nrow = n)	#A <- diag(sqrt(1:p))
#if(outliers == T) {
# val <- floor(gam * n)
# tem <- 10 + 0 * 1:p
# x[1:val,  ] <- x[1:val,  ] + tem
#}
#x <- x %*% A
	A <- cbind(c(1, 0.4), c(0.4, 1))
	B <- cbind(c(0.5, 0), c(0, 0.5))
	if(outliers == T) {
		val <- floor(gam * n)
		x[(val + 1):n,  ] <- x[(val + 1):n,  ] %*% A
		x[1:val,  ] <- x[1:val,  ] %*% B
		x[1:val, 1] <- x[1:val, 1] + 0
		x[1:val, 2] <- x[1:val, 2] + 6
	}
	else {
		x <- x %*% A
	}
	if(start == 1) {
		covs <- var(x)
		mns <- apply(x, 2, mean)
	}
	if(start == 2) {
		covv <- diag(p)
		med <- apply(x, 2, median)
		md2 <- mahalanobis(x, center = med, covv)
		medd2 <- median(md2)	## get the start
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])
	}
	if(start >= 2) {
		tem <- apply(x, 2, mad)^2
		covv <- diag(tem)
		med <- apply(x, 2, median)
		md2 <- mahalanobis(x, center = med, covv)
		medd2 <- median(md2)	## get the start
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])
	}
## concentrate
	for(i in 1:csteps) {
		md2 <- mahalanobis(x, mns, covs)
		medd2 <- median(md2)
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])
		plot(x[, 1], x[, 2])
		points(x[md2 <= medd2, 1], x[md2 <= medd2, 2], pch = 15)
		identify(x[, 1], x[, 2])
	}
}

#' Simulation Study: Outlier Separation Performance
#'
#' Simulation to determine how often different robust estimators (MBA, DGK, MCD, etc.)
#' successfully separate outliers from non-outliers based on DD (distance-distance) plots.
#'
#' @param n Sample size (default: 100)
#' @param p Number of dimensions (default: 2)
#' @param steps Number of concentration steps (default: 5)
#' @param gam Proportion of outliers (default: 0.4)
#' @param runs Number of simulation runs (default: 20)
#'
#' @return List with components counting successful separation for each method:
#'   \item{mbact}{MBA (with multiple starts) success count}
#'   \item{fmcdct}{Fast MCD success count}
#'   \item{dgkct}{DGK success count}
#'   \item{mbct}{Median ball start success count}
#'   \item{madct}{MAD start success count}
#'
#' @details
#' In each run, generates data with outliers at mean (10, 10√2, ..., 10√p).
#' Counts how often min(RD_outliers) > max(RD_good) for each estimator.
#'
#' @keywords robust multivariate
#' @export
concsim<-
function(n = 100, p = 2, steps = 5, gam = 0.4, runs = 20)
{
# This Splus function is used to determine when the DD
# plot separates outliers from non-outliers for various starts.
	A <- sqrt(diag(1:p))
	mbact <- 0
	fmcdct <- 0
	mbct <- 0
	madct <- 0
	dgkct <- 0
	for(i in 1:runs) {
		x <- matrix(rnorm(n * p), ncol = p, nrow = n)
	## outliers have mean (10, 10 sqrt(2), ..., 10 sqrt(p))^T
		val <- floor(gam * n)
		tem <- 10 + 0 * 1:p
		x[1:val,  ] <- x[1:val,  ] + tem
		x <- x %*% A	#MBA
		out <- covmba(x, csteps = steps)
		center <- out$center
		cov <- out$cov
		rd2 <- mahalanobis(x, center, cov)
		if(min(rd2[1:val]) > max(rd2[(val + 1):n]))
mbact <- mbact + 1
	#DGK
		covs <- var(x)
		mns <- apply(x, 2, mean)	## concentrate
		for(i in 1:steps) {
			md2 <- mahalanobis(x, mns, covs)
			medd2 <- median(md2)
			mns <- apply(x[md2 <= medd2,  ], 2, mean)
			covs <- var(x[md2 <= medd2,  ])
		}
		rd2 <- mahalanobis(x, mns, covs)
		if(min(rd2[1:val]) > max(rd2[(val + 1):n])) dgkct <- dgkct + 1
	#Median Ball start
		covv <- diag(p)
		med <- apply(x, 2, median)
		md2 <- mahalanobis(x, center = med, covv)
		medd2 <- median(md2)	## get the start
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])	## concentrate
		for(i in 1:steps) {
			md2 <- mahalanobis(x, mns, covs)
			medd2 <- median(md2)
			mns <- apply(x[md2 <= medd2,  ], 2, mean)
			covs <- var(x[md2 <= medd2,  ])
		}
		rd2 <- mahalanobis(x, mns, covs)
		if(min(rd2[1:val]) > max(rd2[(val + 1):n])) mbct <- mbct + 1
	#MAD start
		tem <- apply(x, 2, mad)^2
		covv <- diag(tem)
		md2 <- mahalanobis(x, center = med, covv)
		medd2 <- median(md2)	## get the start
		mns <- apply(x[md2 <= medd2,  ], 2, mean)
		covs <- var(x[md2 <= medd2,  ])	## concentrate
		for(i in 1:steps) {
			md2 <- mahalanobis(x, mns, covs)
			medd2 <- median(md2)
			mns <- apply(x[md2 <= medd2,  ], 2, mean)
			covs <- var(x[md2 <= medd2,  ])
		}
		rd2 <- mahalanobis(x, mns, covs)
		if(min(rd2[1:val]) > max(rd2[(val + 1):n])) madct <- madct + 1
	#FMCD
		out <- cov.mcd(x)
		center <- out$center
		cov <- out$cov
		rd2 <- mahalanobis(x, center, cov)
		if(min(rd2[1:val]) > max(rd2[(val + 1):n]))
			fmcdct <- fmcdct + 1
	}
	list(mbact = mbact, fmcdct = fmcdct, dgkct = dgkct, mbct = mbct, madct
		 = madct)
}

#' Simulation: Correlation Between Classical and Robust Distances
#'
#' Generates replicate samples and computes correlations between classical
#' Mahalanobis distances (MD) and robust distances (RD) using different estimators.
#'
#' @param n Sample size (default: 100)
#' @param p Number of dimensions (default: 3)
#' @param eps Contamination parameter for outlier generation (default: 0.4, currently unused)
#' @param nruns Number of simulation runs (default: 100)
#' @param type Robust estimator: 1 = covmba, 2 = rmba, 3 = cov.mcd (default: 1)
#'
#' @return List with components:
#'   \item{cmean}{Mean correlation across runs}
#'   \item{cmin}{Minimum correlation}
#'   \item{clt95}{Count of correlations < 0.95}
#'   \item{clt80}{Count of correlations < 0.80}
#'   \item{corrs}{Vector of all correlations}
#'
#' @details
#' Each run generates MVN data, computes MD and RD (scaled to match at median),
#' then correlates them. High correlation indicates good agreement.
#'
#' @keywords robust multivariate
#' @export
corrsim<-
function(n = 100, p = 3, eps = 0.4, nruns = 100, type = 1)
{
#For R, first type "library(lqs)" before using this function
# This function generates 100 n by p matrices x.
# The output is the 100 sample correlations between the MDi and RDi
# RDi uses covmba for type = 1, rmba for type = 2, cov.mcd for type = 3
# mahalanobis gives squared Maha distances
	corrs <- 1:nruns
	for(i in 1:nruns) {
		wt <- 0 * (1:n)
		x <- matrix(rnorm(n * p), ncol = p, nrow = n)
	#The following 3 commands make x elliptically contoured.
#zu <- runif(n)
#x[zu < eps,] <- x[zu < eps,]*5
#x <- x^2
# To make marginals of x lognormal, use
#x <- exp(x)
		center <- apply(x, 2, mean)
		cov <- var(x)
		md2 <- mahalanobis(x, center, cov)
		if(type == 1) {
			out <- covmba(x)
		}
		if(type == 2) {
			out <- rmba(x)
		}
		if(type == 3) {
			out <- cov.mcd(x)
		}
		center <- out$center
		cov <- out$cov
		rd2 <- mahalanobis(x, center, cov)
	# need square roots for the usual distances
		md <- sqrt(md2)
		rd <- sqrt(rd2)
		const <- sqrt(qchisq(0.5, p))/median(rd)
		rd <- const * rd
	# wt[rd < sqrt(qchisq(0.975, p))] <- 1
#  corrs[i] <- cor(md[wt > 0], rd[wt > 0])}
		corrs[i] <- cor(md, rd)
	}
	cmean <- mean(corrs)
	cmin <- min(corrs)
	clt95 <- sum(corrs < 0.95)
	clt80 <- sum(corrs < 0.8)
	list(cmean = cmean, cmin = cmin, clt95 = clt95, clt80 = clt80,
		corrs = corrs)
}


#' Scaled DGK Multivariate Location and Covariance Estimator
#'
#' Computes the DGK (Donoho-Gasko-based) robust multivariate location and
#' covariance estimator using a concentration algorithm, with scaling for MVN consistency.
#'
#' @param x Numeric data matrix (n × p)
#' @param csteps Number of concentration steps (default: 10)
#'
#' @return List with components:
#'   \item{center}{Robust center estimate (p-vector)}
#'   \item{cov}{Robust covariance matrix (p × p), scaled for consistency at MVN}
#'
#' @details
#' Starts from classical mean/covariance, then iteratively concentrates on observations
#' within median Mahalanobis distance. Final covariance scaled by median(RD²)/χ²(0.5, p).
#'
#' @seealso \code{\link{covmba}}, \code{\link{cmba2}}
#'
#' @keywords robust multivariate
#' @export
covdgk<-
function(x, csteps = 10)
{
#computes the scaled DGK multivariate estimator
	p <- dim(x)[2]
	covs <- var(x)
	mns <- apply(x, 2, mean)	## concentrate
	for(i in 1:csteps) {
		md2 <- mahalanobis(x, mns, covs)
		medd2 <- median(md2)
		mns <- apply(x[md2 <= medd2,  ], 2,
			mean)
		covs <- var(x[md2 <= medd2,  ])
	}
##scale for consistency at MVN
	rd2 <- mahalanobis(x, mns, covs)
	const <- median(rd2)/(qchisq(0.5, p))
	covs <- const * covs
	list(center = mns, cov = covs)
}

#' Find Constants for Breakdown and Rejection in Robust Estimation
#'
#' Computes constants c1 and M that achieve a specified breakdown point r
#' and rejection probability alpha for robust multivariate estimation.
#'
#' @param n Sample size
#' @param p Number of dimensions
#' @param r Desired breakdown point (will be capped at maximum achievable: (n-p)/(2n))
#' @param alpha Desired rejection probability
#' @param asymp Logical: use asymptotic (vs finite-sample) maximum breakdown? (default: FALSE)
#'
#' @return List with components:
#'   \item{c1}{Constant c1}
#'   \item{M}{Constant M}
#'   \item{r1}{Achieved breakdown point (may equal input r)}
#'
#' @details
#' Uses Newton-Raphson iteration to solve for c1 and M satisfying breakdown and
#' rejection constraints. If rejection is not achievable, sets c1 = 0.
#'
#' @seealso \code{\link{rejpt.bt.lim}}, \code{\link{erho.bt}}
#'
#' @keywords robust multivariate
#' @export
cgen.bt <- function(n,p,r,alpha,asymp=FALSE){
#   find constants c1 and M that gives a specified breakdown r
#   and rejection point alpha
if (asymp == FALSE){if (r > (n-p)/(2*n) ) r <- (n-p)/(2*n)}
# maximum achievable breakdown
#
#   if rejection is not achievable, use c1=0 and best rejection
#
    limvec <- rejpt.bt.lim(p,r)
    if (1-limvec[2] <= alpha)
    {
        c1 <- 0
        M <- sqrt(qchisq(1-alpha,p))
    }
    else
    {
    c1.plus.M <- sqrt(qchisq(1-alpha,p))
    M <- sqrt(p)
    c1 <- c1.plus.M - M
    iter <- 1
    crit <- 100
    eps <- 1e-5
    while ((crit > eps)&(iter<100))
    {
        deps <- 1e-4
        M.old <- M
        c1.old <- c1
        er <- erho.bt(p,c1,M)
        fc <- er - r*(M^2/2+c1*(5*c1+16*M)/30)
        fcc1 <- (erho.bt(p,c1+deps,M)-er)/deps
        fcM  <- (erho.bt(p,c1,M+deps)-er)/deps
        fcp <- fcM - fcc1 - r*(M-(5*c1+16*M)/30+c1*9/30)
        M <- M - fc/fcp
        if (M >= c1.plus.M ){M <- (M.old + c1.plus.M)/2}
        c1 <- c1.plus.M - M
#        if (M-c1 < 0)  M <- c1.old+(M.old-c1.old)/2
        crit <- abs(fc)
        iter <- iter+1
    }
    }
list(c1=c1,M=M,r1=r)
}




