idk=j
idcost=k
}}}
# Now check to see whether cost matters for the kernel that is being used
temp=NA
for(k in 1:length(cost))temp[k]=comdepthsvm(x1,x2,kernel=kvals[idk],cost=cost[k])$est.prob
if(var(temp)==0)flag=FALSE
