# dbetabin

# ----------------------------------------------------------------------------

#' Beta-Binomial Probability Mass Function
#'
#' @description
#' Computes the probability mass function for the beta-binomial distribution,
#' which models overdispersed binomial data.
#'
#' @param x Number of successes (non-negative integer)
#' @param n Number of trials (positive integer)
#' @param r First shape parameter of the beta distribution (positive)
#' @param s Second shape parameter of the beta distribution (positive)
#'
#' @return
#' The probability P(X = x) for the beta-binomial distribution with parameters
#' n, r, and s.
#'
#' @details
#' The beta-binomial distribution arises when the probability of success in a
#' binomial trial follows a beta(r, s) distribution. It is useful for modeling
#' extra-binomial variation (overdispersion).
#'
#' The computation uses log-gamma functions for numerical stability:
#' \deqn{P(X=x) = \frac{\Gamma(n+1)\Gamma(r+x)\Gamma(n+s-x)\Gamma(r+s)}{\Gamma(x+1)\Gamma(n-x+1)\Gamma(r+s+n)\Gamma(r)\Gamma(s)}}
#'
#' @examples
#' \dontrun{
#' dbetabin(3, 10, 2, 5)  # P(X=3) with n=10, r=2, s=5
#' }
#'
#' @references
#' Johnson, N. L., Kemp, A. W., & Kotz, S. (2005). Univariate Discrete
#' Distributions (3rd ed.). Wiley.
#'
#' @keywords distribution
#' @export
dbetabin<-function(x,n,r,s){
#
# probability function for the beta-binomial distribution
#
v=lgamma(n+1)+lgamma(r+x)+lgamma(n+s-x)+lgamma(r+s)-lgamma(x+1)-lgamma(n-x+1)-lgamma(r+s+n)-lgamma(r)-lgamma(s)
v=exp(v)
v
}

#' Robust Regression with Interaction Term and Confidence Intervals
#'
#' @description
#' Performs robust regression with a two-way interaction term (product of two
#' independent variables). Computes bootstrap confidence intervals for all
#' regression coefficients including the interaction effect.
#'
#' @param x Matrix or data frame of predictors
#' @param y Response variable vector
#' @param regfun Regression function to use (default: \code{tsreg})
#' @param ID Vector of length 2 indicating which columns of x to use for
#'   interaction term (default: c(1,2))
#' @inheritParams regci
#' @param method Outlier detection method: 'PRO' (projection, default), 'PRO.R'
#'   (projection random), 'BLP' (regression-based), 'DUM' (dummy variable),
#'   'MCD' (robust Mahalanobis), or 'BOX' (boxplot, univariate only)
#' @param LABELS Logical: use variable labels from data (default: FALSE)
#' @param not.out Deprecated parameter (use CI instead)
#' @param CI Columns to ignore when checking for outliers (required when method='DUM')
#' @param MC Logical: use multicore parallel processing (default: FALSE)
#' @param pr Logical: print messages (default: TRUE)
#' @param xout Logical: remove outliers before analysis (default: FALSE)
#' @param outfun Outlier detection function (default: \code{outpro})
#' @param ... Additional arguments passed to regression function
#'
#' @return
#' A list with components:
#' \item{output}{Matrix of results with rows for Intercept, x1, x2, x1*x2, and
#'   any additional predictors. Columns: ci.low, ci.up, Estimate, S.E., p-value, p.adj}
#' \item{n}{Original sample size}
#' \item{n.keep}{Sample size after removing outliers (if xout=TRUE)}
#'
#' @details
#' This function:
#' \enumerate{
#'   \item Rearranges data so columns specified by ID are first
#'   \item Creates interaction term (product of first two columns)
#'   \item Optionally removes outliers based on specified method
#'   \item Fits robust regression model with interaction
#'   \item Computes bootstrap confidence intervals for all coefficients
#' }
#'
#' The model fitted is: y ~ x1 + x2 + x1*x2 + other predictors
#'
#' @examples
#' \dontrun{
#' x <- matrix(rnorm(100), ncol=2)
#' y <- x[,1] + 2*x[,2] + 0.5*x[,1]*x[,2] + rnorm(50)
#' regci.inter(x, y)
#' }
#'
#' @seealso \code{\link{regci}}, \code{\link{regciMC}}, \code{\link{tsreg}},
#'   \code{\link{out.methods}}
#'
#' @keywords regression robust
#' @export
regci.inter<-
function(x,y, regfun = tsreg, ID=c(1,2),nboot = 599, alpha = 0.05,method='PRO',
SEED = TRUE,LABELS=FALSE,not.out=NULL,CI=NULL,MC=FALSE,
    pr = TRUE, xout = FALSE, outfun = outpro, ...){

# A function for dealing with the usual regression interaction
# model where the product of  two independent variables is used.
#
#. ID indicates the two columns for which a product term is used.
# The function rearranges the data so that the first two columns are the two
# the will be used with their product.
#
# CI : columns ignored when checking for outliers and when using method='DUM'
#
#. When checking for leverage points, argument
#  method indicate the method used;
#PRO=outpro(x,plotit=plotit),         # projection method
#    PRO.R=outpro.depth(x),   #projection method   random, lower execution time vs outpro
#    BLP=outblp(x,y,regfun=regfun,plotit=FALSE),       # regression method
#    DUM=out.dummy(x,y,outfun=outpro.depth,id=id),   #   Detect outliers ignoring  col indicated by #argument id
#    MCD=outDETMCD(x,plotit=plotit),      use   robust analog of Mahalanobis distance
 #   BOX=outbox(x) boxplot (univariate only).
#
if(pr){
print('Assume the first two columns of x are to be used for an interaction. ')
print('If not the case, use  argument ID to indicate the appropriate columns')
}
p=ncol(x)
p11=p+1
p22=p+2
p1=p+3
if(is.null(p))stop('Should have two or more independent variables')
xy<-cbind(x,y)
xy<-elimna(xy)
x<-xy[,1:p]
y<-xy[,p11]
xsub=x[,-ID]
xID=x[,ID]
x=cbind(xID,xsub)
if(xout){
if(identical(method,'DUM')){
if(is.null(CI))stop('When using DUM, must specify the columns to be ignored via CI')
}
KE=out.methods(x,y,method=method,id=CI)$keep
x=x[KE,]
y=y[KE]
}
xx=cbind(x[,1:2],x[,1]*x[,2])
if(p>2)xx=cbind(x,x[,3:p])
vlabs=c('Intercept','x1','x2','x1*x2')
if(p>2){
p4=p+2
for(j in 5:p4)vlabs[j]=paste('x',j-1)
if(LABELS)vlabs[5:p4]=labels(x)[[2]][3:p]
}
clabs=c('ci.low','ci.up','Estimate','S.E.','p-value','p.adj')
if(!MC)a=regci(xx,y,regfun = regfun, nboot = nboot, alpha =alpha, SEED = SEED, pr =pr,...)
if(MC)a=regciMC(xx,y,regfun = regfun, nboot = nboot, alpha =alpha, SEED = SEED, pr =pr,...)
output=a$regci
dimnames(output)=list(vlabs,clabs)
list(output=output,n=a$n,n.keep=a$n.keep)
}

#' ANOVA for Dependent Groups Using Depth-Based Bootstrap Method
#'
#' @description
#' Performs one-way ANOVA for dependent groups using a partially centered depth-based
#' bootstrap method. Uses weighted grand mean to handle heteroscedasticity.
#'
#' @param x Data in list mode or matrix. If list, x[[j]] contains data for group j.
#'   If matrix, columns represent groups. All groups must have equal sample sizes.
#' @param est Robust estimator function (default: \code{onestep})
#' @inheritParams common_params
#' @param grp Optional vector specifying subset of groups to analyze (default: all groups)
#' @param nboot Number of bootstrap samples (default: 500)
#' @param plotit Logical: create plot for two-group case (default: TRUE)
#' @param pr Logical: print warning messages (default: TRUE)
#' @param WT Logical: use weighted grand mean (default: TRUE)
#' @param ... Additional arguments passed to estimator function
#'
#' @return
#' A list with components:
#' \item{p.value}{Significance level based on bootstrap depth}
#' \item{center}{Vector of robust location estimates for each group}
#' \item{grand.mean}{Weighted grand mean (repeated J times)}
#'
#' @details
#' This function implements a depth-based ANOVA for dependent groups:
#' \enumerate{
#'   \item Computes robust location estimates for each group
#'   \item Generates bootstrap samples and computes bootstrap estimates
#'   \item Calculates weighted grand mean (if WT=TRUE) using inverse variances
#'   \item Computes Mahalanobis depth of grand mean relative to bootstrap distribution
#'   \item P-value is proportion of bootstrap samples with depth ≤ grand mean depth
#' }
#'
#' For J=2, creates a scatterplot showing bootstrap distribution and confidence region.
#'
#' **Warning**: May not be level robust when J is large and n is small. The function
#' \code{rmmismcp} is currently preferred.
#'
#' @examples
#' \dontrun{
#' x <- matrix(rnorm(50), ncol=5)  # 5 dependent groups, n=10
#' ddep(x)
#' }
#'
#' @seealso \code{\link{ddeptr}}, \code{\link{rmmismcp}}, \code{\link{onestep}}
#'
#' @keywords htest robust multivariate
#' @export
ddep<-function(x,est=onestep,alpha=.05,grp=NA,nboot=500,plotit=TRUE,SEED=TRUE,pr=TRUE,WT=TRUE,...){
#
#   Do ANOVA on dependent groups
#   using the partially centered method plus
#   depth of zero among  bootstrap values.
#
#   An improved version of ddep that better handles heteroscedasticity
#   (A weighted grand mean is used in this version.)
#
#   The data are assumed to be stored in x in list mode
#   or in a matrix. In the first case
#   x[[1]] contains the data for the first group, x[[2]] the data
#   for the second group, etc. Length(x)=the number of groups = J.
#   If stored in a matrix, columns correspond to groups.
#
#   grp is used to specify some subset of the groups, if desired.
#   By default, all J groups are used.
#
#   The default number of bootstrap samples is nboot=2000
#
if(pr)print("Warning: Might not be level robust if the number of groups is relatively large and n is small")
if(pr)print("Currently seems that rmmismcp is preferable")
if(is.list(x)){
nv<-NA
for(j in 1:length(x))nv[j]<-length(x[[j]])
if(var(nv) !=0){
stop("The groups are stored in list mode and appear to have different sample sizes")
}
temp<-matrix(NA,ncol=length(x),nrow=nv[1])
for(j in 1:length(x))temp[,j]<-x[[j]]
x<-temp
}
J<-ncol(x)
if(!is.na(grp[1])){ #Select the groups of interest
J<-length(grp)
for(j in 1:J)temp[,j]<-x[,grp[j]]
x<-temp
}
x<-elimna(x) # Remove any rows with missing values.
bvec<-matrix(0,ncol=J,nrow=nboot)
hval<-vector("numeric",J)
if(SEED)set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
print("Taking bootstrap samples. Please wait.")
n<-nrow(x)
totv<-apply(x,2,est,na.rm=TRUE,...)
data<-matrix(sample(n,size=n*nboot,replace=TRUE),nrow=nboot)
for(ib in 1:nboot)bvec[ib,]<-apply(x[data[ib,],],2,est,na.rm=TRUE,...) #nboot by J matrix
if(!WT){
gv<-rep(mean(totv),J) #Grand mean
#m1<-rbind(bvec,gv)
}
bplus<-nboot+1
center<-totv
cmat<-var(bvec)
if(WT){
wt=1/diag(cmat)
ut=sum(wt)
gv<-rep(sum(wt*totv)/ut,J) #Grand mean
}
m1<-rbind(bvec,gv)
discen<-mahalanobis(m1,totv,cmat)
#print("Bootstrap complete; computing significance level")
if(plotit && ncol(x)==2){
plot(bvec,xlab="Group 1",ylab="Group 2")
temp.dis<-order(discen[1:nboot])
ic<-round((1-alpha)*nboot)
xx<-bvec[temp.dis[1:ic],]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,])
lines(xx[c(temp[1],temp[length(temp)]),])
abline(0,1)
}
sig.level<-sum(discen[bplus]<=discen)/bplus
list(p.value=sig.level,center=totv,grand.mean=gv)
}




# ----------------------------------------------------------------------------

# ddeptr

# ----------------------------------------------------------------------------

#' ANOVA for Dependent Groups Using Trimmed Means and Depth-Based Bootstrap
#'
#' @description
#' Performs one-way ANOVA for dependent groups comparing trimmed means using a
#' depth-based bootstrap method with weighted grand mean. Similar to \code{ddep}
#' but specifically for trimmed means.
#'
#' @param x Data in list mode or matrix. If list, x[[j]] contains data for group j.
#'   If matrix, columns represent groups. All groups must have equal sample sizes
#'   (unless na.rm=FALSE).
#' @param na.rm Logical: remove rows with missing values (default: TRUE). If FALSE,
#'   uses all data assuming missing completely at random.
#' @inheritParams common_params
#' @param grp Optional vector specifying subset of groups to analyze (default: all groups)
#' @param nboot Number of bootstrap samples (default: 500)
#' @param plotit Logical: create plot for two-group case (default: TRUE)
#' @param op Logical: print progress messages (default: FALSE)
#' @param ... Additional arguments (currently not used)
#'
#' @return
#' A list with components:
#' \item{p.value}{Significance level based on bootstrap depth}
#' \item{center}{Vector of trimmed means for each group}
#' \item{weighted.grand.mean}{Weighted grand mean using inverse squared standard errors}
#'
#' @details
#' This function uses the same depth-based approach as \code{\link{ddep}} but
#' specifically compares trimmed means:
#' \enumerate{
#'   \item Computes trimmed means for each group
#'   \item Generates bootstrap samples and computes bootstrap trimmed means
#'   \item Calculates weighted grand mean using inverse squared trimmed SEs as weights
#'   \item Computes Mahalanobis depth of grand mean relative to bootstrap distribution
#'   \item P-value is proportion of bootstrap samples with depth ≤ grand mean depth
#' }
#'
#' The weighted grand mean helps handle heteroscedasticity among marginal distributions.
#'
#' For J=2, creates a scatterplot showing bootstrap distribution with confidence region.
#'
#' @examples
#' \dontrun{
#' x <- matrix(rnorm(50), ncol=5)  # 5 dependent groups, n=10
#' ddeptr(x, tr=0.2)
#' }
#'
#' @seealso \code{\link{ddep}}, \code{\link{rmmismcp}}, \code{\link{tmean}},
#'   \code{\link{trimse}}
#'
#' @keywords htest robust multivariate
#' @export
ddeptr<-function(x,na.rm=TRUE,alpha=.05,grp=NA,nboot=500,plotit=TRUE,SEED=TRUE,op=FALSE,tr=.2,...){
#
#   Do ANOVA on dependent groups
#   using the partially centered method plus
#   depth of zero among  bootstrap values.
#
#  The method is like the method used by the R function ddep,
#  but a weighted estimate of the grand mean is used.
#  This helps deal the heteroscedasticity among the marginal distributions.
#
#   The data are assumed to be stored in x in list mode
#   or in a matrix. In the first case
#   x[[1]] contains the data for the first group, x[[2]] the data
#   for the second group, etc. Length(x)=the number of groups = J.
#   If stored in a matrix, columns correspond to groups.
#
#  trimmed means are compared
#
#   grp is used to specify some subset of the groups, if desired.
#   By default, all J groups are used.
#
#   The default number of bootstrap samples is nboot=500
#
#   na.rm=T, all rows of data with missing values are removed.
#   na.rm=F will use all of the data assuming missing values occur at random
#
if(is.list(x)){
nv<-NA
for(j in 1:length(x))nv[j]<-length(x[[j]])
if(var(nv) !=0){
stop("The groups are stored in list mode and appear to have different sample sizes")
}
temp<-matrix(NA,ncol=length(x),nrow=nv[1])
for(j in 1:length(x))temp[,j]<-x[[j]]
x<-temp
}
J<-ncol(x)
if(!is.na(grp[1])){ #Select the groups of interest
J<-length(grp)
for(j in 1:J)temp[,j]<-x[,grp[j]]
x<-temp
}
if(na.rm)x<-elimna(x) # Remove any rows with missing values.
bvec<-matrix(0,ncol=J,nrow=nboot)
hval<-vector("numeric",J)
if(SEED)set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
if(op)print("Taking bootstrap samples. Please wait.")
n<-nrow(x)
wt=apply(x,2,trimse,...)
wt=1/wt^2
ut=sum(wt)
totv<-apply(x,2,tmean,na.rm=TRUE,...)
gv<-rep(sum(wt*totv)/ut,J) #Weighted grand mean
data<-matrix(sample(n,size=n*nboot,replace=TRUE),nrow=nboot)
for(ib in 1:nboot)bvec[ib,]<-apply(x[data[ib,],],2,tmean,na.rm=TRUE,...) #nboot by J matrix
bplus<-nboot+1
m1<-rbind(bvec,gv)
center<-totv
cmat<-var(bvec)
discen<-mahalanobis(m1,totv,cmat)
if(op)print("Bootstrap complete; computing significance level")
if(plotit && ncol(x)==2){
plot(bvec,xlab="Group 1",ylab="Group 2")
temp.dis<-order(discen[1:nboot])
ic<-round((1-alpha)*nboot)
xx<-bvec[temp.dis[1:ic],]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,])
lines(xx[c(temp[1],temp[length(temp)]),])
abline(0,1)
}
sig.level<-sum(discen[bplus]<=discen)/bplus
list(p.value=sig.level,center=totv,weighted.grand.mean=gv[1])
}


#' Decile Comparisons for 2×2 Interactions (Factor A)
#'
#' @description
#' For a two-way (J×K) design, performs decile-based comparisons of all relevant
#' Factor A interactions using the contrasts from \code{con2by2A}.
#'
#' @param J Number of levels for Factor A
#' @param K Number of levels for Factor B
#' @param x Data in matrix or list mode. If matrix, will be converted to list.
#' @inheritParams common_params
#' @param q Vector of quantiles to compare (default: deciles 0.1 to 0.9)
#' @param nboot Number of bootstrap samples (default: 1000)
#' @param method P-value adjustment method (default: "BH" for Benjamini-Hochberg)
#'
#' @return
#' A list with components:
#' \item{A}{List of results from \code{\link{decinter}} for each interaction contrast}
#' \item{con}{Contrast matrix from \code{\link{con2by2A}}}
#'
#' @details
#' This function examines interactions by comparing multiple quantiles (deciles by default)
#' for Factor A in a 2×2 design. It uses the Type A contrasts generated by \code{con2by2A}
#' to define relevant interactions.
#'
#' @seealso \code{\link{dec2by2.B}}, \code{\link{decinter}}, \code{\link{con2by2A}},
#'   \code{\link{dec2way.mcp}}
#'
#' @keywords htest robust
#' @export
dec2by2.A<-function(J,K,x,alpha = 0.05, q = c(1:9)/10, nboot = 1000, SEED = TRUE,
    method = "BH"){
#
# For every relevant interaction, compare multiple quantiles
#
if(is.matrix(x))x=listm(x)
INT=list()
JK=J*K
CO=con2by2A(J,K)$conA
for( j in 1:ncol(CO)){
id=which(CO[,j]!=0)
X=x[id]
INT[[j]]=decinter(X,alpha=alpha,q=q,nboot=nboot,SEED=SEED,method=method)
}
list(A=INT,con=CO)
}




# ----------------------------------------------------------------------------

# dec2by2.B

# ----------------------------------------------------------------------------

#' Decile Comparisons for 2×2 Interactions (Factor B)
#'
#' @description
#' For a two-way (J×K) design, performs decile-based comparisons of all relevant
#' Factor B interactions using the contrasts from \code{con2by2B}.
#'
#' @param J Number of levels for Factor A
#' @param K Number of levels for Factor B
#' @param x Data in matrix or list mode. If matrix, will be converted to list.
#' @inheritParams common_params
#' @param q Vector of quantiles to compare (default: deciles 0.1 to 0.9)
#' @param nboot Number of bootstrap samples (default: 1000)
#' @param method P-value adjustment method (default: "BH" for Benjamini-Hochberg)
#'
#' @return
#' A list with components:
#' \item{B}{List of results from \code{\link{decinter}} for each interaction contrast}
#' \item{con}{Contrast matrix from \code{\link{con2by2B}}}
#'
#' @details
#' This function examines interactions by comparing multiple quantiles (deciles by default)
#' for Factor B in a 2×2 design. It uses the Type B contrasts generated by \code{con2by2B}
#' to define relevant interactions.
#'
#' @seealso \code{\link{dec2by2.A}}, \code{\link{decinter}}, \code{\link{con2by2B}},
#'   \code{\link{dec2way.mcp}}
#'
#' @keywords htest robust
#' @export
dec2by2.B<-function(J,K,x,alpha = 0.05, q = c(1:9)/10, nboot = 1000, SEED = TRUE,
    method = "BH"){
#
# For every relevant interaction, compare multiple quantiles
#
if(is.matrix(x))x=listm(x)
INT=list()
JK=J*K
CO=con2by2B(J,K)$conB
for( j in 1:ncol(CO)){
id=which(CO[,j]!=0)
X=x[id]
INT[[j]]=decinter(X,alpha=alpha,q=q,nboot=nboot,SEED=SEED,method=method)
}
list(B=INT,con=CO)
}




# ----------------------------------------------------------------------------

# dec2way.mcp

# ----------------------------------------------------------------------------

#' Multiple Comparison Procedures for Two-Way Designs Using Deciles
#'
#' @description
#' Performs multiple comparison procedures for two-way designs by comparing
#' multiple quantiles (deciles). Provides wrapper for various interaction and
#' main effect analyses.
#'
#' @param J Number of levels for Factor A
#' @param K Number of levels for Factor B
#' @param x Data in matrix or list mode
#' @param method Type of analysis: 'Int' (interactions), 'A.main' (Factor A main effects),
#'   'B.main' (Factor B main effects), 'A2by2' (Factor A 2×2 interactions),
#'   'B2by2' (Factor B 2×2 interactions)
#' @inheritParams common_params
#' @param q Vector of quantiles to compare (default: deciles 0.1 to 0.9)
#' @param nboot Number of bootstrap samples (default: 1000)
#'
#' @return
#' Result depends on method chosen. See individual functions for details.
#'
#' @details
#' This is a wrapper function that dispatches to specific analysis functions based
#' on the \code{method} argument.
#'
#' @seealso \code{\link{decJKinter}}, \code{\link{decJK.Amain}}, \code{\link{decJK.Bmain}},
#'   \code{\link{dec2by2.A}}, \code{\link{dec2by2.B}}
#'
#' @keywords htest robust
#' @export
dec2way.mcp<-function(J,K,x,method=c('Int','A.main','B.main','A2by2','B2by2'),alpha=.05,
q=c(1:9)/10,nboot=1000,SEED=TRUE){
type=match.arg(method)
switch(type,
Int=decJKinter(J,K,x,alpha =alpha, q = q, nboot = nboot, SEED = SEED),
A.main=decJK.Amain(J,K,x,alpha =alpha, q = q, nboot = nboot, SEED = SEED),
B.main=decJK.Bmain(J,K,x,alpha =alpha, q = q, nboot = nboot, SEED = SEED),
A2by2=dec2by2.A(J,K,x=x,alpha =alpha, q = q, nboot = nboot, SEED = SEED),
B2by2=dec2by2.A(J,K,x=x,alpha =alpha, q = q, nboot = nboot, SEED = SEED))
}


#' Estimate Deciles
#'
#' @description
#' Computes the nine deciles (0.1, 0.2, ..., 0.9) for a data vector using either
#' the Harrell-Davis estimator or standard quantile estimation.
#'
#' @param x Numeric vector of data
#' @param HD Logical: use Harrell-Davis estimator if TRUE (default), standard
#'   quantile function if FALSE
#' @param type Quantile algorithm type (1-9) used when HD=FALSE (default: 7).
#'   See \code{\link[stats]{quantile}} for details.
#'
#' @return
#' Numeric vector of length 9 containing the decile estimates.
#'
#' @details
#' When HD=TRUE, uses the Harrell-Davis estimator which provides smooth,
#' weighted estimates of the quantiles. This is more efficient for small samples
#' and provides estimates that are less sensitive to sampling variation.
#'
#' When HD=FALSE, uses R's built-in \code{quantile} function with the specified
#' type (default type 7 is R's default).
#'
#' Missing values are removed before computation.
#'
#' @examples
#' \dontrun{
#' x <- rnorm(100)
#' deciles(x)  # Harrell-Davis estimates
#' deciles(x, HD=FALSE)  # Standard quantiles
#' }
#'
#' @seealso \code{\link{hd}}, \code{\link[stats]{quantile}}, \code{\link{hdmq}}
#'
#' @keywords univar robust
#' @export
deciles<-function(x,HD=TRUE,type=7){
#
#  Estimate the deciles for the data in vector x
#  HD=TRUE: use the Harrell-Davis estimate of the q quantile
#   HD=FALSE:use R function quantile
#
x=elimna(x)
if(HD){
xs<-sort(x)
n<-length(x)
vecx<-seq(along=x)
xq<-0
for (i in 1:9){
q<-i/10
m1<-(n+1)*q
m2<-(n+1)*(1-q)
wx<-pbeta(vecx/n,m1,m2)-pbeta((vecx-1)/n,m1,m2)  # W sub i values
xq[i]<-sum(wx*xs)
}}
if(!HD){
pts=seq(.1,.9,.1)
xq=quantile(x,probs=pts,type=type)
}
xq
}




# ----------------------------------------------------------------------------

# decinter

# ----------------------------------------------------------------------------

#' Decile-Based Interaction Analysis for 2×2 Design
#'
#' @description
#' Performs interaction analysis for a 2×2 design by comparing multiple quantiles
#' (deciles by default) using the Harrell-Davis estimator and bootstrap methods.
#'
#' @param x Data in list or matrix mode. For 2×2 design, should have 4 groups
#'   corresponding to the cells of the design.
#' @inheritParams common_params
#' @param q Vector of quantiles to compare (default: deciles 0.1 to 0.9)
#' @param nboot Number of bootstrap samples (default: 1000)
#' @param method P-value adjustment method (default: "BH" for Benjamini-Hochberg)
#'
#' @return
#' A matrix with 9 rows (one per quantile) and 8 columns:
#' \describe{
#'   \item{Quant}{The quantile being tested}
#'   \item{Est.Lev 1}{Estimated difference at first level of Factor B}
#'   \item{Est.Lev 2}{Estimated difference at second level of Factor B}
#'   \item{Dif}{Interaction effect (difference of differences)}
#'   \item{ci.low}{Lower confidence limit}
#'   \item{ci.up}{Upper confidence limit}
#'   \item{p-value}{Unadjusted p-value}
#'   \item{p.adj}{Adjusted p-value}
#' }
#'
#' @details
#' For a 2×2 design with groups ordered as (A1B1, A1B2, A2B1, A2B2), the
#' interaction effect at each quantile q is:
#' \deqn{(Q_q(A1B1) - Q_q(A1B2)) - (Q_q(A2B1) - Q_q(A2B2))}
#'
#' Uses Harrell-Davis quantile estimator and percentile bootstrap for inference.
#' P-values are computed using the bootstrap distribution and adjusted for
#' multiple testing.
#'
#' @examples
#' \dontrun{
#' # 2x2 design with 4 groups
#' x <- list(rnorm(20), rnorm(20)+0.5, rnorm(20)+1, rnorm(20)+1.2)
#' decinter(x)
#' }
#'
#' @seealso \code{\link{decJKinter}}, \code{\link{hdmq}}, \code{\link{dec2by2.A}}
#'
#' @keywords htest robust
#' @export
decinter<-function(x,alpha=.05,q=c(1:9)/10,nboot=1000,SEED=TRUE,method='BH'){
#
# By default, use  all deciles when dealing with interactions in a 2-by-2 design.
# The quantiles used can be altered via the argument q
#
if(SEED)set.seed(2)
if(is.matrix(x))x=listm(x)
x=elimna(x)
bv1=matrix(NA,nrow=9,ncol=nboot)
bv2=matrix(NA,nrow=9,ncol=nboot)
bv3=matrix(NA,nrow=9,ncol=nboot)
bv4=matrix(NA,nrow=9,ncol=nboot)
data<-matrix(sample(x[[1]],size=length(x[[1]])*nboot,replace=TRUE),nrow=nboot)
bv1=apply(data,1,hdmq,q=q)
data<-matrix(sample(x[[2]],size=length(x[[2]])*nboot,replace=TRUE),nrow=nboot)
bv2=apply(data,1,hdmq,q=q)
data<-matrix(sample(x[[3]],size=length(x[[3]])*nboot,replace=TRUE),nrow=nboot)
bv3=apply(data,1,hdmq,q=q)
data<-matrix(sample(x[[4]],size=length(x[[4]])*nboot,replace=TRUE),nrow=nboot)
bv4=apply(data,1,hdmq,q=q)
be=bv1-bv2-bv3+bv4
pv=NA
nq=length(q)
ilow<-round((alpha/2) * nboot)
ihi<-nboot - ilow
ilow<-ilow+1
vs=sort(be)
cilow=NA
ciup=NA
for(i in 1:nq){
pv[i]=mean(be[i,]<0)
pv[i]=2*min(pv[i],1-pv[i])
bes=sort(be[i,])
cilow[i]=bes[ilow]
ciup[i]=bes[ihi]
}
output=matrix(NA,nrow=nq,ncol=8)
dimnames(output)=list(NULL,c('Quant','Est.Lev 1','Est.Lev 2','Dif','ci.low','ci.up','p-value','p.adj'))
output[,1]=q
e=lapply(x,hdmq,q=q)
est=e[[1]]-e[[2]]-e[[3]]+e[[4]]
output[,2]=e[[1]]-e[[2]]
output[,3]=e[[3]]-e[[4]]
output[,4]=est
output[,5]=cilow
output[,6]=ciup
output[,7]=pv
output[,8]=p.adjust(pv,method=method)
output
}

ancsm.es<-
function(x1,y1,x2,y2,method='KMS',pts=NA,est=tmean,
fr1=1,fr2=1,nboot=NA,nmin=12,alpha=.05,xout=FALSE,
outfun=outpro,plotit=TRUE,LP=TRUE,xlab='X',ylab='Y',pch1='*',pch2='+',...){
#
# Compare two independent  groups using
#  a percentile bootstrap combined with a running interval
# smooth and some robust measure of effect size:
#
#Choices for method:
# 'EP','QS','QStr','AKP','WMW','KMS'
#
#  Assume data are in x1 y1 x2 and y2
#  Comparisons are made at the design points contained in the vector
#  pts
#
flag.est=FALSE
if(identical(est,onestep))flag.est=TRUE
if(flag.est)LP=FALSE   # Get an error when using onestep in conjunction with LP=T
if(identical(est,mom))flag.est=TRUE
xy1=elimna(cbind(x1,y1))
x1=xy1[,1]
y1=xy1[,2]
xy2=elimna(cbind(x2,y2))
x2=xy2[,1]
y2=xy2[,2]
if(xout){
flag<-outfun(x1,...)$keep
x1<-x1[flag]
y1<-y1[flag]
flag<-outfun(x2,...)$keep
x2<-x2[flag]
