# freq5

# ----------------------------------------------------------------------------

#' Compute Relative Frequencies for Up to Five Variables
#'
#' @description
#' Computes and tabulates relative frequencies for up to five discrete variables.
#' Returns a list with frequency tables for each variable.
#'
#' @param x1 First variable (required)
#' @param x2 Second variable (optional, default: NULL)
#' @param x3 Third variable (optional, default: NULL)
#' @param x4 Fourth variable (optional, default: NULL)
#' @param x5 Fifth variable (optional, default: NULL)
#' @param xlab X-axis label for plotting (default: "X")
#' @param ylab Y-axis label for plotting (default: "Rel. Freq.")
#'
#' @return List of length 1-5 (depending on how many variables provided).
#'   Each element is a two-column matrix with columns:
#'   \item{Value}{Unique values in the variable}
#'   \item{Rel. Freq}{Relative frequency (proportion) of each value}
#'
#' @details
#' This function computes the relative frequency distribution (empirical probability
#' mass function) for up to five discrete variables. Missing values are automatically
#' removed from each variable before computing frequencies.
#'
#' @keywords univar
#' @export
freq5<-function(x1,x2=NULL,x3=NULL,x4=NULL,x5= NULL,xlab="X",ylab="Rel. Freq."){
#
# Compute relative frequencies associated with the sample space for up to five variables.
#
#
temp2=NULL
temp3=NULL
temp4=NULL
temp5=NULL
freqx2=NULL
freqx3=NULL
freqx4=NULL
freqx5=NULL

x1<-x1[!is.na(x1)]
temp1<-sort(unique(x1))
freqx1<-NA
for(i in 1:length(temp1)){
freqx1[i]<-sum(x1==temp1[i])
}
freqx1<-freqx1/length(x1)
N=1

if(!is.null(x2)){
N=2
x2<-x2[!is.na(x2)]
temp2<-sort(unique(x2))
freqx2<-NA
for(i in 1:length(temp2)){
freqx2[i]<-sum(x2==temp2[i])
}
freqx2<-freqx2/length(x2)
}

if(!is.null(x3)){
N=3
x3<-x3[!is.na(x3)]
temp3<-sort(unique(x3))
freqx3<-NA
for(i in 1:length(temp3)){
freqx3[i]<-sum(x3==temp3[i])
}
freqx3<-freqx3/length(x3)
}

if(!is.null(x4)){
N=4
x4<-x4[!is.na(x4)]
temp4<-sort(unique(x4))
freqx4<-NA
for(i in 1:length(temp4)){
freqx4[i]<-sum(x4==temp4[i])
}
freqx4<-freqx4/length(x4)
}

if(!is.null(x5)){
N=5
x5<-x5[!is.na(x5)]
temp5<-sort(unique(x5))
freqx5<-NA
for(i in 1:length(temp5)){
freqx5[i]<-sum(x5==temp5[i])
}
freqx5<-freqx5/length(x5)
}

v=list()
v[[1]]=cbind(temp1,freqx1)
v[[2]]=cbind(temp2,freqx2)
v[[3]]=cbind(temp3,freqx3)
v[[4]]=cbind(temp4,freqx4)
v[[5]]=cbind(temp5,freqx5)
for(j in 1:N)dimnames(v[[j]])=list(NULL,c('Value','Rel. Freq'))
v
}

