# indt0

# ----------------------------------------------------------------------------

#' Test Independence with Zero Intercept Constraint
#'
#' @description
#' Tests the hypothesis that the regression plane between X and Y is a flat
#' horizontal plane with intercept exactly 0 (i.e., E(Y|X) = 0). Based on
#' Stute et al. (1998).
#'
#' @param x Numeric vector or matrix of predictor variable(s)
#' @param y Numeric vector of response variable
#' @param nboot Number of bootstrap samples. Default is 500
#' @param alpha Significance level for critical value. Default is 0.05
#' @param flag Integer specifying test statistic:
#'   \itemize{
#'     \item 1: Kolmogorov-Smirnov test statistic
#'     \item 2: Cramer-von Mises test statistic
#'     \item 3: Both test statistics
#'   }
#' @param SEED Logical. If \code{TRUE}, set random seed for reproducibility.
#'   Default is \code{TRUE}
#'
#' @details
#' This function is similar to \code{\link{indt}} but tests the more specific
#' hypothesis that E(Y|X) = 0 (zero intercept). The method is based on Stute
#' et al. (1998, JASA, 93, 141-149).
#'
#' Unlike \code{\link{indt}}, this function returns critical values rather than
#' p-values.
#'
#' @return
#' List with components:
#' \itemize{
#'   \item \code{dstat}: Kolmogorov-Smirnov test statistic (if flag=1 or 3)
#'   \item \code{wstat}: Cramer-von Mises test statistic (if flag=2 or 3)
#'   \item \code{critd}: Critical value for K-S test at level alpha (if flag=1 or 3)
#'   \item \code{critw}: Critical value for C-vM test at level alpha (if flag=2 or 3)
#' }
#'
#' @references
#' Stute, W., Thies, S., & Zhu, L. X. (1998). Model checks for regression: An
#' innovation process approach. \emph{Annals of Statistics}, 26(5), 1916-1934.
#'
#' @seealso \code{\link{indt}}, \code{\link{indt0sub}}
#'
#' @keywords htest regression
#' @export
indt0<-function(x,y,nboot=500,alpha=.05,flag=1,SEED=TRUE){
#
# Test the hypothesis that the regression plane
#   between x and y  is a flat horizontal plane with intercept 0
# The method is based on results in
# Stute et al. (1998, JASA, 93, 141-149).
#
#  flag=1 gives Kolmogorov-Smirnov test statistic
#  flag=2 gives the Cramer-von Mises test statistic
#  flag=3 causes both test statistics to be reported.
#
if(SEED)set.seed(2)
x<-as.matrix(x)
# First, eliminate any rows of data with missing values.
temp <- cbind(x, y)
        temp <- elimna(temp)
        pval<-ncol(temp)-1
        x <- temp[,1:pval]
        y <- temp[, pval+1]
x<-as.matrix(x)
mflag<-matrix(NA,nrow=length(y),ncol=length(y))
for (j in 1:length(y)){
for (k in 1:length(y)){
mflag[j,k]<-(sum(x[j,]<=x[k,])==ncol(x))
}
}
# ith row of mflag indicates which rows of the matrix x are less
# than or equal to ith row of x
#
yhat<-0
res<-y-yhat
print("Taking bootstrap sample, please wait.")
data<-matrix(runif(length(y)*nboot),nrow=nboot)
data<-(data-.5)*sqrt(12) # standardize the random numbers.
rvalb<-apply(data,1,indt0sub,yhat,res,mflag,x,tr)
# An n x nboot matrix of R values
rvalb<-rvalb/sqrt(length(y))
dstatb<-apply(abs(rvalb),2,max)
wstatb<-apply(rvalb^2,2,mean)
mstatb<-apply(abs(rvalb),2,median)
dstatb<-sort(dstatb)
wstatb<-sort(wstatb)
mstatb<-sort(mstatb)
# compute test statistic
v<-c(rep(1,length(y)))
rval<-indt0sub(v,yhat,res,mflag,x,tr)
rval<-rval/sqrt(length(y))
dstat<-NA
wstat<-NA
critd<-NA
critw<-NA
ib<-round(nboot*(1-alpha))
if(flag==1 || flag==3){
dstat<-max(abs(rval))
critd<-dstatb[ib]
}
if(flag==2 || flag==3){
wstat<-mean(rval^2)
critw<-wstatb[ib]
}
list(dstat=dstat,wstat=wstat,critd=critd,critw=critw)
}




# ----------------------------------------------------------------------------

# indt0sub

# ----------------------------------------------------------------------------

#' Internal Helper for Independence Test with Zero Intercept
#'
#' @description
#' Internal function used by \code{\link{indt0}} to compute test statistics
#' during the bootstrap procedure.
#'
#' @param vstar Vector of standardized random values for bootstrap
#' @param yhat Predicted values (0 under null hypothesis)
#' @param res Residuals from the null model
#' @param mflag Matrix indicating which observations are ≤ each X value
#' @param x Matrix of predictor variables
#' @param tr Trimming parameter (not currently used)
#'
#' @details
#' This function computes the residual-based test statistics used in the
#' bootstrap procedure for testing independence with zero intercept constraint.
#'
#' @return
#' Numeric vector of test statistic values.
#'
#' @seealso \code{\link{indt0}}
#'
#' @keywords internal
#' @export
indt0sub<-function(vstar,yhat,res,mflag,x,tr){
bres<-res*vstar
rval<-0
for (i in 1:nrow(x)){
rval[i]<-sum(bres[mflag[,i]])
}
rval
}

#' Test Independence for All Variable Pairs
#'
#' @description
#' Tests the hypothesis of independence either for all pairs of variables in a
#' matrix, or between each variable in a matrix and a single response variable.
#' Uses repeated calls to \code{\link{indt}}.
#'
#' @param x Numeric matrix of variables
#' @param y Optional numeric vector. If \code{NULL}, tests all pairs of variables
#'   in x. If specified, tests each column of x against y
#' @param tr Trimming parameter (currently not used, reserved for future use).
#'   Default is 0
#' @param nboot Number of bootstrap samples for each test. Default is 500
#' @param SEED Logical. If \code{TRUE}, set random seed for reproducibility.
#'   Default is \code{TRUE}
#'
#' @details
#' This function performs multiple independence tests:
#' \itemize{
#'   \item If \code{y=NULL}: Tests independence for all pairs of columns in x
#'     (i.e., C(p,2) tests where p = ncol(x))
#'   \item If y is specified: Tests independence between each column of x and y
#'     (i.e., p tests)
#' }
#'
#' Each test uses the Cramer-von Mises statistic from \code{\link{indt}} with
#' \code{flag=2}.
#'
#' @return
#' Matrix with columns:
#' \itemize{
#'   \item \code{VAR}: First variable index (or column number)
#'   \item \code{VAR}: Second variable index (or "Y" if testing against y)
#'   \item \code{Test Stat.}: Cramer-von Mises test statistic
#'   \item \code{p-value}: Bootstrap p-value
#' }
#'
#' @seealso \code{\link{indt}}
#'
#' @keywords htest multivariate
#' @export
indtall<-function(x,y=NULL,tr=0,nboot=500,SEED=TRUE){
#
# Test the hypothesis of independence for
#  1. all pairs of variables in matrix x, if y=NA, or
#  2. between each variable stored in the matrix x and y.
#  This is done by repeated  calls to indt
#
x<-as.matrix(x)
# First, eliminate any rows of data with missing values.
if(!is.null(y[1])){
temp <- cbind(x, y)
        temp <- elimna(temp)
        pval<-ncol(temp)-1
        x <- temp[,1:pval]
        y <- temp[, pval+1]
}
x<-as.matrix(x)
if(is.null(y[1])){
ntest<-(ncol(x)^2-ncol(x))/2
if(ntest==0)stop("Something is wrong. Does x have only one column?")
output<-matrix(NA,nrow=ntest,ncol=4)
dimnames(output)<-list(NULL,c("VAR","VAR","Test Stat.","p-value"))
x<-elimna(x)
ic<-0
for (j in 1:ncol(x)){
for (jj in 1:ncol(x)){
if(j<jj){
temp<-indt(x[,j],x[,jj],nboot=nboot,SEED=SEED)
ic<-ic+1
output[ic,1]<-j
output[ic,2]<-jj
output[ic,3]<-temp$dstat
output[ic,4]<-temp$p.value.d
}}}}
if(!is.null(y[1])){
ntest<-ncol(x)
output<-matrix(NA,nrow=ntest,ncol=3)
dimnames(output)<-list(NULL,c("VAR","Test Stat.","p-value"))
ic<-0
for (j in 1:ncol(x)){
temp<-indt(x[,j],y,nboot=nboot,SEED=SEED)
ic<-ic+1
output[ic,1]<-j
output[ic,2]<-temp$dstat
output[ic,3]<-temp$p.value.d
}}
list(output=output)
}





#' Quantile Shift Interaction Effect Size (2×2)
#'
#' @description
#' Computes a quantile shift-type measure of effect size for an interaction
#' in a 2×2 factorial design.
#'
#' @param x Data in one of two formats:
#'   \itemize{
#'     \item List: Length 4 with elements for each cell
#'     \item Matrix/data frame: Will be converted to list
#'   }
#' @param nreps Integer. Number of resampling replications when using large samples (default: 200).
#' @param locfun Function. Location estimator to use (default: median).
#' @param SEED Logical. If TRUE, sets random seed to 2 for reproducibility (default: TRUE).
#' @param ... Additional arguments passed to \code{locfun}.
#'
#' @details
#' Computes interaction effect size by comparing shift functions:
#' \enumerate{
#'   \item For small samples (total n ≤ 1000): Uses all pairwise differences
#'   \item For large samples: Resamples to minimum group size and computes differences
#'   \item Applies \code{\link{shiftes}} to compare distribution of differences
#' }
#'
#' The interaction is assessed by forming differences (cell 1 - cell 2) and
#' (cell 3 - cell 4), then comparing these difference distributions.
#'
#' @return
#' List with component:
#' \describe{
#'   \item{Q.Effect}{Quantile-based interaction effect size}
#' }
#'
#' @seealso \code{\link{shiftes}} for shift function effect sizes,
#'   \code{\link{KMS.inter.pbci}} for alternative interaction test
#'
#' @export
#' @examples
#' # 2x2 design
#' set.seed(123)
#' x <- list(
#'   rnorm(20), rnorm(20, mean = 0.5),
#'   rnorm(20, mean = 0.3), rnorm(20, mean = 1.5)
#' )
#' result <- interQS(x, nreps = 100)
#' result$Q.Effect
interQS<-function(x,nreps=200,locfun=median,SEED=TRUE,...){
#
# Quantile shift-type measure of effect size for an  interaction in a 2-by-2 design
#
if(is.matrix(x) || is.data.frame(x))x=listm(x)
nv=as.vector(matl(lapply(x,FUN='length')))
nmin=min(nv)
ef=NA
nt=prod(nv)
nmin=min(c(nmin,50))
M=matrix(NA,nrow=nmin,ncol=4)
if(nt>10^3){
if(SEED)set.seed(2)
for(i in 1:nreps){
for(j in 1:4)M[,j]=sample(x[[j]],nmin)
L1=outer(M[,1],M[,2],FUN='-')
L2=outer(M[,3],M[,4],FUN='-')
ef[i]=shiftes(L1,L2,locfun=locfun)$Q.Effect
}}
else{
L1=outer(x[[1]],x[[2]],FUN='-')
L2=outer(x[[3]],x[[4]],FUN='-')
ef=shiftes(L1,L2,locfun=locfun,...)$Q.effect
}
es=mean(ef)
list(Q.Effect=es)
}


#' Wald-Type Test for Comparing Interquartile Ranges
#'
#' @description
#' Performs a Wald-type test for comparing the interquartile range (IQR) of
#' two independent groups using bootstrap standard errors.
#'
#' @param x Numeric vector. First group data.
#' @param y Numeric vector. Second group data.
#' @param nboot Integer. Number of bootstrap samples for standard error estimation (default: 100).
#' @param alpha Numeric. Significance level for confidence interval (default: 0.05).
#' @param SEED Logical. If TRUE, uses reproducible random seed in bootstrap (default: TRUE).
#'
#' @details
#' Computes:
#' \enumerate{
#'   \item IQR using Harrell-Davis estimator (\code{\link{IQRhd}}) for each group
#'   \item Bootstrap standard errors for each IQR estimate
#'   \item Wald test statistic: W = (IQR1 - IQR2) / SE
#'   \item Confidence interval based on normal approximation
#'   \item Two-sided p-value
#' }
#'
#' @return
#' List with components:
#' \describe{
#'   \item{Est.1}{IQR estimate for first group}
#'   \item{Est.2}{IQR estimate for second group}
#'   \item{Test.Stat}{Wald test statistic}
#'   \item{ci}{Confidence interval for difference in IQRs}
#'   \item{p.value}{Two-sided p-value}
#' }
#'
#' @seealso \code{\link{IQRhd}} for Harrell-Davis IQR,
#'   \code{\link{bootse}} for bootstrap standard errors,
#'   \code{\link{IQRstand}} for IQR standardization
#'
#' @export
#' @examples
#' set.seed(123)
#' x <- rnorm(30)
#' y <- rnorm(30, sd = 1.5)
#' result <- IQR2g.W(x, y, nboot = 200)
#' result$p.value
IQR2g.W<-function(x,y,nboot=100,alpha=.05,SEED=TRUE){
#
# Wald-type test for comparing interquartile range of two independent groups.
#
sd1=bootse(x,est=IQRhd,nboot=nboot,SEED=SEED)
sd2=bootse(x,est=IQRhd,nboot=nboot,SEED=SEED)
e1=IQRhd(x)
e2=IQRhd(y)
se=sqrt(sd1^2+sd2^2)
W=(e1-e2)/se
crit=qnorm(1-alpha/2)
ci=(e1-e2)-crit*se
ci[2]=(e1-e2)+crit*se
pv=2*(1-pnorm(abs(W)))
list(Est.1=e1,Est.2=e2,Test.Stat=W,ci=ci,p.value=pv)
}

#' IQR Standardization
#'
#' @description
#' Standardizes data by dividing by the interquartile range (IQR) based on
#' the ideal fourths.
#'
#' @param x Numeric vector. Data to standardize.
#'
#' @details
#' Computes standardized values as:
#' \deqn{x_{standardized} = \frac{x}{IQR}}
#'
#' where IQR is computed using \code{\link{idealf}} (ideal fourths method).
#' This provides a robust scale estimate similar to z-scores but using IQR
#' instead of standard deviation.
#'
#' @return
#' Numeric vector of standardized values.
#'
#' @seealso \code{\link{idealf}} for ideal fourths computation,
#'   \code{\link{IQRhd}} for Harrell-Davis IQR,
#'   \code{\link{MADstand}} for MAD standardization
#'
#' @export
#' @examples
#' x <- c(1:10, 100)  # Data with outlier
#' x_std <- IQRstand(x)
#' range(x_std)
IQRstand<-function(x){
vals=idealf(x)
res=x/(vals$qu-vals$ql)
res
}




# ----------------------------------------------------------------------------

# JK.AB.KS.ES

# ----------------------------------------------------------------------------

#' Main Effect Sizes for J×K Design (KS Method)
#'
#' @description
#' Computes Kolmogorov-Smirnov-based effect sizes for main effects in a
#' J×K independent groups factorial design.
#'
#' @param J Integer. Number of levels for Factor A.
#' @param K Integer. Number of levels for Factor B.
#' @param x Data in one of two formats:
#'   \itemize{
#'     \item List: Length J×K with data for each cell
#'     \item Matrix/data frame: Will be converted to list
#'   }
#'
#' @details
#' For each main effect:
#' \enumerate{
#'   \item Factor A: Computes KS effect sizes for each level across Factor B
#'   \item Factor B: Computes KS effect sizes for each level across Factor A
#'   \item Uses \code{\link{KS.ANOVA.ES}} for effect size computation
#' }
#'
#' This provides a distribution-free measure of main effect sizes based on
#' the Kolmogorov-Smirnov statistic.
#'
#' @return
#' List with components:
#' \describe{
#'   \item{Fac.A}{List of length J, each element containing KS effect sizes for Factor A}
#'   \item{Fac.B}{List of length K, each element containing KS effect sizes for Factor B}
#' }
#'
#' @seealso \code{\link{KS.ANOVA.ES}} for KS-based ANOVA effect sizes,
#'   \code{\link{JK.AB.KS.ES}} for interaction effects
#'
#' @export
#' @examples
#' # 2x3 design
#' set.seed(123)
#' x <- list(
#'   rnorm(20), rnorm(20, 0.5), rnorm(20, 1),
#'   rnorm(20, 0.3), rnorm(20, 0.8), rnorm(20, 1.3)
#' )
#' result <- JK.AB.KS.ES(J = 2, K = 3, x)
JK.AB.KS.ES<-function(J,K,x){
#
# Independent groups
# Compute main effect sizes
#
JK=J*K
if(is.matrix(x)  || is.data.frame(x))x=listm(x)
mat=matrix(c(1:JK),nrow=J,byrow=TRUE)
A=list()
B=list()
for(j in 1:nrow(mat)){
id=mat[j,]
A[[j]]=KS.ANOVA.ES(x[id])
}
mat=t(mat)
for(j in 1:nrow(mat)){
id=mat[j,]
B[[j]]=KS.ANOVA.ES(x[id])
}
list(Fac.A=A,Fac.B=B)
}




# ----------------------------------------------------------------------------

# johan

# ----------------------------------------------------------------------------

#' Johansen's Test for Independent Groups
#'
#' @description
#' Performs Johansen's generalized test of linear contrasts for trimmed means
#' in independent groups designs. Tests H0: C μ = 0 where C is a contrast matrix.
#'
#' @param cmat Matrix. Contrast matrix C of dimension k×p (rank k).
#' @param vmean Numeric vector. Length p containing trimmed means for each group.
#' @param vsqse Matrix or vector. Diagonal matrix (or vector of diagonal elements)
#'   containing squared standard errors of the trimmed means.
#' @param h Numeric vector. Effective sample sizes for each group.
#' @param alpha Numeric. Significance level for critical value (default: 0.05).
#'
#' @details
#' Performs Johansen's chi-square-type test with improved critical values
#' that account for:
#' \enumerate{
#'   \item Heteroscedasticity across groups
#'   \item Trimmed mean estimation
#'   \item Small to moderate sample sizes
#' }
#'
#' The test statistic has an approximate chi-square distribution under H0,
#' with adjusted critical values to improve Type I error control.
#'
#' This is an internal utility function used by higher-level ANOVA and
#' contrast testing functions, but can be used directly for custom contrasts.
#'
#' @return
#' List with components:
#' \describe{
#'   \item{teststat}{Johansen's test statistic}
#'   \item{crit}{Adjusted critical value}
#'   \item{df}{Degrees of freedom (number of contrasts)}
#' }
#'
#' @seealso \code{\link{johansp}} for split-plot version,
#'   \code{\link{kbcon}} for Kaiser-Bowden contrasts,
#'   \code{\link{lincon}} for general linear contrasts
#'
#' @export
#' @examples
#' # Three groups, test if mean of group 1 differs from average of groups 2-3
#' vmean <- c(5.2, 4.8, 4.5)
#' vsqse <- c(0.25, 0.30, 0.28)
#' h <- c(18, 18, 18)  # Effective sample sizes
#' cmat <- matrix(c(1, -0.5, -0.5), nrow = 1)
#' result <- johan(cmat, vmean, vsqse, h)
#' result$teststat > result$crit  # Reject H0?
johan<-function(cmat,vmean,vsqse,h,alpha=.05){
#
#  This function is used by other functions that come with this book,
#  and it can be used to test hypotheses not covered in the text.
#
#  The function performs Johansen's test of C mu = 0 for p independent groups,
#  where C is a k by p matrix of rank k and mu is a p by 1 matrix of
#  of unknown trimmed means.
#  The argument cmat contains the matrix C.
#  vmean is a vector of length p containing the p trimmed means
#  vsqe is a diagonal matrix containing the squared standard errors of the
#  the trimmed means in vmean.
#  h is a vector containing the effective sample sizes
#
yvec<-matrix(vmean,length(vmean),1)
if(!is.matrix(vsqse))vsqse<-diag(vsqse)
test<-cmat%*%vsqse%*%t(cmat)
invc<-solve(test)
test<-t(yvec)%*%t(cmat)%*%invc%*%cmat%*%yvec
R<-vsqse%*%t(cmat)%*%invc%*%cmat
A<-sum(diag((diag(R))^2/diag(h-1)))
df<-nrow(cmat)
crit<-qchisq(1-alpha,df)
crit<-crit+(crit/(2*df))*A*(1+3*crit/(df+2))
list(teststat=test[1],crit=crit[1],df=df)
}




# ----------------------------------------------------------------------------

# johansp

# ----------------------------------------------------------------------------

#' Johansen's Test for Split-Plot Designs
#'
#' @description
#' Performs Johansen's generalized test of linear contrasts for trimmed means
#' in split-plot (mixed) designs. Tests H0: C μ = 0 where Factor A is between-subjects
#' and Factor B is within-subjects.
#'
#' @param cmat Matrix. Contrast matrix C of dimension k×p (rank k).
#' @param vmean Numeric vector. Length p = J×K containing trimmed means for all cells.
#' @param vsqse Matrix. Block diagonal covariance matrix, where the j-th block
#'   contains estimated covariances among trimmed means for the j-th level of Factor A.
#' @param h Numeric vector. Length J containing effective sample sizes for each
#'   level of Factor A.
#' @param J Integer. Number of levels for Factor A (between-subjects).
#' @param K Integer. Number of levels for Factor B (within-subjects).
#'
#' @details
#' Extends \code{\link{johan}} to split-plot designs:
#' \enumerate{
#'   \item Accounts for within-subjects correlations in Factor B
#'   \item Uses block diagonal covariance structure
#'   \item Computes F-type test statistic with adjusted degrees of freedom
#'   \item Provides p-value based on F-distribution
#' }
#'
#' The covariance matrix \code{vsqse} must reflect the dependency structure:
#' independent across Factor A levels, but correlated within Factor B levels.
#'
#' This is an internal utility function used by higher-level split-plot ANOVA
#' functions, but can be used directly for custom contrasts.
#'
#' @return
#' List with components:
#' \describe{
#'   \item{teststat}{Johansen's F-type test statistic}
#'   \item{p.value}{p-value based on F-distribution}
#' }
#'
#' @seealso \code{\link{johan}} for independent groups version,
#'   \code{\link{sppba}} for split-plot bootstrap tests,
#'   \code{\link{bwwtrim}} for split-plot trimmed means ANOVA
#'
#' @export
#' @examples
#' # 2×3 split-plot design example
#' # (Would require properly structured covariance matrix)
#' # See split-plot ANOVA functions for usage examples
johansp<-function(cmat,vmean,vsqse,h,J,K){
#
#  This function is used by other functions that come with this book,
#  and it can be used to test hypotheses not covered in the text.
#
#  The function performs Johansen's test of C mu = 0 for
#  a split-plot design where the first factor has independent groups,
#  while the second factor is within subjects,
#  C is a k by p matrix of rank k and mu is a p by 1 matrix of
#  of unknown trimmed means.
#  The argument cmat contains the matrix C.
#  vmean is a vector of length p containing the p trimmed means
#  vsqe is a block diagonal matrix, the jth block being the
#  estimated covariances among the trimmed means
#  in the jth level of factor A,
#  the trimmed means are in vmean,
#  h is a vector of length J containing the effective sample sizes for
#  the jth level of factor A.
#
p<-J*K
yvec<-matrix(vmean,length(vmean),1)
test<-cmat%*%vsqse%*%t(cmat)
invc<-solve(test)
test<-t(yvec)%*%t(cmat)%*%invc%*%cmat%*%yvec
temp<-0
klim<-1-K
kup<-0
for (j in 1:J){
klim<-klim+K
kup<-kup+K
Q<-matrix(0,p,p) #  create Q sub j
for (k in klim:kup)Q[k,k]<-1
mtem<-vsqse%*%t(cmat)%*%invc%*%cmat%*%Q
temp[j]<-(sum(diag(mtem%*%mtem))+(sum(diag(mtem)))^2)/(h[j]-1)
}
A<-.5*sum(temp)
df1<-nrow(cmat)
df2<-nrow(cmat)*(nrow(cmat)+2)/(3*A)
cval<-nrow(cmat)+2*A-6*A/(nrow(cmat)+2)
test<-test/cval
sig<-1-pf(test,df1,df2)
list(teststat=test[1],p.value=sig)
}


#' Kaiser-Bowden Heteroscedastic Contrast Test
#'
#' @description
#' Performs Kaiser-Bowden heteroscedastic tests of linear contrasts using
#' trimmed means for independent groups.
#'
#' @param x Data in one of two formats:
#'   \itemize{
#'     \item List: Each element contains data for one group
#'     \item Matrix: Each column represents a group (will be converted to list)
#'   }
#' @param con Matrix. J×d matrix of contrast coefficients (J groups, d contrasts).
#'   If \code{con=0} (default), performs all pairwise comparisons.
#' @param tr Numeric. Trimming proportion (default: 0.2).
#' @param alpha Numeric. Significance level (default: 0.05).
#' @param pr Logical. If TRUE (default), prints note about FWE control.
#'
#' @details
#' Kaiser-Bowden method features:
#' \enumerate{
#'   \item Allows heteroscedasticity across groups
#'   \item Uses trimmed means for robustness
#'   \item F-type test statistic with adjusted degrees of freedom
#'   \item Confidence intervals control familywise error rate (FWE)
#'   \item Individual p-values are NOT adjusted for multiple comparisons
#' }
#'
#' When \code{con=0}, all (J choose 2) pairwise comparisons are performed.
#' Missing values are automatically removed.
#'
#' @return
#' List with components:
#' \describe{
#'   \item{test}{Matrix with test statistics, critical values, standard errors, and df}
#'   \item{psihat}{Matrix with contrast estimates, confidence intervals, and p-values}
#' }
#'
#' @seealso \code{\link{lincon}} for general linear contrasts,
#'   \code{\link{johan}} for Johansen's method,
#'   \code{\link{mcppb20}} for bootstrap contrasts
#'
#' @export
#' @examples
#' # Three groups, all pairwise comparisons
#' set.seed(123)
#' x <- list(rnorm(20), rnorm(20, 0.5), rnorm(20, 1))
#' result <- kbcon(x, con = 0, tr = 0.2)
#' result$psihat
#'
#' # Custom contrasts
#' con <- matrix(c(1, -0.5, -0.5, 1, 0, -1), nrow = 3, ncol = 2)
#' result2 <- kbcon(x, con = con)
kbcon<-function(x,con=0,tr=.2,alpha=.05,pr=TRUE){
#
#  A heteroscedastic test of d linear contrasts using trimmed means.
#  based on the Kaiser-Bowden method
#
#  The data are assumed to be stored in $x$ in list mode or in a matrix
#  Length(x) (or ncol(x))is assumed to correspond to the total number of groups
#  It is assumed all groups are independent.
#
#  con is a J by d matrix containing the contrast coefficients.
#  If con is not specified, all pairwise comparisons are made.
#
#  Missing values are automatically removed.
#
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop("Data must be stored in a matrix or in list mode.")
con<-as.matrix(con)
J<-length(x)
h<-vector("numeric",J)
w<-vector("numeric",J)
xbar<-vector("numeric",J)
for(j in 1:J){
xx<-!is.na(x[[j]])
val<-x[[j]]
x[[j]]<-val[xx]  # Remove missing values
h[j]<-length(x[[j]])-2*floor(tr*length(x[[j]]))
   # h is the number of observations in the jth group after trimming.
w[j]<-((length(x[[j]])-1)*winvar(x[[j]],tr))/(h[j]*(h[j]-1))
xbar[j]<-mean(x[[j]],tr)
}
if(sum(con^2)==0){
CC<-(J^2-J)/2
v1=J-1
psihat<-matrix(0,CC,6)
dimnames(psihat)<-list(NULL,c("Group","Group","psihat","ci.lower","ci.upper",
"p.value"))
test<-matrix(NA,CC,6)
dimnames(test)<-list(NULL,c("Group","Group","test","crit","se","df"))
jcom<-0
for (j in 1:J){
for (k in 1:J){
if (j < k){
jcom<-jcom+1
df<-(w[j]+w[k])^2/(w[j]^2/(h[j]-1)+w[k]^2/(h[k]-1))
term=sqrt((J-1)*(1+(J-2)/df))
test[jcom,3]<-((xbar[j]-xbar[k])/(term*sqrt(w[j]+w[k])))^2
sejk<-sqrt(w[j]+w[k])
test[jcom,5]<-sejk
psihat[jcom,1]<-j
psihat[jcom,2]<-k
test[jcom,1]<-j
test[jcom,2]<-k
psihat[jcom,3]<-(xbar[j]-xbar[k])
test[jcom,6]<-df
crit=qf(1-alpha,v1,df)
aterm=sqrt(crit)*term
test[jcom,4]<-qf(1-alpha,v1,df)
psihat[jcom,4]<-(xbar[j]-xbar[k])-aterm*sejk
psihat[jcom,5]<-(xbar[j]-xbar[k])+aterm*sejk
psihat[jcom,6]<-1-pf(test[jcom,3],v1,df)
}}}}
if(sum(con^2)>0){
if(nrow(con)!=length(x)){
stop("The number of groups does not match the number of contrast coefficients.")
}
v1=nrow(con)-1
psihat<-matrix(0,ncol(con),5)
dimnames(psihat)<-list(NULL,c("con.num","psihat","ci.lower","ci.upper",
"p.value"))
test<-matrix(0,ncol(con),5)
dimnames(test)<-list(NULL,c("con.num","test","crit","se","df"))
df<-0
L=nrow(con)
for (d in 1:ncol(con)){
psihat[d,1]<-d
psihat[d,2]<-sum(con[,d]*xbar)
sejk<-sqrt(sum(con[,d]^2*w))
test[d,1]<-d
df<-(sum(con[,d]^2*w))^2/sum(con[,d]^4*w^2/(h-1))
A=(L-1)*(1+(L-2)/df)
test[d,2]<-(sum(con[,d]*xbar)/(sqrt(A)*sejk))^2
crit=qf(1-alpha,v1,df)
test[d,3]<-crit
test[d,4]<-sejk
test[d,5]<-df
psihat[d,3]<-psihat[d,2]-sqrt(crit*A)*sejk
psihat[d,4]<-psihat[d,2]+sqrt(crit*A)*sejk
psihat[d,5]<-1-pf(test[d,2],v1,df)
}}
#
if(pr){
print("Note: confidence intervals are adjusted to control FWE")
print("But p-values are not adjusted to control FWE")
}
list(test=test,psihat=psihat)
}




