# LG.samp

# ----------------------------------------------------------------------------

#' Sample Size Estimation for Yuen's Test (Luh-Guo Method)
#'
#' @description
#' Estimates required sample sizes for Yuen's trimmed mean test using the
#' Luh-Guo method. Uses 20\% trimming.
#'
#' @param x Numeric vector for first group (pilot data).
#' @param y Numeric vector for second group (pilot data).
#' @param del Minimum detectable difference (effect size). Default is 0.
#' @param alpha Significance level (Type I error rate). Default is 0.05.
#' @param beta Type II error rate (1 - power). Default is 0.2 (power = 0.8).
#'
#' @return Estimated sample sizes required for each group.
#'
#' @details
#' This function uses pilot data from two groups to estimate the sample sizes
#' needed to detect a specified effect size with given Type I and Type II error
#' rates using Yuen's test with 20\% trimming. The Luh-Guo method is used for
#' the calculation.
#'
#' @keywords design
#' @export
LG.samp<-function(x,y,del=0,alpha=.05,beta=.2){
#
# estimate sample sizes for Yuen methods, trimming =.2
# using Luh-Guo method
# 
f1<-length(x)-2*floor(tr*length(x))
f2<-length(y)-2*floor(tr*length(y))
wx=winval(x)
wy=winval(y)
sqw1=sum((wx-mean(wx))^2)/(f1-1)
sqw2=sum((wy-mean(wy))^2)/(f2-1)
#print(sqw1)
#print(sqw2)
root1=sqrt(sqw1)
root2=sqrt(sqw2)
crit1=qnorm(1-alpha/2)
crit2=qnorm(1-beta)
tauw=sqrt(sqw2/sqw1)
F1=root1*(root1+root2)*(crit1+crit2)^2/del^2++crit1^2/(2*(1+tauw))
F2=root2*(root1+root2)*(crit1+crit2)^2/del^2++crit1^2*tauw/(2*(1+tauw))
N1=floor(F1/.6)+1
N2=floor(F2/.6)+1
c(N1,N2)
}

#' Linear Contrasts for Dependent Groups Using Medians
#'
#' @description
#' Performs heteroscedastic tests of linear contrasts among dependent groups
#' using medians or other quantiles.
#'
#' @param x Data in matrix or list mode. Each column (or list element) represents
#'   a dependent group.
#' @param con A J by d matrix of contrast coefficients where J is number of groups
#'   and d is number of contrasts. If 0 (default), all pairwise comparisons are made.
#' @param alpha Significance level (default: 0.05).
#' @param q Quantile to use for group comparisons (default: 0.5 for median).
#' @param mop Logical. If \code{FALSE} (default), uses single order statistic.
#'   If \code{TRUE}, uses usual sample median with bootstrap covariance estimation.
#' @param nboot Number of bootstrap samples when \code{mop=TRUE} (default: 100).
#' @param SEED Logical. If \code{TRUE}, sets random seed for bootstrap. Default is \code{TRUE}.
#'
#' @return A list with components:
#'   \item{test}{Matrix with columns: contrast number, test statistic, p-value,
#'     critical p-value, standard error}
#'   \item{psihat}{Matrix with columns: contrast number, estimate, CI lower, CI upper}
#'   \item{num.sig}{Number of significant contrasts}
#'
#' @details
#' Tests linear contrasts among dependent groups using quantile estimators.
#' When \code{mop=FALSE}, uses a single order statistic approach. When \code{mop=TRUE},
#' uses bootstrap to estimate covariances among medians. Uses Hochberg's method
#' for multiple comparison adjustment. Missing values are automatically removed.
#'
#' @seealso \code{\link{lincdtr}}, \code{\link{qdmcp}}
#'
#' @keywords htest
#' @export
lincdm<-function(x,con=0,alpha=.05,q=.5,mop=FALSE,nboot=100,SEED=TRUE){
#
#  A heteroscedastic test of d linear contrasts among
#  dependent groups using medians.
#
#  The data are assumed to be stored in $x$ in list mode.
#  Length(x) is assumed to correspond to the total number of groups, J
#  It is assumed all groups are independent.
#
#  con is a J by d matrix containing the contrast coefficients that are used.
#  If con is not specified, all pairwise comparisons are made.
#
#  q is the quantile used to compare groups.
#  con contains contrast coefficients,
#  con=0 means all pairwise comparisons are used
#  mop=F, use single order statistic
#  mop=T, use usual sample median, even if q is not equal to .5
#  in conjunction with a bootstrap estimate of covariances among
#  the medians using
#  nboot samples.
#
#  Missing values are automatically removed.
#
#
if(mop && SEED)set.seed(2)
if(is.list(x)){
x<-matl(x)
x<-elimna(x)
}
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop("Data must be stored in a matrix or in list mode.")
con<-as.matrix(con)
J<-length(x)
h<-length(x[[1]])
w<-vector("numeric",J)
xbar<-vector("numeric",J)
for(j in 1:J){
if(!mop)xbar[j]<-qest(x[[j]],q=q)
if(mop)xbar[j]<-median(x[[j]])
}
if(sum(con^2)==0){
temp<-qdmcp(x,alpha=alpha,q=q,pr=FALSE)
test<-temp$test
psihat<-temp$psihat
num.sig<-temp$num.sig
}
if(sum(con^2)>0){
ncon<-ncol(con)
if(alpha==.05){
dvec<-c(.05,.025,.0169,.0127,.0102,.00851,.0073,.00639,.00568,.00511)
if(ncon > 10){
avec<-.05/c(11:ncon)
dvec<-c(dvec,avec)
}}
if(alpha==.01){
dvec<-c(.01,.005,.00334,.00251,.00201,.00167,.00143,.00126,.00112,.00101)
if(ncon > 10){
avec<-.01/c(11:ncon)
dvec<-c(dvec,avec)
}}
if(alpha != .05 && alpha != .01)dvec<-alpha/c(1:ncon)
if(nrow(con)!=length(x)){
stop("The number of groups does not match the number of contrast coefficients.")
}
psihat<-matrix(0,ncol(con),4)
dimnames(psihat)<-list(NULL,c("con.num","psihat","ci.lower","ci.upper"))
test<-matrix(0,ncol(con),5)
dimnames(test)<-list(NULL,c("con.num","test","p.value","crit.p.value","se"))
df<-length(x[[1]])-1
if(!mop)w<-covmmed(x,q=q)
if(mop)w<-bootcov(x,nboot=nboot,pr=FALSE)
for (d in 1:ncol(con)){
psihat[d,1]<-d
psihat[d,2]<-sum(con[,d]*xbar)
cvec<-as.matrix(con[,d])
sejk<-sqrt(t(cvec)%*%w%*%cvec)
test[d,1]<-d
test[d,2]<-sum(con[,d]*xbar)/sejk
test[d,3]<-2*(1-pt(abs(test[d,2]),df))
test[d,5]<-sejk
}
temp1<-test[,3]
temp2<-order(0-temp1)
zvec<-dvec[1:ncon]
test[temp2,4]<-zvec
psihat[,3]<-psihat[,2]-qt(1-test[,4]/2,df)*test[,5]
psihat[,4]<-psihat[,2]+qt(1-test[,4]/2,df)*test[,5]
num.sig<-sum(test[,3]<=test[,4])
}
list(test=test,psihat=psihat,num.sig=num.sig)
}

#' Linear Contrasts for Dependent Groups Using Trimmed Means
#'
#' @description
#' Performs heteroscedastic tests of linear contrasts among dependent groups
#' using trimmed means.
#'
#' @param x Data in matrix or list mode. Each column (or list element) represents
#'   a dependent group.
#' @param con A J by d matrix of contrast coefficients where J is number of groups
#'   and d is number of contrasts. If 0 (default), all pairwise comparisons are made.
#' @param alpha Significance level (default: 0.05).
#' @param tr Trimming proportion (default: 0.2 for 20\% trimming).
#'
#' @return A list with components:
#'   \item{test}{Matrix with columns: contrast number, test statistic, p-value,
#'     critical p-value, standard error}
#'   \item{psihat}{Matrix with columns: contrast number, estimate, CI lower, CI upper}
#'   \item{num.sig}{Number of significant contrasts}
#'
#' @details
#' Tests linear contrasts among dependent groups using trimmed means. Uses
#' Hochberg's method for multiple comparison adjustment. Missing values are
#' automatically removed.
#'
#' @seealso \code{\link{lincdm}}, \code{\link{rmmcp}}
#'
#' @keywords htest
#' @export
lincdtr<-function(x,con=0,alpha=.05,tr=.2){
#
#  A heteroscedastic test of d linear contrasts among
#  dependent groups using trimmed means.
#
#  The data are assumed to be stored in $x$ in list mode.
#  Length(x) is assumed to correspond to the total number of groups, J
#  It is assumed all groups are independent.
#
#  con is a J by d matrix containing the contrast coefficients that are used.
#  If con is not specified, all pairwise comparisons are made.
#
#  con contains contrast coefficients,
#  con=0 means all pairwise comparisons are used
#
#  Missing values are automatically removed.
#
#
if(is.list(x)){
x<-matl(x)
x<-elimna(x)
}
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop("Data must be stored in a matrix or in list mode.")
con<-as.matrix(con)
J<-length(x)
h<-length(x[[1]])
w<-vector("numeric",J)
xbar<-vector("numeric",J)
for(j in 1:J){
xbar[j]<-mean(x[[j]],tr=tr)
}
if(sum(con^2)==0){
temp<-rmmcp(x,alpha=alpha,tr=tr,dif=FALSE)
test<-temp$test
psihat<-temp$psihat
num.sig<-temp$num.sig
}
if(sum(con^2)>0){
ncon<-ncol(con)
if(alpha==.05){
dvec<-c(.05,.025,.0169,.0127,.0102,.00851,.0073,.00639,.00568,.00511)
if(ncon > 10){
avec<-.05/c(11:ncon)
dvec<-c(dvec,avec)
}}
if(alpha==.01){
dvec<-c(.01,.005,.00334,.00251,.00201,.00167,.00143,.00126,.00112,.00101)
if(ncon > 10){
avec<-.01/c(11:ncon)
dvec<-c(dvec,avec)
}}
if(alpha != .05 && alpha != .01)dvec<-alpha/c(1:ncon)
if(nrow(con)!=length(x)){
stop("The number of groups does not match the number of contrast coefficients.")
}
psihat<-matrix(0,ncol(con),4)
dimnames(psihat)<-list(NULL,c("con.num","psihat","ci.lower","ci.upper"))
test<-matrix(0,ncol(con),5)
dimnames(test)<-list(NULL,c("con.num","test","p.value","crit.p.value","se"))
df<-length(x[[1]])-1
w<-covmtrim(x,tr=tr)
for (d in 1:ncol(con)){
psihat[d,1]<-d
psihat[d,2]<-sum(con[,d]*xbar)
cvec<-as.matrix(con[,d])
sejk<-sqrt(t(cvec)%*%w%*%cvec)
test[d,1]<-d
test[d,2]<-sum(con[,d]*xbar)/sejk
test[d,3]<-2*(1-pt(abs(test[d,2]),df))
test[d,5]<-sejk
}
temp1<-test[,3]
temp2<-order(0-temp1)
zvec<-dvec[1:ncon]
test[temp2,4]<-zvec
psihat[,3]<-psihat[,2]-qt(1-test[,4]/2,df)*test[,5]
psihat[,4]<-psihat[,2]+qt(1-test[,4]/2,df)*test[,5]
num.sig<-sum(test[,3]<=test[,4])
}
list(test=test,psihat=psihat,num.sig=num.sig)
}




