# linplot

# ----------------------------------------------------------------------------

#' Plot Distribution of Linear Contrast
#'
#' @description
#' Estimates and plots the distribution of a linear contrast Y = sum(c_j * X_j)
#' using adaptive kernel density estimation.
#'
#' @param x Data in matrix or list format. For matrix: each column is a group.
#'   For list: x[[j]] contains data for group j.
#' @param con Numeric vector of contrast coefficients (length J). Must sum to zero.
#' @param nreps Number of resampling iterations to estimate the distribution (default: 200).
#' @param SEED Logical. If TRUE (default), sets random seed to 2 for reproducibility.
#' @param xlab X-axis label (default: 'DV').
#' @param ylab Y-axis label (default: empty string).
#'
#' @details
#' This function:
#' \itemize{
#'   \item Estimates the distribution of the linear contrast via resampling
#'   \item For each iteration, randomly samples one value from each group
#'   \item Computes the weighted sum using contrast coefficients
#'   \item Plots the resulting distribution using \code{\link{akerd}}
#' }
#'
#' @return None (creates a plot).
#'
#' @seealso \code{\link{linQS}} (quantile effect size), \code{\link{linEP}} (explanatory power),
#'   \code{\link{akerd}} (plotting function)
#'
#' @export
#' @examples
#' # Plot distribution of difference between two groups
#' set.seed(123)
#' x <- list(rnorm(50), rnorm(50, mean = 0.5))
#' linplot(x, con = c(1, -1), nreps = 500)
linplot<-function(x,con,nreps=200,SEED=TRUE,xlab='DV',ylab=''){
#
# Determine distribution of Y_i=sum_j c_jX_j
# and then plot the distribution
#
con=as.vector(con)
if(sum(con)!=0)stop('Contrast coefficients must sum to zero')
if(SEED)set.seed(2)
if(is.data.frame(x))x=as.matrix(x)
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop('Data must be stored in a matrix or in list mode.')
J<-length(x)
if(length(con)!=J)stop('Length of con should equal number of groups')
x=elimna(x)
L=NA
linv=NA
for(i in 1:nreps){
for(j in 1:J)linv[j]=sample(x[[j]],1)
L[i]=sum(con*linv)
}
akerd(L,xlab='X',ylab=ylab)
}

#' Quantile Shift Effect Size for Linear Contrast (Resampling Version)
#'
#' @description
#' Estimates quantile shift effect size for a linear contrast using resampling
#' to handle unequal sample sizes. This version estimates the distribution of
#' Y = sum(c_j * X_j) via balanced resampling.
#'
#' @param x Data in matrix or list format. For matrix: each column is a group.
#'   For list: x[[j]] contains data for group j.
#' @param con Numeric vector of contrast coefficients (length J). Must sum to zero.
#' @param locfun Location estimator function (default: \code{median}).
#' @param nreps Number of resampling iterations (default: 200).
#' @param SEED Logical. If TRUE (default), sets random seed to 2 for reproducibility.
#'
#' @details
#' This is a resampling version of \code{lindQS} that:
#' \itemize{
#'   \item Resamples equal-sized groups (size = min sample size across groups)
#'   \item Computes linear contrasts for each resampled dataset
#'   \item Estimates quantile shift and location for each iteration
#'   \item Averages results across iterations
#' }
#'
#' The quantile effect indicates the proportion of the contrast distribution
#' relative to its center.
#'
#' @return
#' List with components:
#' \describe{
#'   \item{Q.effect}{Average quantile shift effect size across resampling iterations}
#'   \item{center}{Average location estimate across resampling iterations}
#' }
#'
#' @seealso \code{\link{lindQS}} (direct version), \code{\link{linQS.sub2}} (helper),
#'   \code{\link{linEP}}, \code{\link{linWMWMC.sub}}
#'
#' @note This function overrides an earlier definition of linQS that doesn't use resampling.
#'   This version is the active one when the package loads.
#'
#' @export
#' @examples
#' # Three groups with unequal sample sizes
#' set.seed(123)
#' x <- list(rnorm(30), rnorm(40, mean = 0.3), rnorm(35, mean = 0.5))
#' con <- c(-1, 0, 1)  # Linear trend
#' result <- linQS(x, con, nreps = 100)
#' result$Q.effect
linQS<-function(x,con,locfun=median,nreps=200,SEED=TRUE){
#
# Determine distribution of Y_i=sum_j c_jX_j
# Then estimate quantile shift in location measure of effect size
# locfun, which defaults to the median.
#
if(sum(con)!=0)stop('Contrast coefficients must sum to zero')
if(SEED)set.seed(2)
if(is.data.frame(x))x=as.matrix(x)
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop('Data must be stored in a matrix or in list mode.')
J<-length(x)
if(length(con)!=J)stop('Length of con should equal number of groups')
x=elimna(x)
nv=as.vector(matl(lapply(x,FUN='length')))
nmin=min(nv)
est=NA
p=NA
B=list()
M=matrix(NA,nrow=nmin,ncol=J)
for(i in 1:nreps){
for(j in 1:J)M[,j]=sample(x[[j]],nmin)
B[[i]]=M
}
L=lapply(B,linWMWMC.sub,con=con)
est=lapply(L,locfun)
p=lapply(L,linQS.sub2,locfun=locfun)
est=as.vector(matl(est))
p=as.vector(matl(p))
list(Q.effect=mean(p),center=mean(est))
}




# ----------------------------------------------------------------------------

# linQS.sub2

# ----------------------------------------------------------------------------

#' Helper Function for linQS - Compute Quantile Proportion
#'
#' @description
#' Internal function used by \code{\link{linQS}} to compute the proportion of
#' values below the location measure. Not intended for direct use.
#'
#' @param L Numeric vector of contrast values.
#' @param locfun Location estimator function (default: \code{median}).
#'
#' @details
#' Computes: mean(L - locfun(L) < locfun(L))
#'
#' This is equivalent to the proportion of centered values that are less than
#' the location measure.
#'
#' @return Scalar proportion (0 to 1).
#'
#' @seealso \code{\link{linQS}}
#'
#' @keywords internal
#' @export
linQS.sub2<-function(L,locfun=median){
phat=mean(L-locfun(L)<locfun(L))
phat
}




# ----------------------------------------------------------------------------

# linsign

# ----------------------------------------------------------------------------

#' Estimate Probability that Linear Contrast is Negative
#'
#' @description
#' Estimates the probability that a linear contrast Y = sum(c_j * X_j) is less than zero
#' using resampling.
#'
#' @param x Data in matrix or list format. For matrix: each column is a group.
#'   For list: x[[j]] contains data for group j.
#' @param con Numeric vector of contrast coefficients (length J). Must sum to zero.
#' @param nreps Number of resampling iterations (default: 200).
#' @param SEED Logical. If TRUE (default), sets random seed to 2 for reproducibility.
#' @param nmax Maximum product of sample sizes (default: 10^8). If exceeded, reduces
#'   resampling size to min(nmin, 100).
#'
#' @details
#' This function:
#' \itemize{
#'   \item Resamples equal-sized groups (size = min sample size)
#'   \item Computes linear contrasts for each resampled dataset
#'   \item Estimates P(Y < 0) for each iteration
#'   \item Returns average probability across iterations
#' }
#'
#' When the product of sample sizes exceeds nmax, the resampling size is reduced
#' to prevent excessive computation.
#'
#' @return Scalar probability (0 to 1) that the linear contrast is negative.
#'
#' @seealso \code{\link{linQS}}, \code{\link{linEP}}, \code{\link{linWMWMC.sub}}
#'
#' @export
#' @examples
#' # Estimate P(X1 < X2)
#' set.seed(123)
#' x <- list(rnorm(40), rnorm(40, mean = 0.3))
#' result <- linsign(x, con = c(1, -1), nreps = 500)
#' result  # Probability that group 1 < group 2
linsign<-function(x,con,nreps=200,SEED=TRUE,nmax=10^8){
#
#  Estimate the	probability that a linear contrast is less than	zero
#
if(sum(con)!=0)stop('Contrast coefficients must sum to zero')
if(SEED)set.seed(2)
if(is.data.frame(x))x=as.matrix(x)
if(is.matrix(x))x<-listm(x)
nv=as.vector(matl(lapply(x,FUN='length')))
if(!is.list(x))stop('Data must be stored in a matrix or in list mode.')
J<-length(x)
nv=as.vector(matl(lapply(x,FUN='length')))
if(length(con)!=J)stop('Length of con should equal number of groups')
x=elimna(x)
B=list()
np=prod(nv)
nmin=min(nv)
if(np>nmax)nmin=min(c(nmin,100))
M=matrix(NA,nrow=nmin,ncol=J)
for(i in 1:nreps){
for(j in 1:J)M[,j]=sample(x[[j]],nmin)
B[[i]]=M
}
L=lapply(B,linWMWMC.sub,con=con)
ef.size=NA
for(j in 1:length(L))ef.size[j]=mean(L[[j]]<0)
ef=mean(ef.size)
ef
}

#' Percentile Bootstrap Linear Contrasts for Independent Groups (Trimmed Means)
#'
#' @description
#' Computes percentile bootstrap confidence intervals for linear contrasts of
#' independent groups using trimmed means. Similar to \code{\link{linpbg}} but
#' specialized for trimmed means.
#'
#' @param x Data in matrix or list format. For matrix: each column is a group.
#'   For list: x[[j]] contains data for group j.
#' @param con J×d matrix of contrast coefficients, where J = number of groups and
#'   d = number of contrasts. Default (con=0) performs all pairwise comparisons.
#' @param tr Trimming proportion (default: 0.2).
#' @param alpha Significance level (default: 0.05).
#' @param nboot Number of bootstrap samples (default: NA, automatically determined as
#'   5000 for >4 contrasts, 2000 otherwise).
#'
#' @details
#' This function:
#' \itemize{
#'   \item Assumes independent groups (each group bootstrapped separately)
#'   \item Uses percentile bootstrap with Rom's critical values
#'   \item Automatically removes missing values
#'   \item Sets random seed to 2 for reproducibility
#'   \item Uses trimmed mean (via mean(..., tr)) for location estimation
#' }
#'
#' Example contrasts:
#' \itemize{
#'   \item con[,1] = c(1,1,-1,-1,0,0): sum of first two equals sum of second two
#'   \item con[,2] = c(1,-1,0,0,1,-1): difference in first pair equals difference in second pair
#' }
#'
#' @return
#' List with components:
#' \describe{
#'   \item{psihat}{Matrix with columns: con.num, psihat, ci.lower, ci.upper}
#'   \item{test}{Matrix with columns: con.num, test (p-value), crit.val}
#'   \item{con}{Contrast coefficient matrix used}
#' }
#'
#' @seealso \code{\link{linpbg}} (general estimator version), \code{\link{lindm}} (dependent groups),
#'   \code{\link{linconpb}}
#'
#' @export
#' @examples
#' # Three independent groups
#' set.seed(123)
#' x <- list(rnorm(30), rnorm(30, mean = 0.5), rnorm(30, mean = 0.8))
#'
#' # Linear trend contrast
#' con <- matrix(c(-1, 0, 1), ncol = 1)
#' result <- lintpb(x, con = con, tr = 0.2, nboot = 1000)
lintpb<-function(x,con=0,tr=.2,alpha=.05,nboot=NA){
#
#   Compute a 1-alpha confidence interval
#   for a set of d linear contrasts
#   involving trimmed means using the percentile bootstrap method.
#   Independent groups are assumed.
#
#   The data are assumed to be stored in x in list mode or in a matrix.
#   Thus,
#   x[[1]] contains the data for the first group, x[[2]] the data
#   for the second group, etc.
#   If x has list mode, length(x)=the number of groups = J, say.
#
#   Missing values are automatically removed.
#
#   con is a J by d matrix containing the
#   contrast coefficents of interest.
#   If unspecified, all pairwise comparisons are performed.
#   For example, con[,1]=c(1,1,-1,-1,0,0)
#   and con[,2]=c(,1,-1,0,0,1,-1)
#   will test two contrasts: (1) the sum of the first
#   two trimmed means is
#   equal to the sum of the second two,
#   and (2) the difference between
#   the first two is equal to the difference
#   between the trimmed means of
#   groups 5 and 6.
#
#
con<-as.matrix(con)
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop("Data must be stored in a matrix or in list mode.")
J<-length(x)
for(j in 1:J){
xx<-x[[j]]
xx[[j]]<-xx[!is.na(xx)] # Remove any missing values.
}
Jm<-J-1
d<-(J^2-J)/2
if(sum(con^2)==0){
con<-matrix(0,J,d)
id<-0
for (j in 1:Jm){
jp<-j+1
for (k in jp:J){
id<-id+1
con[j,id]<-1 #If con not specified do all pairwise comparisons
con[k,id]<-0-1
}}}
if(nrow(con)!=length(x)){
stop("The number of groups does not match the number of contrast coefficients.")
}
if(is.na(nboot)){
nboot<-5000
if(ncol(con)<=4)nboot<-2000
}
m1<-matrix(0,nrow=J,ncol=nboot)
set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
print("Taking bootstrap samples. Please wait.")
for(j in 1:J){
paste("Working on group ",j)
data<-matrix(sample(x[[j]],size=length(x[[j]])*nboot,replace=TRUE),nrow=nboot)
m1[j,]<-apply(data,1,mean,tr)
}
testb<-NA
boot<-matrix(0,ncol(con),nboot)
testvec<-NA
for (d in 1:ncol(con)){
boot[d,]<-apply(m1,2,trimpartt,con[,d])
# A vector of length nboot containing psi hat values
# and corresponding to the dth linear contrast
testb[d]<-sum((boot[d,]>0))/nboot
testvec[d]<-min(testb[d],1-testb[d])
}
#
#  Determine critical value
#
dd<-ncol(con)
if(alpha==.05){
if(dd==1)crit<-alpha/2
if(dd==2)crit<-.014
if(dd==3)crit<-.0085
if(dd==4)crit<-.007
if(dd==5)crit<-.006
if(dd==6)crit<-.0045
if(dd==10)crit<-.0023
if(dd==15)crit<-.0016
}
else{
crit<-alpha/(2*dd)
}
icl<-round(crit*nboot)
icu<-round((1-crit)*nboot)
psihat<-matrix(0,ncol(con),4)
test<-matrix(0,ncol(con),3)
dimnames(psihat)<-list(NULL,c("con.num","psihat","ci.lower","ci.upper"))
dimnames(test)<-list(NULL,c("con.num","test","crit.val"))
for (d in 1:ncol(con)){
test[d,1]<-d
psihat[d,1]<-d
testit<-lincon(x,con[,d],tr)
test[d,2]<-testvec[d]
temp<-sort(boot[d,])
psihat[d,3]<-temp[icl]
psihat[d,4]<-temp[icu]
psihat[d,2]<-testit$psihat[1,2]
test[d,3]<-crit
}
list(psihat=psihat,test=test,con=con)
}

#' Form Pairwise Differences Between Two Lists
#'
#' @description
#' Computes element-wise differences between two lists of vectors, creating a new
#' list where each element is the difference x1[[j]] - x2[[j]].
#'
#' @param x1 List of numeric vectors.
#' @param x2 List of numeric vectors (must have same length as x1).
#'
#' @details
#' This utility function is useful for creating difference scores in repeated measures
#' or paired designs. Both lists must have the same length, and corresponding elements
#' should have compatible dimensions for subtraction.
#'
#' @return
#' List with same length as x1 and x2, where dif[[j]] = x1[[j]] - x2[[j]].
#'
#' @seealso \code{\link{yuend}} (for analyzing dependent groups),
#'   \code{\link{rmmcp}} (for multiple comparisons)
#'
#' @export
#' @examples
#' # Create difference scores for paired data
#' x1 <- list(rnorm(20), rnorm(20), rnorm(20))
#' x2 <- list(rnorm(20, mean = 0.5), rnorm(20, mean = 0.3), rnorm(20, mean = 0.4))
#' differences <- list.dif(x1, x2)
#' sapply(differences, mean)
list.dif<-function(x1,x2){
#
# Form all differences
#
if(!is.list(x1))stop('Argument x1 should have list mode')
if(!is.list(x2))stop('Argument x2 should have list mode')
if(length(x1)!=length(x2))stop('x1 and x2 have different lengths')
dif=list()
for(j in 1:length(x1))dif[[j]]=x1[[j]]-x2[[j]]
dif
}




