# lsqs2

# ----------------------------------------------------------------------------

#' Liu-Singh Quality Index for Comparing Two Distributions
#'
#' @description
#' Computes the Liu-Singh quality index Q for comparing two distributions using
#' data depth methods. The index measures the degree of separation between two
#' samples based on how deeply observations from one sample penetrate into the
#' other sample's distribution.
#'
#' @param x Numeric vector or matrix for first group.
#' @param y Numeric vector or matrix for second group.
#' @param MD Logical. If \code{TRUE}, use Mahalanobis depth. If \code{FALSE}
#'   (default), use halfspace depth (exact for p=2, approximate otherwise).
#' @param tr Numeric. Trimming proportion for winsorized variance (default: 0.05).
#'   Only used when \code{MD=TRUE}.
#' @param plotit Logical. If \code{TRUE} (default) and data are bivariate (p=2),
#'   plot the data with depth contours.
#'
#' @return A list with three components (exact content depends on implementation):
#'   \item{qhatxy}{Proportion of x observations with atypical depth in y}
#'   \item{qhatyx}{Proportion of y observations with atypical depth in x}
#'   \item{qhat}{Average of qhatxy and qhatyx}
#'
#' @details
#' The Liu-Singh quality index is based on data depth:
#' \itemize{
#'   \item For univariate data: Uses empirical CDF-based depth
#'   \item For bivariate data (p=2): Uses exact halfspace depth with optional plotting
#'   \item For multivariate data (p>2): Uses approximate halfspace depth (Rousseeuw & Ruts)
#'   \item With \code{MD=TRUE}: Uses Mahalanobis depth based on robust location/scatter
#' }
#'
#' Higher Q values indicate greater separation between distributions.
#'
#' @references
#' Liu, R.Y. and Singh, K. (1993). A quality index based on data depth and
#' multivariate rank tests. Journal of the American Statistical Association,
#' 88, 252-260.
#'
#' @seealso \code{\link{lsqs3}}, \code{\link{depth}}, \code{\link{fdepth}}
#'
#' @keywords multivariate nonparametric
#' @export
lsqs2<-function(x,y,MD=FALSE,tr=.05,plotit=TRUE){
#  cf Liu and Singh, JASA 1993, 252-260
#
if(is.list(x))x<-matl(x)
if(is.list(y))y<-matl(y)
disyx<-NA # depth of y in x
disxy<-NA # depth of x in y
if(!is.matrix(x) && !is.matrix(y)){
x<-x[!is.na(x)]
y<-y[!is.na(y)]
#
tempxx<-NA
for(i in 1:length(x)){
tempxx[i]<-sum(x[i]<=x)/length(x)
if(tempxx[i]>.5)tempxx[i]<-1-tempxx[i]
}
for(i in 1:length(x)){
temp<-sum(x[i]<=y)/length(y)
if(temp>.5)temp<-1-temp
disxy[i]<-mean(temp>tempxx)
}
tempyy<-NA
for(i in 1:length(y)){
tempyy[i]<-sum(y[i]<=y)/length(y)
if(tempyy[i]>.5)tempyy[i]<-1-tempyy[i]
}
for(i in 1:length(y)){
temp<-sum(y[i]<=x)/length(x)
if(temp>.5)temp<-1-temp # depth of y_i in x
disyx[i]<-mean(temp>tempyy)
}
qhatxy<-mean(disyx)
qhatyx<-mean(disxy)
qhat<-(qhatxy+qhatyx)/2
}
if(is.matrix(x) && is.matrix(x)){
if(!MD){
if(ncol(x)!=2 || ncol(y)!=2){
# Use approximate depth
tempyy<-fdepth(y)
temp<-fdepth(y,x)
for(i in 1:nrow(x)){
disxy[i]<-mean(temp[i]>tempyy)
}
tempxx<-NA
tempxx<-fdepth(x)
temp<-fdepth(x,pts=y)
for(i in 1:nrow(y)){
disyx[i]<-mean(temp[i]>tempxx)
}}
if(ncol(x)==2 && ncol(y)==2){
if(plotit){
plot(rbind(x,y),type="n",xlab="Var 1",ylab="VAR 2")
points(x)
points(y,pch="o")
temp<-NA
for(i in 1:nrow(x)){
temp[i]<-depth(x[i,1],x[i,2],x)
}
flag<-(temp>=median(temp))
xx<-x[flag,]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,])
lines(xx[c(temp[1],temp[length(temp)]),])
temp<-NA
for(i in 1:nrow(y)){
temp[i]<-depth(y[i,1],y[i,2],y)
}
flag<-(temp>=median(temp))
xx<-y[flag,]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
flag<-(temp>=median(temp))
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,],lty=2)
lines(xx[c(temp[1],temp[length(temp)]),],lty=2)
}
tempyy<-NA
for(i in 1:nrow(y))tempyy[i]<-depth(y[i,1],y[i,2],y)
for(i in 1:nrow(x)){
temp<-depth(x[i,1],x[i,2],y)
disxy[i]<-mean(temp>tempyy)
}
tempxx<-NA
for(i in 1:nrow(x))tempxx[i]<-depth(x[i,1],x[i,2],x)
for(i in 1:nrow(y)){
temp<-depth(y[i,1],y[i,2],x)
disyx[i]<-mean(temp>tempxx)
}
}}
if(MD){
mx<-apply(x,2,median)
my<-apply(y,2,median)
vx<-apply(x,2,winval,tr=tr)-apply(x,2,mean,trim=tr)+mx
vx<-var(vx)
vy<-apply(y,2,winval,tr=tr)-apply(y,2,mean,trim=tr)+my
vy<-var(vy)
tempxx<-1/(1+mahalanobis(x,mx,vx))
tempyx<-1/(1+mahalanobis(y,mx,vx))
for(i in 1:nrow(y)){
disyx[i]<-mean(tempyx[i]>tempxx)
}
tempyy<-1/(1+mahalanobis(y,my,vy))
tempxy<-1/(1+mahalanobis(x,my,vy))
for(i in 1:nrow(x)){
disxy[i]<-mean(tempxy[i]>tempyy)
}
}
qhatxy<-sum(disxy)
qhatyx<-sum(disyx)
qhat<-(qhatxy+qhatyx)/(length(disxy)+length(disyx))
}
qhatyx<-mean(disyx)
qhatxy<-mean(disxy)
list(qhatxy,qhatyx,qhat)
}

#' Liu-Singh Quality Index with Copula-Based Depth
#'
#' @description
#' Computes the Liu-Singh quality index Q for comparing two multivariate distributions
#' using copula-based depth methods. Provides several depth function options and
#' optional bootstrap p-value testing.
#'
#' @param x Matrix or data frame for first group.
#' @param y Matrix or data frame for second group.
#' @param plotit Logical. If \code{TRUE} (default) and data are bivariate (p=2),
#'   create scatter plot with group indicators.
#' @param cop Integer (1, 2, or 3). Copula choice for computing depth (default: 2):
#'   \itemize{
#'     \item \code{cop=1}: Clayton copula
#'     \item \code{cop=2}: Normal (Gaussian) copula
#'     \item \code{cop=3}: t-copula
#'   }
#' @param ap.dep Logical. If \code{TRUE}, use approximate depth computation.
#'   If \code{FALSE} (default), use exact method.
#' @param v2 Logical. Alternative depth computation method (default: \code{FALSE}).
#' @param pv Logical. If \code{TRUE}, compute bootstrap p-value for testing
#'   equality of distributions (default: \code{FALSE}).
#' @param SEED Logical. If \code{TRUE} (default), set random seed for reproducibility
#'   when computing p-value.
#' @param nboot Integer. Number of bootstrap samples for p-value (default: 1000).
#'   Only used if \code{pv=TRUE}.
#' @param ypch Plot character for y group observations (default: "o").
#' @param xpch Plot character for x group observations (default: "+").
#'
#' @return A list with components:
#'   \item{q.index}{Liu-Singh quality index value}
#'   \item{p.value}{Bootstrap p-value (only if \code{pv=TRUE})}
#'   Additional components may be returned depending on options.
#'
#' @details
#' This function extends \code{\link{lsqs2}} by using copula-based depth functions
#' which can be more powerful for detecting differences in dependence structure.
#'
#' The copula-based approach:
#' \itemize{
#'   \item Transforms marginals to uniform scale
#'   \item Computes depth based on copula-specified dependence
#'   \item May be more sensitive to distributional differences than halfspace depth
#' }
#'
#' @references
#' Liu, R.Y. and Singh, K. (1993). A quality index based on data depth and
#' multivariate rank tests. JASA, 88, 252-260.
#'
#' @seealso \code{\link{lsqs2}}, \code{\link{lsqs3.sub}}
#'
#' @keywords multivariate nonparametric
#' @export
lsqs3<-function(x,y,plotit=TRUE,cop=2,ap.dep=FALSE,v2=FALSE,pv=FALSE,SEED=TRUE,nboot=1000,ypch="o",xpch="+"){
#
#  Compute the typical depth of x in y,
#  Compute the typical depth of y in x,
#  use the maximum of the two typical depths
#  as a test statistic.
#  This method is designed to be sensitive to
#  shifts in location.
#
# Use Tukey's depth; bivariate case only.
#
# cop=2 use MCD location estimator when
# computing depth with function fdepth
# cop=3 uses medians
# cop=3 uses MVE
#
#  xpch="+" means when plotting the data, data from the first
#  group are indicated by a +
#  ypch="o" are data from the second group
#
if(is.list(x))x<-matl(x)
if(is.list(y))y<-matl(y)
x<-elimna(x)
y<-elimna(y)
x<-as.matrix(x)
y<-as.matrix(y)
nx=nrow(x)
ny=nrow(y)
if(ncol(x) != ncol(y))stop("Number of variables not equal")
disyx<-NA # depth of y in x
disxy<-NA # depth of x in y
#
if(ncol(x)==2){
if(plotit){
plot(rbind(x,y),type="n",xlab="VAR 1",ylab="VAR 2")
points(x,pch=xpch)
points(y,pch=ypch)
if(nrow(x)>50){
if(!ap.dep){
print("If execution time is high, might use ap.dep=FALSE")
}
if(!ap.dep)temp<-depth2(x,plotit=FALSE)
if(ap.dep)temp<-fdepth(x,plotit=FALSE,cop=cop)
}
if(!ap.dep)temp<-depth2(x,plotit=FALSE)
if(ap.dep)temp<-fdepth(x,plotit=FALSE,cop=cop)
flag<-(temp>=median(temp))
xx<-x[flag,]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,])
lines(xx[c(temp[1],temp[length(temp)]),])
if(ap.dep)temp<-fdepth(y,plotit=FALSE,cop=cop)
if(!ap.dep)temp<-depth2(y,plotit=FALSE)
if(!ap.dep)temp<-depth2(y,plotit=FALSE)
if(!ap.dep)temp<-fdepth(y,plotit=FALSE)
flag<-(temp>=median(temp))
xx<-y[flag,]
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
flag<-(temp>=median(temp))
xord<-order(xx[,1])
xx<-xx[xord,]
temp<-chull(xx)
lines(xx[temp,],lty=2)
lines(xx[c(temp[1],temp[length(temp)]),],lty=2)
}
tempyx<-NA
tempxy<-NA
if(ap.dep)tempyx<-fdepth(x,y,plotit=FALSE,cop=cop)
if(!ap.dep)tempyx<-depth2(x,y,plotit=FALSE)
if(ap.dep)tempxy<-fdepth(y,x,plotit=FALSE,cop=cop)
if(!ap.dep)tempxy<-depth2(y,x,plotit=FALSE)
}
if(ncol(x)==1){
tempyx<-unidepth(as.vector(x),as.vector(y))
tempxy<-unidepth(as.vector(y),as.vector(x))
}
if(ncol(x)>2){
if(!v2){
tempxy<-fdepth(y,x,plotit=FALSE,cop=cop)
tempyx<-fdepth(x,y,plotit=FALSE,cop=cop)
}
if(v2){
tempxy<-fdepthv2(y,x,plotit=FALSE)
tempyx<-fdepthv2(x,y,plotit=FALSE)
}}
qhatxy<-mean(tempxy)
qhatyx<-mean(tempyx)
qhat<-max(c(qhatxy,qhatyx))
n1<-nrow(x)
n2<-nrow(y)
nv<-(3*min(c(n1,n2))+max(c(n1,n2)))/4
if(ncol(x)==1)crit<-.2536-.4578/sqrt(nv)
if(ncol(x)==2)crit<-.1569-.3/sqrt(nv)
if(ncol(x)==3)crit<-.0861-.269/sqrt(nv)
if(ncol(x)==4)crit<-.054-.1568/sqrt(nv)
if(ncol(x)==5)crit<-.0367-.0968/sqrt(nv)
if(ncol(x)==6)crit<-.0262-.0565/sqrt(nv)
if(ncol(x)==7)crit<-.0174-.0916/sqrt(nv)
if(ncol(x)>7)crit<-.013
rej<-"Fail to reject"
if(qhat<=crit)rej<-"Reject"
testv=NULL
pval=NULL
if(pv){
if(SEED)set.seed(2)
rej="NULL"
for(i in 1:nboot)testv[i]=lsqs3.sub(rmul(n1,ncol(x)),rmul(n2,ncol(x)),cop=cop,ap.dep=ap.dep,v2=v2,)$test
pval=mean(qhat>=testv)
}
list(n1=nx,n2=ny,avg.depth.of.x.in.y=qhatxy,avg.depth.of.y.in.x=qhatyx,test=qhat,crit=crit,Decision=rej,p.value=pval)
}

