# ord.loc.ex

# ----------------------------------------------------------------------------

#' Determine Order of Trimmed Means and Extract P-values
#'
#' @description
#' Determines the order of population trimmed means across groups and extracts
#' the p-values for testing adjacent pairs in the ordering.
#'
#' @param x Data. Can be a matrix, data frame, or list.
#' @param alpha Significance level. Default is 0.05.
#' @param tr Trimming proportion. Default is 0.2 (20% trimming).
#'
#' @details
#' Groups are ordered by their trimmed means, then adjacent pairs in the ordering
#' are tested using \code{\link{yuen}}. This function extracts p-values without
#' making formal decisions about ordering. For formal decision-making, use
#' \code{\link{ord.loc.PV}}.
#'
#' @return Vector of p-values for tests of adjacent pairs in the ordering.
#'
#' @seealso \code{\link{ord.loc.PV}}, \code{\link{ord.loc.crit}}, \code{\link{yuen}}
#'
#' @keywords htest robust
#' @export
ord.loc.ex<-function(x,alpha=.05,tr=.2){
#
#
#  Determine the order of the population trimmed means.
#  Can a decision be made that the correct order has been identified?
#
#  p.crit:  If NULL, critical p-values are determined so that that FWE is alpha
#  This is done using a simulation to determine the null distribution based on
#  iter=5000 replications.
#
#
#  Returns:
#   ORD='No Decision' if a complete ordering cannot be made.
#   DEC= the pairs of  group for which a decision can be made
#
#   Confidence intervals having simultaneous probability coverage 1-alpha
#  using the adjusted level.
#
x=elimna(x)
if(is.matrix(x))x=listm(x)
J=length(x)
if(J<3)stop('Should have 3 or more groups')
Jm1=J-1
est=lapply(x,tmean,tr=tr)
n=lapply(x,length)
est=matl(est)
n=as.vector(matl(n))
R=order(est)
ic=0
pvec=NA
for(i in 2:J){
im1=i-1
a=yuen(x[[R[im1]]],x[[R[[i]]]])
ic=ic+1
pvec[ic]=a$p.value
}
pvec
}

#' Test and Determine Ordering of Trimmed Means with FWE Control
#'
#' @description
#' Determines whether a complete ordering of population trimmed means can be
#' established across J groups, controlling family-wise error rate (FWE).
#'
#' @param x Data. Can be a matrix, data frame, or list. Must have at least 3 groups.
#' @param p.crit Vector of critical p-values for each test. If \code{NULL}, determined
#'   via simulation. Default is \code{NULL}.
#' @param alpha Significance level for FWE control. Default is 0.05.
#' @param tr Trimming proportion. Default is 0.2 (20% trimming).
#' @param iter Number of simulation iterations for determining critical p-values.
#'   Default is 5000.
#' @param SEED Logical. Set random seed for reproducibility. Default is \code{TRUE}.
#'
#' @details
#' Groups are sorted by trimmed mean estimates, then adjacent pairs (j, j+1) are
#' tested for j=1,...,J-1. FWE is controlled using a method designed specifically
#' for this ordering problem. A complete ordering decision is made only if all J-1
#' tests reject the null hypothesis.
#'
#' @return An S4 object of class 'BIN' with slots:
#' \item{Make.a.Decison}{'YES' if complete ordering established, 'NO' otherwise.}
#' \item{Decision.p.value}{Overall p-value for the ordering decision.}
#' \item{Estimates}{Trimmed mean estimates for all groups.}
#' \item{n}{Sample sizes for all groups.}
#' \item{output}{Matrix with detailed results for each pairwise test.}
#'
#' @seealso \code{\link{ord.loc.ex}}, \code{\link{ord.loc.crit}}, \code{\link{yuen}}
#'
#' @keywords htest robust
#' @export
ord.loc.PV<-function(x,p.crit=NULL,alpha=.05,tr=.2,iter=5000,SEED=TRUE){
#
#
#  Determine the order of the population trimmed means.
#  Can a decision be made that the correct order has been identified?
#
#  p.crit:  If NULL, critical p-values are determined so that that FWE is alpha
#  This is done using a simulation to determine the null distribution based on
#  iter=5000 replications.
#
#  Strategy: For J groups, sort the  groups so that estimates of the trimmed mean are in ascending order.
# Next,  compare group j  to j+1, j=1, ... J-1
#  FWE is controlled using a method designed specifically for the problem at hand.
#   If all J-1 hypotheses are rejected, make a decision
#
#  Returns:
#   ORD='No Decision' if a decision about complete ordering cannot be made.
#   output: contains the results for each of the J-1 tests.
#
#   Confidence intervals having simultaneous probability coverage 1-alpha
#  using the adjusted level.
#
if(is.vector(x))stop('x should be a matrix with ncol>2, or data.frame or list mode with length >2')
x=elimna(x)
if(is.matrix(x))x=listm(x)
J=length(x)
if(J<3)stop('Should have 3 or more groups')
Jm1=J-1
est=lapply(x,tmean,tr=tr)
n=lapply(x,length)
est=matl(est)
n=as.vector(matl(n))
R=order(est)
pvec=NA
aval=c(seq(.001,.1,.001),seq(.11,.99,.01))
if(length(id)==0)stop('alpha must be one of values .001(.001).1 or 11(.01).99')
v=ord.loc.crit.det(J=J,n=n,iter=iter,alpha=alpha,SEED=SEED)
p.crit=v[id,]

pvdist=NULL
if(is.null(p.crit)){
v=ord.loc.crit(J=J,n=n,iter=iter,alpha=alpha,SEED=SEED)
p.crit=v$fin.crit
pvdist=v$pvdist
}
output<-matrix(NA,Jm1,9)
dimnames(output)=list(NULL,c('Grp.L','Grp.R','Est.L','Est.R','Dif','ci.low','ci.up','p.value','p.crit'))
for(i in 2:J){
im1=i-1
a=yuen(x[[R[im1]]],x[[R[[i]]]],alpha=p.crit[im1])
pvec[im1]=a$p.value
output[im1,]=c(R[im1],R[i],a$est.1,a$est.2,a$dif,a$ci[1],a$ci[2],a$p.value,p.crit[im1])
}
dpv=NA
if(!is.null(pvdist)){
chk=0
for(i in 1:iter){
flag=0
for(j in 1:Jm1)if(pvdist[i,j]<=output[j,7])flag=flag+1
if(flag>0)chk=chk+1
}
dpv=chk/iter
}
# Determine p-value for overall decision
na=length(aval)
for(i in 1:na){
chk=sum(output[,7]<=v[i,])
pv=aval[i]
if(chk==Jm1)break
}
ORD.ID='NO'
id=output[,8]<=output[,9]
if(sum(id)==Jm1)ORD.ID='YES'
# setClass('BIN',slots=c('Make.a.Decison','Decision.p.value','Estimates','n','output'))  # Defined in .onLoad
put=new('BIN',Make.a.Decison=ORD.ID,Decision.p.value=pv,Estimates=est,n=n,output=output)
put
}

#' Determine Critical P-values for Ordering Test
#'
#' @description
#' Determines critical p-values for testing the ordering of trimmed means using
#' simulation under the null hypothesis of equal population trimmed means.
#'
#' @param J Number of groups.
#' @param n Sample size per group (can be a vector for unequal sample sizes). Default is 30.
#' @param alpha Significance level. Default is 0.05.
#' @param tr Trimming proportion. Default is 0.2 (20% trimming).
#' @param iter Number of simulation iterations. Default is 5000.
#' @param SEED Logical. Set random seed for reproducibility. Default is \code{TRUE}.
#'
#' @details
#' Simulates data under the null hypothesis of equal trimmed means to determine
#' critical p-values that control FWE for the ordering problem. Used internally
#' by \code{\link{ord.loc.PV}} when critical p-values are not provided.
#'
#' @return A list with components containing critical p-values and the simulated
#' p-value distribution.
#'
#' @seealso \code{\link{ord.loc.PV}}, \code{\link{ord.loc.ex}}
#'
#' @keywords htest
#' @export
ord.loc.crit<-function(J,n=30,alpha=.05,tr=.2,iter=5000,SEED=TRUE){
#
#  Determine critical p-values for ord.loc
#
if(SEED)set.seed(2)
Jm1=J-1
rem=matrix(NA,iter,Jm1)
for(k in 1:iter){
if(length(n)==1){
x=rmul(n,p=J)
x=listm(x)
}
else{
x=list()
if(length(n)!=J)stop('J is not equal to the length  of n')
for(j in 1:J)x[[j]]=rnorm(n[j])
}
rem[k,]=ord.loc.ex(x,tr=tr)
}
init=apply(rem,2,qest,alpha)
#print(apply(rem,2,mean))
#print(init)
z=optim(0,ord.loc.fun,init=init,iter=iter,rem=rem,Jm1=Jm1,alpha=alpha,method='Brent',lower=0,upper=1)
fin.crit=z$par*init
list(fin.crit=fin.crit,pvdist=rem)
}




# ----------------------------------------------------------------------------

# ord.loc.fun

# ----------------------------------------------------------------------------

#' Objective Function for Ordinal Location Test Critical Values (Internal)
#'
#' @description
#' Internal optimization objective function for determining critical p-values
#' in ordinal location tests. Used by \code{\link{ord.loc.crit.det}}.
#'
#' @param a Numeric scaling parameter being optimized.
#' @param init Numeric vector of initial critical value estimates.
#' @param iter Integer. Number of iterations/simulations.
#' @param rem Matrix of simulated p-values (iter × Jm1).
#' @param Jm1 Integer. Number of groups minus 1 (J-1).
#' @param alpha Numeric. Target alpha level.
#'
#' @return Absolute difference between empirical and target alpha level.
#'
#' @keywords internal
ord.loc.fun<-function(a,init,iter,rem,Jm1,alpha){
#
chk=0
init=a*init
for(i in 1:iter){
flag=0
for(j in 1:Jm1)if(rem[i,j]<=init[j])flag=flag+1
if(flag>0)chk=chk+1
}
chk=chk/iter
dif=abs(chk-alpha)
dif
}

#' Determine Critical P-Values for Ordinal Location Tests
#'
#' @description
#' Determines critical p-values for ordinal location tests via simulation.
#' Used internally by functions like \code{anc.best} to establish appropriate
#' decision thresholds for multiple comparisons.
#'
#' @param J Integer. Number of groups.
#' @param n Integer or vector of sample sizes. If length 1, equal sample sizes
#'   are assumed; if length J, specifies size for each group.
#' @param alpha Numeric. Nominal alpha level (default: 0.05).
#' @param tr Numeric. Proportion of trimming (default: 0.2).
#' @param iter Integer. Number of simulation iterations (default: 5000).
#' @param SEED Logical. If \code{TRUE}, sets random seed to 2 (default: \code{TRUE}).
#'
#' @return Matrix (na × Jm1) of critical p-values, where na is number of alpha
#'   values tested and Jm1 = J-1.
#'
#' @keywords internal
ord.loc.crit.det<-function(J,n,alpha=.05,tr=.2,iter=5000,SEED=TRUE){
#
#  Determine critical p-values for anc.best
#
if(SEED)set.seed(2)
Jm1=J-1
rem=matrix(NA,iter,Jm1)
for(k in 1:iter){
if(length(n)==1){
x=rmul(n,p=J)
x=listm(x)
}
else{
x=list()
if(length(n)!=J)stop('J is not equal to the length  of n')
for(j in 1:J)x[[j]]=rnorm(n[j])
}
rem[k,]=ord.loc.ex(x,tr=tr)
}
aval=c(seq(.001,.1,.001),seq(.011,.99,.01))
na=length(aval)
fin.crit=matrix(NA,na,Jm1)
for(i in 1:na){
init=apply(rem,2,qest,aval[i])
z=optim(0,ord.loc.fun,init=init,iter=iter,rem=rem,Jm1=Jm1,alpha=aval[i],method='Brent',lower=0,upper=1)
fin.crit[i,]=z$par*init
}
fin.crit
}

#' Orthonormalize a Matrix
#'
#' @description
#' Performs orthonormalization of a matrix using QR decomposition.
#'
#' @param x A numeric matrix to orthonormalize.
#'
#' @return An orthonormal matrix with the same dimensions as \code{x}.
#'   The columns are orthogonal (perpendicular) to each other and have unit length.
#'
#' @details
#' This function uses QR decomposition via \code{\link{qr}} and extracts the
#' orthonormal Q matrix via \code{\link{qr.Q}}. The resulting matrix has
#' orthonormal columns, meaning each column has length 1 and all pairs of
#' columns are orthogonal (have dot product 0).
#'
#' @keywords array algebra
#' @export
ortho<-function(x){
# Orthnormalize x
#
y<-qr(x)
y<-qr.Q(y)
y
}




# ----------------------------------------------------------------------------

# OS.lasso

# ----------------------------------------------------------------------------

#' Outlier Shifting LASSO Regression
#'
#' @description
#' Performs robust LASSO regression by identifying and shifting outliers in the
#' response variable. This method is designed for regression with highly corrupted
#' responses.
#'
#' @param x Matrix or data frame of predictor variables.
#' @param y Vector of response values.
#' @param lambda.lasso.try Vector of LASSO penalty parameters to try in cross-validation.
#'   Default is sequence from 0.01 to 0.6 with 100 values.
#' @param lambda.gamma.try Vector of outlier shifting penalty parameters to try.
#'   Default is sequence from 1 to 4 with 50 values.
#' @param xout Logical. If \code{TRUE}, remove outliers from predictor space before fitting.
#'   Default is \code{FALSE}.
#' @param outfun Function for detecting outliers in predictor space. Default is \code{\link{outpro}}.
#' @param details Logical. If \code{TRUE}, return detailed diagnostic information.
#'   Default is \code{FALSE}.
#' @param ... Additional arguments passed to outlier detection function.
#'
#' @return If \code{details=FALSE} (default), a list with:
#'   \item{coef}{Regression coefficients (including intercept)}
#'   \item{residuals}{Residuals from the fitted model}
#'
#'   If \code{details=TRUE}, additional components:
#'   \item{fit}{LASSO fitted values}
#'   \item{iter}{Number of iterations until convergence}
#'   \item{sigma.est}{Estimated error standard deviation (MAD-based)}
#'   \item{CV.error}{Cross-validation errors for different gamma values}
#'   \item{n.outlier}{Number of detected outliers in response}
#'   \item{gamma.est}{Estimated outlier shifts}
#'   \item{lambda.opt}{Optimal outlier shifting penalty parameter}
#'
#' @details
#' The Outlier Shifting LASSO uses an iterative algorithm:
#' \enumerate{
#'   \item Fit LASSO regression to obtain initial estimates
#'   \item Identify outliers as residuals exceeding sigma * lambda.gamma
#'   \item Shift these outliers by their residual values
#'   \item Re-fit LASSO on the shifted response
#'   \item Iterate until convergence
#' }
#'
#' Both the LASSO penalty and outlier shifting penalty are selected via 5-fold
#' cross-validation. Missing values are automatically removed.
#'
#' @references
#' Jung, Y., Lee, S., and Hu, J. (2016). Robust regression for highly corrupted
#' response by shifting outliers. Statistical Modelling, 16(1):1--23.
#'
#' @seealso \code{\link{H.lasso}}, \code{\link{LAD.lasso}}
#'
#' @keywords robust regression
#' @export
OS.lasso<- function(x,y,lambda.lasso.try=NULL,lambda.gamma.try=NULL,xout=FALSE,outfun=outpro,details=FALSE,...){
#
# Outlier Shifting lasso
# Jung, Y., Lee, S., and Hu, J. (2016). Robust regression for highly corrupted response
# by shifting outliers. Statistical Modelling, 16(1):1--23.
#
#
X=x
Y=y
if(is.null(lambda.lasso.try))lambda.lasso.try=seq(0.01,0.6,length.out=100)
if(is.null(lambda.gamma.try))lambda.gamma.try = seq(1,4,length.out=50)
library(glmnet)
X<-as.matrix(X)
p1<-ncol(X)+1
p<-ncol(X)
xy<-cbind(X,Y)
xy<-elimna(xy)
X<-xy[,1:p]
Y<-xy[,p1]
if(xout){
X<-as.matrix(X)
flag<-outfun(X,plotit=FALSE,...)$keep
X<-X[flag,]
Y<-Y[flag]
X<-as.matrix(X)
n.keep=nrow(X)
}
x=X
y=Y
n<-length(Y)
Y.orgn<- Y
model.for.cv<- cv.glmnet(X, Y, family="gaussian",lambda=lambda.lasso.try)
lambda.lasso.opt<- model.for.cv$lambda.min
model.est<- glmnet(X,Y,family="gaussian",lambda=lambda.lasso.opt)
fit.lasso<- predict(model.est,X,s=lambda.lasso.opt)
res.lasso<- Y - fit.lasso
sigma.est<- mad(Y-fit.lasso)
beta.est<- as.numeric(model.est$beta)
gamma.est<-rep(0,n)
n.fold<- 5
n.cv <- n/n.fold
CV.error2<-CV.error<-rep(NA,length(lambda.gamma.try))
Y.pred.cv<-matrix(NA,nrow=length(Y),ncol=length(lambda.gamma.try))
Y.new<- Y
for (tt in 1:length(lambda.gamma.try))
{
gamma.est.cv<-rep(0,n-n.cv)
for (jj in 1:n.fold)
{
sample.out.index<- (1+n.cv*(jj-1)):(n.cv*(jj))
X.train<- X[-sample.out.index,]
Y.train<- Y[-sample.out.index]
X.test<- X[sample.out.index,]
model.train.temp<- glmnet(X.train,Y.train,family="gaussian",
lambda=lambda.lasso.opt)
beta.pre<-beta.post<- c(model.train.temp$a0,
as.numeric(model.train.temp$beta))
tol<-100; n.iter <- 0
while(tol>1e-6 & n.iter<100)
{resid.temp<- Y.train-cbind(rep(1,n-n.cv),X.train)%*%beta.pre
nonzero<-which(abs(resid.temp)>=sigma.est*lambda.gamma.try[tt])
gamma.est.cv[nonzero]<- resid.temp[nonzero]
Y.train.new <- Y.train - gamma.est.cv
model.train.temp<-glmnet(X.train,Y.train.new,
family="gaussian",lambda=lambda.lasso.opt)
beta.post <- c(model.train.temp$a0,
as.numeric(model.train.temp$beta))
tol<- sum((beta.pre-beta.post)^2)
n.iter<- n.iter+1
beta.pre<-beta.post
}
Y.pred.cv[sample.out.index,tt] <-cbind(rep(1,n.cv),
X.test)%*%beta.post
}
CV.error[tt]<- mean((Y.pred.cv[,tt]-Y.orgn)^2)
CV.error2[tt]<- mean(abs(Y.pred.cv[,tt]-Y.orgn))
}
lambda.gamma.opt<- lambda.gamma.try[which.min(CV.error)]
model.opt<- glmnet(X,Y.orgn,family="gaussian",lambda=lambda.lasso.opt)
beta.pre<- beta.post<- c(model.opt$a0,as.numeric(model.opt$beta))
tol<-100; n.iter <- 0
while(tol>1e-6 & n.iter<100)
{
resid.opt<- Y.orgn-cbind(rep(1,n),X)%*%beta.pre
nonzero<-which(abs(resid.opt)>=sigma.est*lambda.gamma.opt)
gamma.est[nonzero]<- resid.opt[nonzero]
Y.new <- Y.orgn - gamma.est
model.opt<- glmnet(X,Y.new,family="gaussian",lambda=lambda.lasso.opt)
beta.post <- c(model.opt$a0,as.numeric(model.opt$beta))
tol<- mean((beta.pre-beta.post)^2)
n.iter<- n.iter+1
beta.pre<-beta.post}
Y.fit<- cbind(rep(1,n),X)%*%beta.post
res=y-Y.fit
if(details)
list(coef=beta.post,fit=fit.lasso,iter = n.iter,
sigma.est = sigma.est,CV.error=CV.error,
n.outlier=length(which(gamma.est!=0)),
gamma.est=gamma.est,lambda.opt=lambda.gamma.opt)
else list(coef=beta.post,residuals=res)
}

