# qghdist

# ----------------------------------------------------------------------------

#' Quantile of a g-and-h Distribution
#'
#' @description
#' Computes the quantile of a g-and-h distribution. The g-and-h distribution
#' is a flexible parametric family useful for modeling heavy-tailed and/or
#' skewed data.
#'
#' @param q Numeric value in (0,1). Quantile to compute (default: 0.5).
#' @param g Numeric. Skewness parameter (default: 0).
#' @param h Numeric. Tail weight parameter (default: 0).
#'
#' @return Numeric value representing the q-th quantile of the g-and-h distribution
#'   with specified parameters.
#'
#' @details
#' Applies the g-and-h transformation to the q-th standard normal quantile.
#' When g=0 and h=0, returns standard normal quantiles.
#'
#' @seealso \code{\link{ghtransform}}, \code{\link{pghdist}}
#'
#' @keywords distribution
#' @export
qghdist<-function(q=.5,g=0,h=0){
#
# Determine quantile of a g-and-h distribution
#
e=qnorm(q)
v=ghtransform(e,g=g,h=h)
v
}

#' Test Homoscedasticity Using Quantile Regression Slopes
#'
#' @description
#' Tests the hypothesis that the error term is homogeneous by comparing quantile
#' regression slopes. Computes a bootstrap confidence interval for the difference
#' between two quantile regression slopes (default: 0.8 quantile slope minus
#' 0.2 quantile slope).
#'
#' @param x Numeric vector or matrix with one column (predictor variable).
#' @param y Numeric vector (response variable).
#' @param nboot Integer. Number of bootstrap samples (default: 100).
#' @param alpha Numeric. Alpha level for confidence interval (default: 0.05).
#' @param qval Numeric vector of length 2 specifying which quantiles to compare
#'   (default: c(.2,.8)). Tests difference qval[2] - qval[1].
#' @param plotit Logical. If \code{TRUE}, plots the quantile regression lines
#'   (default: \code{TRUE}).
#' @param SEED Logical. If \code{TRUE}, sets random seed to 2 (default: \code{TRUE}).
#' @param pch Plotting character (default: '*').
#' @param xlab Character string for x-axis label (default: "X").
#' @param ylab Character string for y-axis label (default: "Y").
#' @param xout Logical. If \code{TRUE}, removes outliers from predictors using
#'   \code{outfun} (default: \code{FALSE}).
#' @param outfun Function for outlier detection (default: \code{\link{outpro}}).
#' @param pr Logical. If \code{TRUE}, prints progress messages (default: \code{TRUE}).
#' @param WARN Logical. If \code{FALSE}, suppresses warnings (default: \code{FALSE}).
#' @param ... Additional arguments passed to \code{outfun}.
#'
#' @return List with components:
#' \describe{
#'   \item{slope.bottom}{Slope estimate for lower quantile (qval[1])}
#'   \item{slope.top}{Slope estimate for upper quantile (qval[2])}
#'   \item{dif.est}{Estimated difference in slopes}
#'   \item{dif.ci}{Bootstrap confidence interval for difference}
#'   \item{p.value}{Two-sided p-value}
#'   \item{se}{Standard error of difference}
#'   \item{adjusted.ci}{Adjusted CI (when alpha=.05 and qval=c(.2,.8))}
#' }
#'
#' @details
#' Uses Koenker-Bassett quantile regression. If slopes differ significantly,
#' suggests heteroscedasticity. Only works with one predictor; use \code{\link{qhomtv2}}
#' for multiple predictors.
#'
#' @seealso \code{\link{qhomtv2}}, \code{\link{qplotreg}}
#'
#' @keywords htest regression
#' @export
qhomt<-function(x,y,nboot=100,alpha=.05,qval=c(.2,.8),plotit=TRUE,SEED=TRUE,pch='*',
xlab="X",ylab="Y",xout=FALSE,outfun=outpro,pr=TRUE,WARN=FALSE,...){
#
#   Test hypothesis that the error term is  homogeneous by
#   computing a confidence interval for beta_1-beta_2, the
#   difference between the slopes of the qval[2] and qval[1]
#   regression slopes, where qval[1] and qval[2] are
#   the quantile regression slopes
#   estimated via the Koenker-Bassett method.
#   So by default, use the .8 quantile slope minus the
#   the .2 quantile slope.
#
if(length(qval)!=2)stop("Argument qval should have 2 values exactly")
x<-as.matrix(x)
if(ncol(x)!=1)stop("Only one predictor is allowed; use qhomtv2")
xy<-elimna(cbind(x,y))
x<-xy[,1]
x<-as.matrix(x)
y<-xy[,2]
if(xout){
flag<-outfun(x,...)$keep
x<-as.matrix(x)
x<-x[flag,]
y<-y[flag]
x<-as.matrix(x)
}
if(SEED)set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
if(!WARN)options(warn=-1)
if(pr)print("Taking bootstrap samples. Please wait.")
data<-matrix(sample(length(y),size=length(y)*nboot,replace=TRUE),nrow=nboot)
bvec<-apply(data,1,qhomtsub,x,y,qval) # An nboot vector.
se<-sqrt(var(bvec))
temp<-qplotreg(x,y,qval=qval,plotit=plotit,xlab=xlab,ylab=ylab,pch=pch)
crit<-qnorm(1-alpha/2)
crit.ad<-NA
dimnames(temp)=c(NULL,NULL)
dif<-temp[2,2]-temp[1,2]
regci<-NA
regci[1]<-dif-crit*se
regci[2]<-dif+crit*se
sig.level<-2*(1-pnorm(abs(dif)/se))
regci.ad<-NA
if(alpha==.05 && qval[1]==.2 && qval[2]==.8)crit.ad<-qnorm(0-.09/sqrt(length(y))+.975)
ci.ad<-c(dif-crit.ad*se,dif+crit.ad*se)
if(!WARN)options(warn=0)
list(slope.bottom=temp[1,2],slope.top=temp[2,2],
dif.est=dif,dif.ci=regci,p.value=sig.level,se=se,adjusted.ci=ci.ad)
}



#' Bootstrap Helper for Homoscedasticity Test (Internal)
#'
#' @description
#' Internal helper function for \code{\link{qhomt}}. Computes the difference
#' between two quantile regression slopes for a bootstrap sample.
#'
#' @param isub Integer vector of bootstrap sample indices.
#' @param x Numeric vector or matrix (predictor).
#' @param y Numeric vector (response).
#' @param qval Numeric vector of length 2 specifying quantiles to compare.
#'
#' @return Numeric value representing the difference in slopes (qval[2] - qval[1]).
#'
#' @keywords internal
qhomtsub<-function(isub,x,y,qval){
#
#  Perform quantile regression using x[isub] to predict y[isub]
#  isub is a vector of length n,
#  a bootstrap sample from the sequence of integers
#  1, 2, 3, ..., n
#
#  This function is used by other functions when computing
#  bootstrap estimates.
#
#  regfun is some regression method already stored in R
#  It is assumed that regfun$coef contains the  intercept and slope
#  estimates produced by regfun.  The regression methods written for
#  this  book, plus regression functions in R, have this property.
#
#  x is assumed to be a matrix containing values of the predictors.
#
xmat<-matrix(x[isub,],nrow(x),ncol(x))
temp<-qplotreg(xmat,y[isub],qval=qval,plotit=FALSE)
regboot<-temp[1,2]-temp[2,2]
regboot
}

#' @title Bootstrap Helper for Quantile Regression Slope Estimation
#'
#' @description
#' Internal bootstrap helper function that performs quantile regression on a
#' bootstrap sample and returns the slope coefficients. Used by \code{\link{qhomtv2}}
#' for homoscedasticity testing.
#'
#' @param isub Integer vector of bootstrap sample indices (length n)
#' @param x Numeric matrix of predictor values
#' @param y Numeric vector of response values
#' @param qval Numeric value specifying the quantile (0 < qval < 1)
#'
#' @return Numeric vector of slope coefficients (excluding intercept) from
#'   quantile regression fit on the bootstrap sample
#'
#' @seealso \code{\link{qhomtv2}}, \code{\link{rqfit}}
#'
#' @keywords internal
#' @export
qhomtsub2<-function(isub,x,y,qval){
#
#  Perform quantile regression using x[isub] to predict y[isub]
#  isub is a vector of length n,
#  a bootstrap sample from the sequence of integers
#  1, 2, 3, ..., n
#
#  This function is used by other functions when computing
#  bootstrap estimates.
#
#  regfun is some regression method already stored in R
#  It is assumed that regfun$coef contains the  intercept and slope
#  estimates produced by regfun.  The regression methods written for
#  this  book, plus regression functions in R, have this property.
#
#  x is assumed to be a matrix containing values of the predictors.
#
xmat<-matrix(x[isub,],nrow(x),ncol(x))
pp<-ncol(x)+1
temp<-rqfit(xmat,y[isub],qval)$coef[2:pp]
temp
}




# ----------------------------------------------------------------------------

# qhomtv2

# ----------------------------------------------------------------------------

#' @title Test for Homoscedasticity Using Quantile Regression
#'
#' @description
#' Tests the hypothesis of homoscedasticity by computing a bootstrap confidence
#' interval for the difference between quantile regression slopes at two different
#' quantiles. By default, compares the 0.8 and 0.2 quantile slopes using the
#' Koenker-Bassett method.
#'
#' @param x Numeric matrix or vector of predictor variable(s)
#' @param y Numeric vector of response variable
#' @param nboot Integer specifying number of bootstrap samples (default: 100)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param qval Numeric vector of length 2 specifying quantiles to compare
#'   (default: c(0.2, 0.8))
#' @param SEED Logical; if TRUE, set random seed for reproducibility (default: TRUE)
#' @param WARN Logical; if FALSE, suppress warnings (default: FALSE)
#'
#' @return Matrix with columns: "Est 1" (slope at qval[1]), "Est 2" (slope at qval[2]),
#'   "Dif" (difference), "SE" (standard error), "ci.lower", "ci.upper", "p.value"
#'
#' @details
#' Under homoscedasticity, the quantile regression slopes should be similar across
#' quantiles. Large differences suggest heteroscedasticity. Adjusted confidence
#' intervals are used when alpha=0.05 and qval=c(0.2, 0.8).
#'
#' @note
#' The function prints messages about adjusted confidence intervals and that
#' familywise error is not controlled.
#'
#' @seealso \code{\link{qhomtsub2}}, \code{\link{rqfit}}, \code{\link{qhomt}}
#'
#' @keywords htest
#' @export
qhomtv2<-function(x,y,nboot=100,alpha=.05,qval=c(.2,.8),SEED=TRUE,WARN=FALSE){
#
#   Test hypothesis of homoscedasticiy  by
#   computing a confidence interval for beta_1-beta_2, the
#   difference between the slopes of the qval[2] and qval[1]
#   regression slopes, where qval[1] and qval[2] are
#   the quantile regression slopes
#   estimated via the Koenker-Bassett method.
#   So by default, use the .8 quantile slope minus the
#   the .2 quantile slope.
#
print("Note: adjusted confidence intervals are used;")
print("they can differ from p-values")
print("FWE is not controlled")
if(length(qval)!=2)stop("Argument qval should have 2 values")
x<-as.matrix(x)
p<-ncol(x)
xy<-elimna(cbind(x,y))
x<-xy[,1:p]
x<-as.matrix(x)
pp<-p+1
y<-xy[,pp]
if(!WARN)options(warn=-1)
if(SEED)set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
print("Taking bootstrap samples. Please wait.")
data<-matrix(sample(length(y),size=length(y)*nboot,replace=TRUE),nrow=nboot)
bvec1<-apply(data,1,qhomtsub2,x,y,qval[1]) # A p by nboot matrix
bvec2<-apply(data,1,qhomtsub2,x,y,qval[2])
bvec1<-as.matrix(bvec1)
bvec2<-as.matrix(bvec2)
if(p==1){
bvec1<-t(bvec1)
bvec2<-t(bvec2)
}
se<-NA
for(j in 1:p)se[j]<-sqrt(var(bvec1[j,]-bvec2[j,]))
temp1<-rqfit(x,y,qval[1])$coef[2:pp]
temp2<-rqfit(x,y,qval[2])$coef[2:pp]
crit<-qnorm(1-alpha/2)
crit.ad<-NA
dif<-temp2-temp1
regci<-NA
regci1<-dif-crit*se
regci2<-dif+crit*se
sig.level<-2*(1-pnorm(abs(dif)/se))
regci.ad<-NA
if(alpha==.05 && qval[1]==.2 && qval[2]==.8)
crit.ad<-qnorm(0-.09/sqrt(length(y))+.975)
output<-matrix(NA,ncol=7,nrow=p)
dimnames(output)<-list(NULL,c("Est 1","Est 2","Dif","SE",
"ci.lower","ci.upper","p.value"))
output[,1]<-temp1
output[,2]<-temp2
output[,3]<-dif
output[,4]<-se
output[,5]<-regci1
output[,6]<-regci2
output[,7]<-sig.level
ci.ad<-c(dif-crit.ad*se,dif+crit.ad*se)
if(!WARN)options(warn=0)
output
}




# ----------------------------------------------------------------------------

# qint

# ----------------------------------------------------------------------------

#' @title Confidence Interval for Quantile with Exact Coverage
#'
#' @description
#' Computes a confidence interval for the qth quantile with exact probability
#' coverage. Uses order statistics to construct the interval and reports the
#' actual coverage probability achieved.
#'
#' @param x Numeric vector of data values
#' @param q Numeric value specifying the quantile (0 < q < 1; default: 0.5 for median)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param pr Logical; if TRUE, print warnings about duplicate values (default: FALSE)
#'
#' @return List with components:
#'   \item{ci.low}{Lower confidence limit}
#'   \item{ci.up}{Upper confidence limit}
#'   \item{ci.coverage}{Actual probability coverage achieved}
#'
#' @details
#' The function uses binomial probabilities to determine which order statistics
#' provide coverage closest to (and at least) 1-alpha. If exact coverage cannot
#' be achieved, a warning is printed (when pr=TRUE). With tied values, consider
#' using \code{\link{hdpb}} instead.
#'
#' @seealso \code{\link{hdpb}}, \code{\link{qmjci}}
#'
#' @keywords htest
#' @export
qint<-function(x,q=.5,alpha=.05,pr=FALSE){
#
# Compute a 1-alpha confidence interval for the qth quantile
# The function returns the exact probability coverage.
#
if(pr){
if(sum(duplicated(x)>0))print("Duplicate values detected; use hdpb")
}
n<-length(x)
ii<-floor(q*n+.5)
jj<-ii+1
if(ii<=0)stop("Cannot compute a confidence interval for this q")
if(jj>n)stop("Cannot compute a confidence interval for this q")
jjm<-jj-1
iim<-ii-1
cicov<-pbinom(jjm,n,q)-pbinom(iim,n,q)
while(cicov<1-alpha){
iim<-max(iim-1,0)
jjm<-min(jjm+1,n)
if(iim==0 && jjm==n)break
cicov<-pbinom(jjm,n,q)-pbinom(iim,n,q)
}
xsort<-sort(x)
low<-xsort[iim+1]
hi<-xsort[jjm+1]
if(cicov<1-alpha){
if(pr)print("Warning: Desired probability coverage could not be achieved")
}
list(ci.low=low,ci.up=hi,ci.coverage=cicov)
}


#' @title Quantile-Based Effect Size for Group Differences
#'
#' @description
#' Computes an effect size by determining what quantiles the location measures
#' of each group correspond to in the first group's distribution. The difference
#' in these quantile positions provides a distribution-free effect size measure.
#'
#' @param x Numeric vector for first group
#' @param y Numeric vector for second group
#' @param est Function to compute location measure (default: \code{\link{tmean}})
#' @param ... Additional arguments passed to \code{est}
#'
#' @return Numeric value: difference in quantile positions (q1 - q2) where q1 is
#'   the quantile position of est(x) in x's distribution and q2 is the quantile
#'   position of est(y) in x's distribution
#'
#' @details
#' This function provides an effect size based on how the location measures from
#' each group compare when viewed through the lens of the first group's distribution.
#' Positive values indicate the first group's location is at a higher quantile
#' position than the second group's location (when both are evaluated in the
#' first group's distribution).
#'
#' @seealso \code{\link{tmean}}, \code{\link{akp.effect}}
#'
#' @keywords univar
#' @export
qloc.dif<-function(x,y,est=tmean,...){
#
#  Compute a measure of	location for each group.
#  Using the data in first group, determine what quantiles
#  these measure of location correspond	to.
#  The difference is used as a measure of effect size.
#
m1=est(x)
m2=est(y)
q1=mean(x<=m1)
q2=mean(x<=m2)
delta=q1-q2
delta
}

#' @title Multiple Comparisons for Quantiles Among Independent Groups
#'
#' @description
#' Performs multiple comparisons among independent groups based on a specified
#' quantile. Uses the Harrell-Davis estimator (or trimmed Harrell-Davis) to
#' handle tied values, with familywise error controlled via Hochberg's method.
#'
#' @param x List or data in format suitable for \code{\link{linconpb}}
#' @param q Numeric value specifying the quantile (default: 0.5 for median)
#' @param con Numeric value or matrix of contrasts (default: 0 for pairwise comparisons)
#' @param SEED Logical; if TRUE, set random seed for reproducibility (default: TRUE)
#' @param THD Logical; if TRUE, use trimmed Harrell-Davis estimator (default: FALSE)
#' @param nboot Integer specifying number of bootstrap samples (default: NA)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param HOCH Deprecated parameter (Hochberg's method is always used)
#'
#' @return Results from \code{\link{linconpb}} with quantile-based comparisons
#'
#' @details
#' This function is a wrapper for \code{\link{linconpb}} that specializes in
#' quantile comparisons. The Harrell-Davis estimator is robust to tied values.
#' When THD=TRUE, the trimmed version (\code{\link{thd}}) is used instead of
#' the standard Harrell-Davis estimator (\code{\link{hd}}).
#'
#' @seealso \code{\link{linconpb}}, \code{\link{hd}}, \code{\link{thd}}, \code{\link{QSmcp.ci}}
#'
#' @keywords htest
#' @export
Qmcp<-function(x,q=.5,con=0,SEED=TRUE,THD=FALSE,nboot=NA,alpha=.05,HOCH=FALSE){
#
#  Multiple comparisons among independent groups
#  based on the quantile indicated by the argument
#  q
#
# THD=TRUE would use the trimmed Harrell--Davis estimator
# The default is the Harrell--Davis estimator
#   Familywise error is controlled with the Hochberg's method

#
# The Harrell--Davis estimator is used in order to deal with tied values
#
est=hd
if(THD)est=thd
res=linconpb(x,est=est,q=q,nboot=nboot,SEED=SEED,con=con,method='hoch')
res
}


#' @title Confidence Interval for Quantile Using Maritz-Jarrett Standard Error
#'
#' @description
#' Computes a confidence interval for the qth quantile using the Maritz-Jarrett
#' estimate of the standard error. Supports different standard error estimators
#' via the \code{op} parameter.
#'
#' @param x Numeric vector of data values
#' @param q Numeric value specifying the quantile (0 < q < 1; default: 0.5)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param op Integer (1, 2, or 3) specifying standard error method:
#'   \itemize{
#'     \item 1: Maritz-Jarrett estimator (\code{\link{mjse}})
#'     \item 2: McKean-Schrader median SE (\code{\link{msmedse}}, only for q=0.5)
#'     \item 3: General quantile SE (\code{\link{qse}})
#'   }
#' @param pr Logical; if TRUE, print warning about duplicate values (default: TRUE)
#'
#' @return Numeric vector of length 2: [lower limit, upper limit]
#'
#' @details
#' The Maritz-Jarrett method provides asymptotic standard errors for quantiles.
#' With tied values, consider using \code{\link{hdpb}} instead. When op=2, only
#' the median (q=0.5) is supported.
#'
#' @seealso \code{\link{mjse}}, \code{\link{msmedse}}, \code{\link{qse}},
#'   \code{\link{hdpb}}, \code{\link{qint}}
#'
#' @keywords htest
#' @export
qmjci<-function(x,q=.5,alpha=.05,op=1,pr=TRUE){
#
#   Compute a 1-alpha confidence for qth quantile using the
#   Maritz-Jarrett estimate of the standard error.
#
#   The default quantile is .5.
#   The default value for alpha is .05.
#
x=elimna(x)
if(pr){
if(sum(duplicated(x)>0))print("Duplicate values detected; use hdpb")
}
if(q <= 0 || q>=1)stop("q must be between 0 and 1")
y<-sort(x)
m<-floor(q*length(x)+.5)
crit<-qnorm(1-alpha/2)
qmjci<-vector(mode="numeric",2)
se<-NA
if(op==1)se<-mjse(x)
if(op==2){
if(q!=.5)stop("op=2 works only with q=.5")
se<-msmedse(x)
}
if(op==3)se<-qse(x,q)
if(is.na(se))stop("Something is wrong, op should be 1, 2 or 3")
qmjci[1]<-y[m]-crit*se
qmjci[2]<-y[m]+crit*se
qmjci
}


#' @title Test of Linear Fit Based on Quantile Regression
#'
#' @description
#' Tests the adequacy of a linear quantile regression fit using the method of
#' He and Zhu (2003, JASA, 98, 1013-1022). Uses approximate critical values for
#' efficiency, or simulations for p-value computation when requested.
#'
#' @param x Numeric matrix or vector of predictor variable(s)
#' @param y Numeric vector of response variable
#' @param qval Numeric value specifying the quantile (default: 0.5)
#' @param q Alternative parameter for qval (overrides qval if not NULL)
#' @param nboot Integer specifying number of bootstrap/simulation samples (default: 1000)
#' @param com.pval Logical; if TRUE, compute p-value via simulation (default: FALSE)
#' @param SEED Logical; if TRUE, set random seed for reproducibility (default: TRUE)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param pr Logical; if TRUE, print informative messages (default: TRUE)
#' @param xout Logical; if TRUE, remove outliers in predictors (default: FALSE)
#' @param outfun Function for outlier detection (default: \code{\link{out}})
#' @param chk.table Logical; currently not used (default: FALSE)
#' @param MC Logical; if TRUE, use multicore processing for simulations (default: FALSE)
#' @param ... Additional arguments passed to \code{outfun}
#'
#' @return List with components:
#'   \item{test.stat}{Test statistic value}
#'   \item{crit.value}{Critical value for the test}
#'   \item{p.value}{P-value (NULL unless com.pval=TRUE)}
#'   \item{Decision}{Character string: "Reject" or "Fail to reject"}
#'
#' @details
#' For n<=400, p<=6, and qval=0.5, the function uses tabled critical values for
#' alpha in {0.1, 0.05, 0.025, 0.01}. Otherwise, it computes critical values via
#' simulation. Set com.pval=TRUE to obtain a p-value, which requires more computation.
#' Multicore processing (MC=TRUE) can speed up simulations substantially.
#'
#' @references
#' He, X., & Zhu, L. (2003). A lack-of-fit test for quantile regression.
#' Journal of the American Statistical Association, 98, 1013-1022.
#'
#' @seealso \code{\link{qrchkv2}}, \code{\link{rqfit}}, \code{\link{Qregci}}
#'
#' @keywords htest regression
#' @export
qrchk<-function(x,y,qval=.5,q=NULL,nboot=1000,com.pval=FALSE,SEED=TRUE,alpha=.05,pr=TRUE,
xout=FALSE,outfun=out,chk.table=FALSE,MC=FALSE,...){
#
# Test of a linear fit based on quantile regression
# The method stems from He and Zhu 2003, JASA, 98, 1013-1022.
# Here, resampling is avoided using approximate critical values if
# com.pval=F
#
#  To get a p-value, via simulations, set  com.pval=T
#  nboot is number of simulations used to determine p-value.
#  Execution time can be quite high
#
#  This function quickly determines .1, .05, .025 and .01
#  critical values for n<=400 and p<=6 (p= number of predictors)
#  and when dealing with the .5 quantile.
#  Otherwise, critical values are determined via simulations, which
#  can have high execution time.
#
if(!is.null(q))qval=q
if(pr){
if(!com.pval)print('To get a p-value, set com.pval=T and use MC=T if a multicore processor is available')
print('Reject if test statistic is >= critical value')
}
x<-as.matrix(x)
p<-ncol(x)
pp1<-p+1
yx<-elimna(cbind(y,x)) #Eliminate missing values.
y<-yx[,1]
x<-yx[,2:pp1]
store.it=F
x<-as.matrix(x)
p.val<-NULL
crit.val<-NULL
x<-as.matrix(x)
if(xout){
flag<-outfun(x,...)$keep
x<-x[flag,]
y<-y[flag]
}
# shift the  marginal x values so that the test statistic is
# invariant under changes in location
n<-length(y)
x=standm(x)
if(p<=6){
if(qval==.5){
aval<-c(.1,.05,.025,.01)
aokay<-duplicated(c(alpha,aval))
aokay<-sum(aokay)
if(aokay>0){
crit10<-matrix(c(.0254773,.008372,.00463254,.0023586,.000959315,.00042248,
.00020069,
.039728,.012163,.0069332,.0036521,.001571,.0006882, .0003621,
.055215,.0173357,.009427,.004581,.0021378,.00093787,.00045287,
.075832,.0228556,.0118571,.005924,.00252957,.0011593,.00056706,
.103135,.0298896,.0151193,.0073057,.00305456,.0014430,.000690435,
.12977,.03891,.018989,.009053,.0036326,.001617,.000781457),ncol=6,nrow=7)
crit05<-matrix(c(.031494,.010257,.00626,.00303523,.0012993,.000562247,
.00025972,
.046296,.015066,.00885556,.0045485,.0110904,.00086946,.000452978,
.063368,.0207096546,.010699,.005341,.0025426,.0011305,.000539873,
.085461,.027256,.014067,.0071169,.002954,.0013671,.000660338,
.11055,.03523,.017511,.0084263,.0036533,.0016338,.00081289,
.13692,.043843,.0222425,.0102265,.004283,.0019,.000907241),ncol=6,nrow=7)
crit025<-matrix(c(.0361936,.012518,.007296,.0036084,.00172436,.000725365,
.000327776,
.05315,.017593,.0102389,.0055043,.00227459,.0010062,.000523526,
.07214,.023944,.013689,.0060686,.0028378,.00136379,.000635645,
.093578,.0293223,.0156754,.0086059,.0035195,.001694,.00074467,
.118414,.03885,.0201468,.0094298,.0040263,.00182437,.000916557,
.14271,.047745,.0253974,.011385,.004725,.00207588,.0010191),ncol=6,nrow=7)
crit01<-matrix(c(.0414762,.0146553,.0098428,.0045274,.00219345,.00096244,
.000443827,
.058666,.020007,.01129658,.0063092,.002796,.0011364,.000628054,
.079446,.0267958,.015428,.0071267,.0034163,.0015876,.000734865,
.102736,.0357572,.017786,.0093682,.0042367,.0019717,.000868506,
.125356,.041411,.0234916,.0106895,.0047028,.0020759,.00101052,
.14837,.053246,.027759,.012723,.00528,.002437,.00116065),ncol=6,nrow=7)
if(alpha==.1)critit<-crit10
if(alpha==.05)critit<-crit05
if(alpha==.025)critit<-crit025
if(alpha==.01)critit<-crit01
nvec<-c(10,20,30,50,100,200,400)
nval<-duplicated(c(n,nvec))
nval<-nval[2:7]
if(sum(nval)>0)crit.val<-critit[nval,p]
if(is.null(crit.val)){
if(n<=400){
loc<-rank(c(n,nvec))
xx<-c(1/nvec[loc[1]-1]^1.5,1/nvec[loc[1]]^1.5)
yy<-c(critit[loc[1]-1,p],critit[loc[1],p])
}
icoef<-lsfit(xx,yy)$coef
crit.val<-icoef[1]+icoef[2]/n^1.5
}}}}
if(is.null(crit.val)){
# no critical value found
if(!com.pval){
print('Critical values not available, will set com.pval=T')
print('and compute a p-value')
com.pval<-T
}}
gdot<-cbind(rep(1,n),x)
gdot<-ortho(gdot)
x<-gdot[,2:pp1]
x<-as.matrix(x)
temp<-rqfit(x,y,qval=qval,res=TRUE)
coef<-temp$coef
psi<-NA
psi<-ifelse(temp$residuals>0,qval,qval-1)
rnmat<-matrix(0,nrow=n,ncol=pp1)
ran.mat<-apply(x,2,rank)
flagvec<-apply(ran.mat,1,max)
for(j in 1:n){
flag<-ifelse(flagvec<=flagvec[j],TRUE,FALSE)
flag<-as.numeric(flag)
rnmat[j,]<-apply(flag*psi*gdot,2,sum)
}
rnmat<-rnmat/sqrt(n)
temp<-matrix(0,pp1,pp1)
for(i in 1:n)temp<-temp+rnmat[i,]%*%t(rnmat[i,])
temp<-temp/n
test<-max(eigen(temp)$values)
if(com.pval){
if(SEED)set.seed(2)
xy=list()
p1=p+1
for(i in 1:nboot)xy[[i]]=rmul(n,p=p1)
if(MC)temp3=mclapply(xy,qrchkv2.sub2,qval=qval,mc.preschedule=TRUE)
if(!MC)temp3=lapply(xy,qrchkv2.sub2,qval=qval)
rem=matl(temp3)
p.val=sum(test>=rem)
rem<-sort(rem)
p.val<-1-p.val/nboot
ic<-round((1-alpha)*nboot)
crit.val<-rem[ic]
}
de='Fail to reject'
if( test>=crit.val)de='Reject'
list(test.stat=test,crit.value=crit.val,p.value=p.val,Decision=de)
}




