# qrchkv2.sub2

# ----------------------------------------------------------------------------

#' @title Bootstrap Helper for Quantile Regression Lack-of-Fit Test
#'
#' @description
#' Internal helper function for \code{\link{qrchk}} that computes the test
#' statistic on simulated multivariate normal data for p-value estimation.
#'
#' @param xy Numeric matrix with response in last column, predictors in first columns
#' @param qval Numeric value specifying the quantile
#'
#' @return Numeric value: test statistic from \code{\link{qrchkv2}}
#'
#' @seealso \code{\link{qrchk}}, \code{\link{qrchkv2}}
#'
#' @keywords internal
#' @export
qrchkv2.sub2<-function(xy,qval){
p1=ncol(xy)
p=p1-1
val=qrchkv2(xy[,1:p],xy[,p1],qval=qval)
val
}

#' @title Cross-Validation Helper for Regression Tests
#'
#' @description
#' Internal helper that extracts the minimum p-value from regression confidence
#' intervals, used in cross-validation contexts.
#'
#' @param xy Numeric matrix with two columns (predictor and response)
#' @param regfun Regression function to apply
#' @param null.value Null hypothesis value for testing (default: 0)
#' @param xout Logical; if TRUE, remove outliers (default: FALSE)
#' @param ... Additional arguments passed to \code{\link{regYci}}
#'
#' @return Numeric value: minimum p-value from the regression test
#'
#' @seealso \code{\link{regYci}}
#'
#' @keywords internal
#' @export
regciCV.sub<-function(xy,regfun,null.value=0,xout=FALSE,...){
 pv=regYci(xy[,1],xy[,2],SEED=FALSE,regfun=regfun,null.value=null.value,xout=xout,...)[,5]
 min(pv)
}

#' @title Test Quantile Regression Slopes Equal to Zero
#'
#' @description
#' Tests the hypothesis that quantile regression slopes are zero using bootstrap
#' methods. Can test at a single quantile or multiple quantiles (0.2, 0.5, 0.8)
#' with familywise error control.
#'
#' @param x Numeric matrix or vector of predictor variable(s)
#' @param y Numeric vector of response variable
#' @param nboot Integer specifying number of bootstrap samples (default: 100)
#' @param alpha Numeric value for significance level (default: 0.05)
#' @param qval Numeric value or vector specifying quantile(s) (default: 0.5)
#' @param q Alternative parameter for qval (overrides qval if not NULL)
#' @param SEED Logical; if TRUE, set random seed for reproducibility (default: TRUE)
#' @param pr Logical; if TRUE, print progress messages (default: TRUE)
#' @param xout Logical; if TRUE, remove outliers in predictors (default: FALSE)
#' @param outfun Function for outlier detection (default: \code{\link{outpro}})
#' @param ... Additional arguments passed to \code{outfun}
#'
#' @return List with components:
#'   \item{n}{Sample size}
#'   \item{test}{Test statistics}
#'   \item{se.val}{Standard errors}
#'   \item{crit.val}{Critical value (unadjusted)}
#'   \item{crit.fwe}{Critical value with familywise error control}
#'   \item{est.values}{Estimated slopes}
#'   \item{ci}{Confidence interval matrix}
#'
#' @details
#' For alpha in {0.1, 0.05, 0.025, 0.01}, adjusted critical values provide
#' familywise error control when testing multiple quantiles or multiple predictors.
#' When length(qval) equals 2 or 3, or when p equals 2 or 3, the appropriate
#' multiplicity adjustment is applied.
#'
#' @seealso \code{\link{Qreg}}, \code{\link{qrchk}}, \code{\link{Qindbt.sub}}
#'
#' @keywords htest regression
#' @export
Qregci<-function(x,y,nboot=100,alpha=.05,
qval=.5,q=NULL,SEED=TRUE,pr=TRUE,xout=FALSE,outfun=outpro,...){
#
#  Test the hypothesis that the quantile regression slopes are zero.
#  Can use the .5 quantile regression line only,
#  the .2 and .8 quantile regression lines, or
#  the .2, .5 and .8 quantile regression lines.
#  In the latter two cases, FWE is controlled for alpha=.1, .05, .025 and .01.
#
if(!is.null(q))qval=q
xx<-elimna(cbind(x,y))
np<-ncol(xx)
p<-np-1
y<-xx[,np]
x<-xx[,1:p]
x<-as.matrix(x)
if(xout){
x<-as.matrix(x)
flag<-outfun(x,plotit=FALSE,...)$keep
x<-x[flag,]
y<-y[flag]
}
x<-as.matrix(x)
n<-length(y)
if(SEED)set.seed(2) # set seed of random number generator so that
#             results can be duplicated.
if(pr)print("Taking bootstrap samples. Please wait.")
data<-matrix(sample(length(y),size=length(y)*nboot,replace=TRUE),nrow=nboot)
# determine critical value.
crit<-NA
if(alpha==.1)crit<-1.645-1.19/sqrt(n)
if(alpha==.05)crit<-1.96-1.37/sqrt(n)
if(alpha==.025)crit<-2.24-1.18/sqrt(n)
if(alpha==.01)crit<-2.58-1.69/sqrt(n)
crit.fwe<-crit
if(length(qval)==2 || p==2){
if(alpha==.1)crit.fwe<-1.98-1.13/sqrt(n)
if(alpha==.05)crit.fwe<-2.37-1.56/sqrt(n)
if(alpha==.025)crit.fwe<-2.60-1.04/sqrt(n)
if(alpha==.01)crit.fwe<-3.02-1.35/sqrt(n)
}
if(length(qval)==3 || p==3){
if(alpha==.1)crit.fwe<-2.145-1.31/sqrt(n)
if(alpha==.05)crit.fwe<-2.49-1.49/sqrt(n)
if(alpha==.025)crit.fwe<-2.86-1.52/sqrt(n)
if(alpha==.01)crit.fwe<-3.42-1.85/sqrt(n)
}
if(is.na(crit.fwe)){
print("Could not determine a critical value")
print("Only alpha=.1, .05, .025 and .01 are allowed")
}
if(p==1){
bvec<-apply(data,1,Qindbt.sub,x,y,q=qval)
estsub<-NA
for(i in 1:length(qval)){
estsub[i]<-Qreg(x,y,q=qval[i])$coef[2]
}
if(is.matrix(bvec))se.val<-sqrt(apply(bvec,1,FUN=var))
if(!is.matrix(bvec))se.val<-sqrt(var(bvec))
test<-abs(estsub)/se.val
ci.mat<-matrix(nrow=length(qval),ncol=3)
dimnames(ci.mat)<-list(NULL,c("Quantile","ci.lower","ci.upper"))
ci.mat[,1]<-qval
ci.mat[,2]<-estsub-crit*se.val
ci.mat[,3]<-estsub+crit*se.val
}
if(p>1){
if(length(qval)>1){
print("With p>1 predictors,only the first qval value is used")
}
bvec<-apply(data,1,regboot,x,y,regfun=Qreg,qval=qval[1])
se.val<-sqrt(apply(bvec,1,FUN=var))
estsub<-Qreg(x,y,q=qval[1])$coef
test<-abs(estsub)/se.val
ci.mat<-matrix(nrow=np,ncol=3)
dimnames(ci.mat)<-list(NULL,c("Predictor","ci.lower","ci.upper"))
ci.mat[,1]<-c(0:p)
ci.mat[,2]<-estsub-crit*se.val
ci.mat[,3]<-estsub+crit*se.val
}
list(n=length(y),test=test,se.val=se.val,crit.val=crit,crit.fwe=crit.fwe,est.values=estsub,ci=ci.mat)
}




#' @title Bootstrap Helper for Quantile Regression Slopes
#'
#' @rdname qindbt_sub_functions
#'
#' @description
#' Internal bootstrap helper function that performs quantile regression on a
#' bootstrap sample and returns the slope coefficient(s) for one or more quantiles.
#' Used by \code{\link{Qregci}} for testing.
#'
#' @param isub Integer vector of bootstrap sample indices (length n)
#' @param x Numeric matrix of predictor values
#' @param y Numeric vector of response values
#' @param qval Numeric vector specifying one or more quantiles
#'
#' @return Numeric vector of slope coefficients (excluding intercept), one per quantile
#'
#' @seealso \code{\link{Qregci}}, \code{\link{Qreg}}
#'
#' @keywords internal
#' @export
Qindbt.sub<-function(isub,x,y,qval){
#
#  Perform regression using x[isub] to predict y[isub]
#  isub is a vector of length n,
#  a bootstrap sample from the sequence of integers
#  1, 2, 3, ..., n
#
#  This function is used by other functions when computing
#  bootstrap estimates.
#
#
#  x is assumed to be a matrix containing values of the predictors.
#
xmat<-matrix(x[isub,],nrow(x),ncol(x))
regboot<-NA
for(i in 1:length(qval)){
regboot[i]<-Qreg(xmat,y[isub],q=qval[i])$coef[2]
}
regboot
}




