# rmm.difpb

# ----------------------------------------------------------------------------

#' Pairwise Comparisons for Dependent Groups (Bootstrap on Difference Scores)
#'
#' @description
#' Bootstrap version of \code{\link{rmm.dif}} using percentile bootstrap on
#' difference scores for all pairwise comparisons.
#'
#' @param x Data in matrix format (columns = groups) or list mode.
#' @param est Location estimator function (default: \code{\link{tmean}}).
#' @param alpha Family-wise alpha level (default: 0.05).
#' @param nboot Number of bootstrap samples (default: NA uses function default).
#' @inheritParams common-params
#' @param BH Logical. If \code{TRUE}, use Benjamini-Hochberg; else Hochberg.
#' @param ADJ.CI Logical. If \code{TRUE}, adjust confidence intervals.
#' @param ... Additional arguments passed to \code{est}.
#'
#' @return
#' A list with components:
#' \describe{
#'   \item{\code{n}}{Sample size}
#'   \item{\code{test}}{Matrix with group pairs, p-values, adjusted p-values}
#'   \item{\code{psihat}}{Matrix with estimates and confidence intervals}
#' }
#'
#' @seealso
#'   \code{\link{rmm.dif}}, \code{\link{rmm.marpb}}, \code{\link{rmmcppbd}}
#'
#' @keywords htest robust bootstrap
#' @export
rmm.difpb<-function(x, est=tmean, alpha = 0.05,nboot=NA,SEED=TRUE,BH=FALSE,ADJ.CI=FALSE,...){
#
#  Dependent groups
# Pairwise comparisons,  trimmed means based on difference scores
# ADJ.CI=TRUE: Confidence interval adjusted based on Hochberg  or, if BH=TRUE, Benjamini--Hochberg
#
if(!is.matrix(x))x<-matl(x)
if(!is.matrix(x))stop('Data must be stored in a matrix or in list mode.')
J<-ncol(x)
L=(J^2-J)/2
psihat<-matrix(0,L,5)
testt<-matrix(0,L,4)
dimnames(psihat)<-list(NULL,c('Group','Group','est','ci.lower','ci.upper'))
test<-matrix(NA,L,4)
dimnames(test)<-list(NULL,c('Group','Group','p.value','p.adjust'))
jcom<-0
for (j in 1:J){
for (k in 1:J){
if (j < k){
jcom<-jcom+1
test[jcom,1]<-j
test[jcom,2]<-k
psihat[jcom,1]<-j
psihat[jcom,2]<-k
a=rmmcppbd(x[,j],x[,k],est=est,alpha=alpha,nboot=nboot,SEED=SEED,plotit=FALSE,...)$output
psihat[jcom,3]=a[2]
test[jcom,1]<-j
test[jcom,2]<-k
test[jcom,3]<-a[3]
psihat[jcom,4]=a[5]
psihat[jcom,5]=a[6]
}}}
if(ADJ.CI){
ior=rev(rank(test[,3]))
adj=alpha/c(1:L) #Hoch
if(BH)adj=alpha*(L-1:L+1)
jcom<-0
for (j in 1:J){
for (k in 1:J){
if (j < k){
jcom<-jcom+1
print(adj[ior[[jcom]]])
#a=trimci(x[,j]-x[,k],alpha=adj[ior[[jcom]]],tr=tr)
#a=two.dep.pb(x[,j],x[,k],dif=TRUE,est=est,alpha=adj[ior[[jcom]]],nboot=nboot,SEED=SEED,pr=FALSE,...)
a=rmmcppbd(x[,j],x[,k],est=est,alpha=adj[ior[[jcom]]],nboot=nboot,SEED=SEED,plotit=FALSE,...)$output
psihat[jcom,4]=a[5]
psihat[jcom,5]=a[6]
}}}
}
test[,4]=p.adjust(test[,3],method='hoch')
if(BH)test[,4]=p.adjust(test[,3],method='BH')
nval=nrow(x)
list(n=nval,test=test,psihat=psihat)
}




