# t1waysub

# ----------------------------------------------------------------------------

#' Welch Test Statistic for Trimmed Means (Internal)
#'
#' @description
#' Internal function used by \code{t1waybt} to compute the Welch test statistic
#' for trimmed means.
#'
#' @param tm Numeric vector of trimmed means for each group
#' @param sqse Numeric vector of squared standard errors for each group
#' @param hval Numeric vector of effective sample sizes (h-values) for each group
#'
#' @details
#' Computes the heteroscedastic one-way ANOVA F-statistic using weighted means
#' with weights inversely proportional to the squared standard errors.
#'
#' @return Numeric. The Welch test statistic
#'
#' @keywords internal
t1waysub<-function(tm,sqse,hval){
#
#  Used by t1waybt to compute Welch test statistic based on trimmed means
#  and squared standard errors stored in tm and sqse
#
w<-1/sqse
uval<-sum(w)
xtil<-sum(w*tm)/uval
A<-sum(w*(tm-xtil)^2)/(length(tm)-1)
B<-sum((1-w/uval)^2/(hval-1))
t1waysub<-A/(B+1)
t1waysub
}

#' Compute P-Value for Linear Contrasts (Internal)
#'
#' @description
#' Internal function to compute p-values for linear contrasts using an iterative
#' search algorithm.
#'
#' @param cmat Contrast matrix
#' @param tmeans Vector of trimmed means
#' @param v Variance estimates
#' @param h Effective sample sizes
#'
#' @details
#' Uses an iterative bisection search to find the p-value by comparing test
#' statistics to critical values at progressively finer alpha levels.
#'
#' @return Numeric. P-value for the contrast test
#'
#' @keywords internal
t3pval<-function(cmat,tmeans,v,h){
alph<-c(1:99)/100
for(i in 1:99){
irem<-i
chkit<-johan(cmat,tmeans,v,h,alph[i])
if(chkit$teststat>chkit$crit)break
}
p.value <- irem/100
        if(p.value <= 0.1) {
                iup <- (irem + 1)/100
                alph <- seq(0.001, iup, 0.001)
                for(i in 1:length(alph)) {
                        p.value <- alph[i]
                        chkit<-johan(cmat,tmeans,v,h,alph[i])
if(chkit$teststat>chkit$crit)break
                }
        }
  if(p.value <= 0.001) {
                alph <- seq(0.0001, 0.001, 0.0001)
                for(i in 1:length(alph)) {
                        p.value <- alph[i]
chkit<-johan(cmat,tmeans,v,h,alph[i])
if(chkit$teststat>chkit$crit)break
                }
        }
p.value
}

#' Confidence Interval for Tail Probability P(X-Y < threshold)
#'
#' @description
#' Computes a bootstrap confidence interval for the probability that the difference
#' between two independent variables falls below a specified threshold.
#'
#' @param x Numeric vector for first group
#' @param y Numeric vector for second group
#' @param pts Numeric. Threshold value. If NULL, estimated as qth quantile of differences
#' @param q Numeric. Quantile to use if \code{pts} is NULL (default: 0.25)
#' @param nboot Integer. Number of bootstrap samples (default: 1000)
#' @param estfun Function. Quantile estimation function (default: \code{hdmq})
#' @param alpha Numeric. Significance level (default: 0.05)
#' @param SEED Logical. If TRUE, set random seed to 2 for reproducibility (default: TRUE)
#'
#' @details
#' This function estimates P(X - Y < threshold) and computes a percentile bootstrap
#' confidence interval for this probability. If \code{pts} is not specified, it is
#' estimated as the qth quantile of all pairwise differences.
#'
#' The bootstrap resamples independently from X and Y, computes all pairwise
#' differences for each bootstrap sample, and estimates the probability for each.
#'
#' @return List with components:
#'   \item{Est}{Estimated probability P(X - Y < threshold)}
#'   \item{ci}{Two-element vector with lower and upper confidence limits}
#'
#' @examples
#' x <- rnorm(30)
#' y <- rnorm(30, mean = 0.5)
#' tailci(x, y, pts = 0, nboot = 500)
#'
#' @seealso \code{\link{tailci.reverse}}, \code{\link{hdmq}}
#' @keywords htest
#' @export
tailci<-function(x,y,pts=NULL,q=.25, nboot=1000,estfun=hdmq,alpha=.05,SEED=TRUE){
#
#   If pts is specified, the goal is to compute a confidence interval
# P(x-y< pts). If pts is not specified, it is taken to be an estimate of the qth quantile,
# q=.25 is the default.
#
if(SEED)set.seed(2)
x<-x[!is.na(x)]
y<-y[!is.na(y)]
n1=length(x)
n2=length(y)
qe=NA
m=as.vector(outer(x,y,FUN='-'))
if(is.null(pts))e=estfun(m,q)
else e=pts
est=mean(m<=e)
V=NA
for(i in 1:nboot){
id1=sample(n1,replace=TRUE)
id2=sample(n2,replace=TRUE)
M=as.vector(outer(x[id1],y[id2],FUN='-'))
V[i]=mean(M<=e)
}
crit<-alpha/2
icl<-round(crit*nboot)+1
icu<-nboot-icl
a=sort(V)
ci=a[icl]
ci[2]=a[icu]
list(Est=est,ci=ci)
}

difqci=tailci


#' Confidence Interval for Tail Probability P(X-Y > threshold)
#'
#' @description
#' Computes a bootstrap confidence interval for the probability that the difference
#' between two independent variables exceeds a specified threshold.
#'
#' @param x Numeric vector for first group
#' @param y Numeric vector for second group
#' @param pts Numeric. Threshold value. If NULL, estimated as qth quantile of differences
#' @param q Numeric. Quantile to use if \code{pts} is NULL (default: 0.25)
#' @param nboot Integer. Number of bootstrap samples (default: 1000)
#' @param estfun Function. Quantile estimation function (default: \code{hdmq})
#' @param alpha Numeric. Significance level (default: 0.05)
#' @param SEED Logical. If TRUE, set random seed to 2 for reproducibility (default: TRUE)
#'
#' @details
#' This function estimates P(X - Y > threshold) and computes a percentile bootstrap
#' confidence interval for this probability. It is the complement of \code{tailci},
#' testing for differences in the opposite direction.
#'
#' If \code{pts} is not specified, it is estimated as the qth quantile of all
#' pairwise differences.
#'
#' @return List with components:
#'   \item{Est}{Estimated probability P(X - Y > threshold)}
#'   \item{ci}{Two-element vector with lower and upper confidence limits}
#'
#' @examples
#' x <- rnorm(30, mean = 1)
#' y <- rnorm(30)
#' tailci.reverse(x, y, pts = 0, nboot = 500)
#'
#' @seealso \code{\link{tailci}}, \code{\link{hdmq}}
#' @keywords htest
#' @export
tailci.reverse<-function(x,y,pts=NULL,q=.25, nboot=1000,estfun=hdmq,alpha=.05,SEED=TRUE){
  #
  #   If pts is specified, the goal is to compute a confidence interval
  # P(x-y> pts). If pts is not specified, it is taken to be an estimate of the qth quantile,
  # q=.25 is the default.
  #
  if(SEED)set.seed(2)
  x<-x[!is.na(x)]
  y<-y[!is.na(y)]
  n1=length(x)
  n2=length(y)
  qe=NA
  m=as.vector(outer(x,y,FUN='-'))
  if(is.null(pts))e=estfun(m,q)
  else e=pts
  est=mean(m>=e)
  V=NA
  for(i in 1:nboot){
    id1=sample(n1,replace=TRUE)
    id2=sample(n2,replace=TRUE)
    M=as.vector(outer(x[id1],y[id2],FUN='-'))
    V[i]=mean(M>=e) 
  }
  crit<-alpha/2
  icl<-round(crit*nboot)+1
  icu<-nboot-icl
  a=sort(V)
  ci=a[icl]
  ci[2]=a[icu]
  list(Est=est,ci=ci)
}

#' Tamhane's Two-Stage Multiple Comparison Procedure
#'
#' @description
#' Implements the first stage of Tamhane's two-stage multiple comparison method,
#' which determines required sample sizes for achieving desired confidence
#' interval precision.
#'
#' @param x Data in list or matrix format for first stage
#' @param x2 Data in list or matrix format for second stage (optional)
#' @param cil Numeric. Desired length of confidence intervals
#' @param crit Numeric. Critical value from appropriate distribution
#'
#' @details
#' Tamhane's method is a two-stage procedure for multiple comparisons that:
#' \enumerate{
#'   \item Uses first-stage data to estimate variances and determine required
#'         sample sizes to achieve the desired CI length
#'   \item If second-stage data are provided, combines both stages to compute
#'         confidence intervals for all pairwise comparisons
#' }
#'
#' The confidence interval length (\code{cil}) is the total distance between
#' the upper and lower limits.
#'
#' @return List with components:
#'   \item{n.vec}{Vector of required sample sizes for each group}
#'   \item{ci.mat}{Matrix of confidence intervals for pairwise comparisons
#'     (only if \code{x2} is provided). Each row contains: Group 1, Group 2,
#'     lower limit, upper limit}
#'
#' @examples
#' # First stage only - determine required sample sizes
#' x <- list(rnorm(10), rnorm(10), rnorm(10))
#' result <- tamhane(x, cil = 1.0, crit = 2.5)
#'
#' @references
#' Tamhane, A. C. (1977). Multiple comparisons in model I one-way ANOVA with
#' unequal variances. Communications in Statistics-Theory and Methods, 6, 15-32.
#'
#' @seealso \code{\link{T.HSD}}, \code{\link{lincon}}
#' @keywords htest
#' @export
tamhane<-function(x,x2=NA,cil=NA,crit=NA){
#
# First stage of Tamhane's method
#
# x contains first stage data
# x2 contains second stage data
#
# cil is the desired length of the confidence intervals.
# That is, cil is the distance between the upper and lower
# ends of the confidence intervals.
#
if(is.matrix(x))x<-listm(x)
if(!is.list(x))stop("Data must be stored in list mode or in matrix mode.")
J<-length(x)
tempn<-0
svec<-NA
for(j in 1:J){
temp<-x[[j]]
temp<-temp[!is.na(temp)] # Remove missing values.
tempn[j]<-length(temp)
x[[j]]<-temp
svec[j]<-var(temp)
}
A<-sum(1/(tempn-1))
df<-J/A
paste("The degrees of freedom are:",df)
if(is.na(crit))stop("Enter a critical value and reexecute this function")
if(is.na(cil))stop("To proceed, you must specify the length of the confidence intervals.")
d<-(cil/(2*crit))^2
n.vec<-NA
for(j in 1:J){
n.vec[j]<-max(tempn[j]+1,floor(svec[j]/d)+1)
}
ci.mat<-NA
if(!is.na(x2[1])){
if(is.matrix(x2))x2<-listm(x2)
if(!is.list(x2))stop("Data must be stored in list mode or in matrix mode.")
TT<-NA
U<-NA
J<-length(x)
nvec2<-NA
for(j in 1:length(x)){
nvec2[j]<-length(x2[[j]])
if(nvec2[j] <n.vec[j]-tempn[j]){
paste("The required number of observations for group",j," in the second stage is ")
paste(n.vec[j]-tempn[j]," but only ",nvec2[j]," are available")
stop()
}
TT[j]<-sum(x[[j]])
U[j]<-sum(x2[[j]])
print(c(TT[j],U[j],nvec2[j]))
}
b<-sqrt(tempn*((tempn+nvec2)*d-svec)/(nvec2*svec))
b<-(b+1)/(tempn+nvec2)
print(c(b,svec))
xtil<-TT*(1-nvec2*b)/tempn+b*U
print(xtil)
jall<-(J^2-J)/2
ci.mat<-matrix(0,ncol=4,nrow=jall)
dimnames(ci.mat)<-list(NULL,c("Group","Group","ci.low","ci.high"))
ic<-0
for(j in 1:J){
for(k in 1:J){
if(j<k){
ic<-ic+1
ci.mat[ic,1]<-j
ci.mat[ic,2]<-k
ci.mat[ic,3]<-xtil[j]-xtil[k]-cil/2
ci.mat[ic,4]<-xtil[j]-xtil[k]+cil/2
}}}}
list(n.vec=n.vec,ci.mat=ci.mat)
}




